/* ── LESSON ───────────────────────────────────────────────── */

function acRenderLesson(){
var ls=null,modTitle='';
for(var i=0;i<AC_COURSE.modules.length;i++){
 for(var j=0;j<AC_COURSE.modules[i].lessons.length;j++){
  if(AC_COURSE.modules[i].lessons[j].id===AC.lid){ls=AC_COURSE.modules[i].lessons[j];modTitle=AC_COURSE.modules[i].title;break}
 }
}
if(!ls)return '<div class="acad-wrap" style="padding:40px 20px"><p>المحاضرة غير موجودة.</p></div>';

var content=acGetContent(AC.lid);
if(!content){
return '<div class="acad-lesson-pg">'+
'<div class="acad-breadcrumb">'+
'<span role="button" onclick="NAcademy.goHome()">الأكاديمية</span>'+
'<span class="sep">›</span><span>'+ls.title+'</span></div>'+
'<div class="acad-coming">'+
'<div class="acad-coming-ico">'+acIco('wrench',30)+'</div>'+
'<h4>قيد الإعداد</h4>'+
'<p>هذه المحاضرة قيد التحرير حالياً وستكون متاحة قريباً.<br>يمكنك الاطلاع على المحاضرات المتاحة في الوقت الحالي.</p>'+
'</div>'+
'<div class="acad-lnav">'+
'<button class="acad-btn acad-btn-ghost" onclick="NAcademy.goHome()">‹ العودة للدورة</button>'+
'</div></div>'}

var done=acDone(ls.id);
return '<div class="acad-lesson-pg">'+
'<div class="acad-breadcrumb">'+
'<span role="button" onclick="NAcademy.goHome()">الأكاديمية</span>'+
'<span class="sep">›</span>'+
'<span role="button" onclick="NAcademy.goHome()">'+modTitle+'</span>'+
'<span class="sep">›</span>'+
'<span>'+ls.title+'</span></div>'+
'<div class="acad-lesson-hdr">'+
'<div class="acad-lesson-kicker">'+acIco('clock',13)+' '+ls.dur+' &nbsp;·&nbsp; قراءة وتطبيق</div>'+
'<div class="acad-lesson-h1">'+ls.title+'</div>'+
'</div>'+
content+
'<div class="acad-lnav">'+
'<button class="acad-btn acad-btn-ghost" onclick="NAcademy.goHome()">‹ العودة للدورة</button>'+
'<button class="acad-btn acad-btn-ghost" onclick="NAcademy.downloadLessonPDF(\''+ls.id+'\',this)">'+acIco('download',14)+' تحميل PDF</button>'+
'<button class="acad-btn acad-btn-primary" onclick="NAcademy.goQuiz(\''+ls.id+'\')">'+
(done?'إعادة الاختبار '+acIco('refresh',13):'الاختبار ←')+'</button>'+
'</div></div>'}

/* ── QUIZ ENGINE ──────────────────────────────────────────── */

var AC_QUIZZES={
p1:{title:'اختبار: مفاهيم الآفات الزراعية',questions:[
{q:'مزارع يجد أعداداً كبيرة من حشرة ما على محصوله، لكن الإنتاج لم يتأثر حتى الآن. ما القرار الأصح بناءً على مبدأ عتبة الضرر؟',
opts:['رش فوري وقائي لمنع أي ضرر مستقبلي','مراقبة يومية دقيقة دون تدخل الآن','إزالة النباتات المصابة','حرث الأرض وإعادة الزراعة'],
cor:1,exp:'إذا لم تبلغ الكثافة الحشرية عتبة الضرر الاقتصادي، فالتدخل غير مبرر مالياً وبيئياً. المراقبة المنتظمة هي الإجراء الصحيح حتى تُرصد التغيرات في الكثافة.'},
{q:'أيّ من هذه الكائنات لا يُعدّ آفة زراعية بالتعريف العلمي الدقيق؟',
opts:['المن (Aphids)','دعسوقة سبع النقاط','دودة الحشد الخريفية','ذبابة الثمار'],
cor:1,exp:'دعسوقة سبع النقاط مفترس طبيعي يتغذى على المن ويُعدّ عدوّاً حيوياً مفيداً. الآفة بالتعريف هي الكائن الذي يُلحق ضرراً اقتصادياً بالمحصول، وهذا لا ينطبق على الدعسوقة.'},
{q:'شخّص الحالة: مزارع طماطم يلاحظ اصفرار أوراق الذروة وتجعّدها مع إفرازات لزجة. ما الآفة الأرجح؟',
opts:['دودة الحشد','المن','ذبابة الفاكهة','الدودة الحارقة'],
cor:1,exp:'تجعّد أوراق الذروة + الإفرازات اللزجة (العسل الندي) = علامتان مميزتان للمن. المن يمتص عصارة البراعم والأوراق الحديثة مما يتسبب في تشوّهها، ويفرز مادة سكرية تُشجع على نمو العفن الأسود.'},
{q:'ما الفرق الجوهري بين مفهوم "المكافحة" ومفهوم "الإبادة" في علم الآفات؟',
opts:['لا فرق بينهما، المصطلحان مترادفان','المكافحة تُبقي الآفة دون العتبة الاقتصادية، الإبادة تستهدف القضاء الكامل','الإبادة أرخص وأسرع من المكافحة','المكافحة تستخدم مبيدات أكثر تركيزاً'],
cor:1,exp:'الإبادة الكاملة للآفات مستحيلة عملياً ومكلفة ومضرة بيئياً. الهدف العلمي الصحيح هو الإبقاء على كثافة الآفة أقل من العتبة الاقتصادية لحماية المحصول دون الإخلال بالتوازن البيئي.'},
{q:'ما أكثر عوامل انتشار الآفات تأثيراً في ظروف الزراعة المصرية الحديثة؟',
opts:['استخدام التسميد العضوي','زراعة محصول واحد على مساحات واسعة (monoculture)','الري بالغمر','استخدام البذور المحلية'],
cor:1,exp:'زراعة محصول واحد على مساحات شاسعة توفر مصدراً غذائياً متواصلاً للآفات وتُغيب التنوع البيولوجي الضروري لوجود الأعداء الطبيعية. هذا هو المسبب الأساسي لانفجارات الآفات في الزراعة التجارية الحديثة.'}
]},
p2:{title:'اختبار: عتبة الضرر الاقتصادي',questions:[
{q:'حقل قطن به 4 حشرات من لكل نبتة والعتبة الاقتصادية المحددة 10 حشرات/نبتة. ما القرار الأمثل؟',
opts:['رش فوري لأن الإصابة بدأت','مراقبة مكثفة كل يومين مع تسجيل أعداد الحشرات','إزالة النباتات المصابة','لا شيء، الإصابة بعيدة جداً'],
cor:1,exp:'الكثافة الحالية (4 حشرات) أقل من نصف العتبة الاقتصادية (10 حشرات). لكنها ليست صفراً، لذا المراقبة المنتظمة ضرورية لرصد الزيادة. الرش غير مبرر الآن ويُكلّف المزارع بدون ضرورة ويقتل الأعداء الطبيعية.'},
{q:'أيّ من هذه العوامل يرفع عتبة الضرر الاقتصادي؟',
opts:['ارتفاع سعر المبيد في السوق','انخفاض سعر المحصول عند البيع','كلاهما يرفع العتبة','لا علاقة لأيّ منهما بالعتبة'],
cor:2,exp:'معادلة العتبة = تكلفة المكافحة ÷ (قيمة المحصول × نسبة إنقاذه). عندما ترتفع تكلفة المكافحة أو ينخفض سعر المحصول، ترتفع العتبة: تصبح المكافحة مربحة فقط عند مستويات إصابة أعلى.'},
{q:'مهندس زراعي يُقرر الرش الوقائي قبل ظهور أي إصابة. ما أكبر مشكلة في هذا القرار؟',
opts:['لا مشكلة، الوقاية أفضل من العلاج دائماً','تكلفة غير مبررة وقتل الأعداء الطبيعية وتطوير مقاومة للمبيدات','الجرعة الوقائية غالباً أعلى من العلاجية','الرش الوقائي ممنوع قانونياً في مصر'],
cor:1,exp:'الرش غير المبرر يُهدر الأموال، يقضي على الأعداء الطبيعية للآفات، يُسرّع ظهور مقاومة كيميائية، ويُبقي بقايا كيميائية زائدة في المحصول. المبدأ العلمي الصحيح: لا تتدخل إلا عند بلوغ العتبة الاقتصادية.'},
{q:'لماذا تختلف عتبة الضرر الاقتصادي من مرحلة نمو لأخرى في نفس المحصول؟',
opts:['لأن أنواع الآفات تتغير في كل مرحلة','لأن حساسية النبات للضرر ومردوده الاقتصادي يتغيران بحسب المرحلة','لأن المبيدات تتغير فاعليتها بحسب درجة الحرارة','لا تختلف العتبة طوال موسم النمو'],
cor:1,exp:'الضرر في مرحلة الإزهار والعقد أخطر بكثير مما هو عليه في مرحلة النضج. النبات في مرحلة الإزهار أكثر حساسية وفقدان الأزهار يعني فقدان مباشر في الإنتاج، مما يخفّض عتبة الضرر ويستوجب تدخلاً أبكر.'},
{q:'ما المقصود بـ "المستوى الحرج" (Action Threshold) وكيف يختلف عن عتبة الضرر الاقتصادي؟',
opts:['هما نفس الشيء ومترادفان','المستوى الحرج أقل قليلاً من العتبة الاقتصادية ليتيح وقتاً للتخطيط والتدخل','المستوى الحرج أعلى من العتبة الاقتصادية','المستوى الحرج يُحدد نقطة انقراض الآفة'],
cor:1,exp:'المستوى الحرج هو الكثافة التي يجب عندها اتخاذ قرار المكافحة الفعلية، وهو أقل بقليل من عتبة الضرر الاقتصادي. الهدف: إتاحة وقت كافٍ للتخطيط وشراء المبيدات وتنفيذ المكافحة قبل أن تصل الإصابة إلى مستوى الضرر الفعلي.'}
]},
p3:{title:'اختبار: الحشرات الماصة',questions:[
{q:'تجد في حقل فلفل أوراقاً ملتفة للأسفل مع مسحوق فضي على أسطح الأوراق. ما الآفة الأرجح؟',
opts:['المن','التربس (Thrips)','الذبابة البيضاء','دودة الحشد'],
cor:1,exp:'المسحوق الفضي على أسطح الأوراق هو علامة مميزة جداً للتربس. التربس يكشط خلايا البشرة ويمتص محتوياتها، مخلّفاً مناطق فضية اللون. التفاف الأوراق قد ينتج عن أي حشرة ماصة، لكن المسحوق الفضي مميز للتربس.'},
{q:'ما الخطر الثانوي الأشد ضرراً للمن بعد الامتصاص المباشر للعصارة؟',
opts:['إتلاف جهاز الجذور','نقل الفيروسات النباتية من نبات لآخر','حجب الضوء عن الأوراق','تسميم التربة بالإفرازات'],
cor:1,exp:'المن ناقل ممتاز للفيروسات النباتية. لعابه يحمل جزيئات الفيروس وينقلها إلى النبات السليم خلال ثوانٍ من الوخز. بعض الفيروسات التي ينقلها المن - كفيروسات الموزاييك - تسبب أضراراً في الإنتاج أشد من الامتصاص المباشر.'},
{q:'في بيت محمي مزروع بالطماطم، ما أفضل توقيت لرش المبيد ضد الذبابة البيضاء؟',
opts:['منتصف النهار عند الحرارة القصوى','الصباح الباكر أو بعد الغروب','لا يهم الوقت في البيت المحمي','عند ظهور أولى الحشرات البالغة فقط'],
cor:1,exp:'الرش صباحاً أو مساءً يضمن: تبخّراً أقل للمبيد، فاعلية أعلى لأن درجات الحرارة المنخفضة تُبطئ استقلاب الحشرة للمبيد، وتقليل الضرر على الحشرات الملقحة النافعة التي تكون نشطة وقت الذروة الحرارية.'},
{q:'مزارع رش مبيداً كيميائياً ضد الذبابة البيضاء فتحسّن الوضع ثم عادت الإصابة أشد. ما السبب العلمي لهذه الظاهرة؟',
opts:['جرعة المبيد كانت منخفضة جداً','المبيد قتل الأعداء الطبيعية فأُتيح للذبابة البيضاء التكاثر دون قيود','نوع المبيد غير مناسب للذبابة البيضاء','الإصابة جاءت من حقل مجاور بعد الرش'],
cor:1,exp:'هذه ظاهرة "تفجّر الآفة بعد الرش" (Post-Pesticide Resurgence). المبيد أبادت الأعداء الطبيعية كنبات الحشرات والطفيليات الصغيرة. الذبابة البيضاء تتعافى في أسبوع لكن أعداءها الطبيعية تحتاج أسابيع للعودة، فيجد الآفة مجالاً مفتوحاً.'},
{q:'أيّ ظرف بيئي يُهيئ أكثر لانفجار أعداد التربس في البيوت المحمية؟',
opts:['رطوبة نسبية عالية وحرارة منخفضة','جفاف وحرارة مرتفعة وضعف مائي على النبات','تهوية جيدة ودرجة حرارة معتدلة','كثرة المطر وبرودة الجو'],
cor:1,exp:'التربس يتكاثر بسرعة هائلة في الحرارة العالية والجفاف. الرطوبة العالية (فوق 75%) تُشجع الفطريات الممرضة للتربس مثل Beauveria bassiana وتُعيق تطور البيض. النباتات المجهدة مائياً تُقلل دفاعاتها وتُسهّل الإصابة.'}
]},
p4:{title:'اختبار: الحشرات القارضة',questions:[
{q:'مزارع يجد شتلات ذرة مقطوعة من عند سطح التربة في الصباح الباكر بينما النباتات سليمة في المساء. ما الآفة الأرجح؟',
opts:['الدودة الحارقة (Agrotis ipsilon)','دودة القطن (Helicoverpa armigera)','التربس','المن'],
cor:0,exp:'القطع الليلي لسيقان الشتلات من عند سطح التربة هو العلامة المميزة للدودة الحارقة. تُكمل يرقاتها دورة حياتها في التربة نهاراً وتخرج ليلاً لقضم سيقان الشتلات. الاسم الإنجليزي Black Cutworm مشتق من هذا السلوك.'},
{q:'لماذا تُعدّ دودة القطن (Helicoverpa armigera) من أخطر آفات المحاصيل؟',
opts:['لأنها تعيش في التربة فقط','لأنها متعددة المضيفين وتُصيب أكثر من 180 نوعاً من النباتات وتطوّر مقاومة سريعة للمبيدات','لأنها تنقل الفيروسات فقط','لأن تطور المقاومة لديها مستحيل'],
cor:1,exp:'Helicoverpa armigera هي من أكثر آفات العالم خطورة اقتصادياً لأنها: تتغذى على أكثر من 180 نوعاً نباتياً، تُصيب الثمار والبراعم والقرون مباشرة، وتطوّر مقاومة كيميائية بسرعة مذهلة بسبب قدرتها الجينية على تحييد المبيدات. خسائرها الاقتصادية العالمية تتجاوز ملياري دولار سنوياً.'},
{q:'ما الأسلوب الأنجع لرصد وجود دودة الحشد الخريفية (Spodoptera frugiperda) في الذرة؟',
opts:['فحص الوجه السفلي للأوراق العجوزة','فحص قلب النبات (القمة النامية) لوجود براز دقيق وثقوب صغيرة','فحص جذور النبات','ملاحظة لون السيقان'],
cor:1,exp:'دودة الحشد الخريفية تُفضّل القمة النامية وقلب النبات. وجود براز دقيق يشبه نشارة الخشب داخل قلب الذرة مع ثقوب دقيقة على الأوراق الحديثة هي العلامة الأولى للإصابة المبكرة قبل أن تكبر اليرقة وتسبب ضرراً أشد.'},
{q:'مزارع قطن يجد ثقوباً دائرية في قوز القطن الأخضر مع إفرازات غير منتظمة. ما الآفة الأرجح والقرار الصحيح؟',
opts:['دودة الحشد الخريفية - رش فوري','دودة القطن (Helicoverpa armigera) - رش مبيد بيولوجي أو كيميائي مناسب بعد التأكد من تجاوز العتبة الاقتصادية','البياض الدقيقي - رش فطرية','المن - رش حشري'],
cor:1,exp:'الثقوب الدائرية في القوز مع الإفرازات هي بصمة Helicoverpa. القرار الصحيح: أولاً التحقق من كثافة الإصابة بالعد الحقلي مقارنةً بالعتبة الاقتصادية (2-3 يرقات/100 قوز)، ثم الاختيار بين Bt أو مبيدات الأوكزاديازين أو الديامايد وفق مرحلة اليرقة.'},
{q:'لماذا يُنصح بالرش في الساعات الأولى من المساء عند مكافحة الدودة الحارقة تحديداً؟',
opts:['لأن المبيد يفقد فاعليته في الحرارة','لأن الدودة الحارقة تخرج للتغذية ليلاً فيتلامس المبيد مع اليرقات في ذروة نشاطها','لأن المبيد يمتص الرطوبة الليلية ويصبح أكثر فاعلية','لا فرق في التوقيت'],
cor:1,exp:'الدودة الحارقة ذات نشاط ليلي صرف. تختبئ في التربة نهاراً ثم تخرج بعد الغروب لقضم الشتلات. الرش المسائي يضمن تلامس المبيد مع اليرقات وهي في ذروة حركتها ونشاطها، مما يرفع كفاءة المكافحة بشكل ملحوظ مقارنةً بالرش الصباحي.'}
]},
p5:{title:'اختبار: الأكاروسات والنيماتودا',questions:[
{q:'مزارع خيار يلاحظ شبكة دقيقة جداً على الوجه السفلي للأوراق مع اصفرار دقيق على السطح العلوي. ما الآفة؟',
opts:['البياض الدقيقي','العنكبوت الأحمر (Tetranychus urticae)','نيماتودا الجذور','التربس'],
cor:1,exp:'الشبكة الدقيقة (النسيج الحريري) على الوجه السفلي للأوراق مع نقط صفراء على السطح العلوي هي العلامة المميزة للعنكبوت الأحمر. يصنع الأكاروس هذا النسيج لحماية مستعمراته. الاصفرار الدقيق ناتج عن ثقب الخلايا وامتصاص محتوياتها.'},
{q:'ما السبب الرئيسي لصعوبة مكافحة الأكاروسات بالمبيدات الحشرية التقليدية؟',
opts:['الأكاروسات تعيش تحت التربة','الأكاروسات ليست حشرات بل أراكنيدات (عنكبوتيات) لا تستجيب لمعظم المبيدات الحشرية','الأكاروسات تطور مقاومة لكل المبيدات في أيام','الأكاروسات محمية بقشرة صلبة'],
cor:1,exp:'الأكاروسات عنكبوتيات (أراكنيدات) وليست حشرات، لذا المبيدات الحشرية التقليدية كالبايريثرويدات والأورجانوفوسفيت غالباً لا تُؤثر عليها بل قد تقتل أعداءها الطبيعية. يجب استخدام مواد مخصصة تُسمى Acaricides مثل Abamectin وFenpyroximate وBifenazate.'},
{q:'نبات طماطم تظهر عليه عقد صغيرة على الجذور مع ذبول عام رغم كفاءة الري. ما التشخيص الأرجح؟',
opts:['جفاف التربة','نيماتودا تعقّد الجذور (Meloidogyne spp.)','أمراض فطرية في الجذور','نقص التسميد'],
cor:1,exp:'العقد (الغلل) على الجذور هي العلامة المرضية الكلاسيكية لنيماتودا Meloidogyne (Root-knot nematode). النيماتودا تحث الخلايا الجذرية على التضخم لتكوين خلايا عملاقة تتغذى عليها، فتعيق امتصاص الماء والغذاء مما يسبب الذبول رغم كفاءة الري.'},
{q:'ما الأسلوب الأكثر فاعلية واستدامة لإدارة نيماتودا الجذور في المزارع المصرية؟',
opts:['رش مبيدات كيميائية بتركيزات عالية على الأوراق','التغميس الكيميائي للتربة بالميثيل برومايد فقط','تكامل الأساليب: تعقيم شمسي للتربة + دورة زراعية + أصناف مقاومة + تسميد عضوي + تطبيق نيماتيسيدات عند الضرورة','لا علاج لنيماتودا الجذور'],
cor:2,exp:'إدارة نيماتودا الجذور تتطلب نهجاً تكاملياً: التعقيم الشمسي (رفع حرارة التربة بالبلاستيك الشفاف صيفاً) يقتل 80-90% من الأفراد، والدورة الزراعية مع محاصيل غير عائلة تقطع دورة الحياة، والأصناف المقاومة (تحمل الجين Mi في الطماطم) تمنع التكاثر. الاعتماد على المبيدات وحدها غير مستدام.'},
{q:'ما الاختلاف الجوهري بين العنكبوت الأحمر والعنكبوت الأبيض (Polyphagotarsonemus latus) من ناحية الضرر والتشخيص؟',
opts:['لا فرق، كلاهما يُسبب نفس الأعراض','العنكبوت الأحمر يُسبب شبكة مرئية واصفراراً، بينما العنكبوت الأبيض أصغر بكثير ويُسبب تشوّهاً وتقزّماً في القمم النامية دون شبكة مرئية','العنكبوت الأبيض يُصيب الجذور فقط','العنكبوت الأحمر أصغر وغير مرئي'],
cor:1,exp:'تمييز دقيق ومهم: العنكبوت الأحمر (0.4-0.5 مم) مرئي بالعين المجردة ويصنع شبكة حريرية. العنكبوت الأبيض أصغر بكثير (0.1-0.2 مم) ولا يُرى بالعين المجردة ولا يصنع شبكة، لكنه يُحقن سموماً في القمم النامية تُسبب تشوهاً مميزاً (الأوراق الحديثة تنكمش وتتصلب وتأخذ شكلاً غير طبيعي).'}
]},
p6:{title:'اختبار: البياض الدقيقي والزغبي',questions:[
{q:'مزارع خيار يجد مسحوقاً أبيض على السطح العلوي للأوراق القديمة ينمحي بالحك. ما التشخيص؟',
opts:['البياض الزغبي (Downy mildew)','البياض الدقيقي (Powdery mildew)','رواسب كلسية من مياه الري','التربس'],
cor:1,exp:'المسحوق الأبيض الناعم على السطح العلوي للأوراق الذي ينمحي بالحك هو ميزة البياض الدقيقي. هذا المسحوق هو في الحقيقة جراثيم فطرية (كونيديا) ظاهرة خارج النسيج النباتي. البياض الزغبي يظهر على السطح السفلي ولونه رمادي-بنفسجي.'},
{q:'ما الفرق الجوهري بين البياض الدقيقي والبياض الزغبي من حيث طبيعة المسبب؟',
opts:['كلاهما فطريان حقيقيان لا فرق بينهما','البياض الدقيقي فطر حقيقي (Ascomycete)، بينما البياض الزغبي أوميسيتي (Oomycete) أقرب للطحالب وليس فطراً حقيقياً','البياض الزغبي بكتيري والدقيقي فطري','كلاهما بكتيريان'],
cor:1,exp:'تمييز علمي جوهري: البياض الدقيقي فطر حقيقي من شعبة Ascomycota (مثل Erysiphe, Podosphaera). البياض الزغبي أوميسيتي من مجموعة Oomycetes (مثل Plasmopara, Peronospora)، وهي أقرب تطورياً للطحالب. هذا الفرق يُحدد نوع المبيد الفعّال: مبيدات الأرجوستيرول لا تُؤثر على البياض الزغبي لأن الأوميسيتات لا تحتوي على هذا الستيرول في أغشيتها.'},
{q:'حقل فلفل أصفر الأوراق مع بقع صفراء متعددة الأضلاع محدودة بالأوردة على السطح العلوي ونمو رمادي-بنفسجي على السطح السفلي. ما التشخيص؟',
opts:['البياض الدقيقي','نقص المغنيسيوم','البياض الزغبي (Plasmopara/Peronospora)','مرض فيروسي'],
cor:2,exp:'البقع الصفراء المحدودة بالأوردة على السطح العلوي + النمو الرمادي-البنفسجي (السبورانجيوفورات) على السطح السفلي هو نمط البياض الزغبي المميز. تحديد البقع بالأوردة ناتج عن أن الفطر يتحرك عبر الخلايا البارانشيمية ولا يستطيع اجتياز الأوردة.'},
{q:'لماذا يُفضّل البياض الدقيقي الظروف الجافة نسبياً بينما يُزدهر البياض الزغبي في الرطوبة العالية؟',
opts:['لا علاقة للرطوبة بأي منهما','البياض الدقيقي جراثيمه تحتاج رطوبة منخفضة للإنبات ولا تحتاج ماءً حراً، بينما البياض الزغبي يحتاج ماءً حراً على السطح لإطلاق البوغات المتحركة','البياض الزغبي يعيش في الهواء الجاف','كلاهما يفضل الجفاف'],
cor:1,exp:'فارق حيوي-أحيائي مهم: كونيديا البياض الدقيقي تنبت بكفاءة عند رطوبة نسبية 50-70% وتُعيقها الرطوبة العالية (فوق 95%) التي تُسبب تفجّر الجراثيم. أما البياض الزغبي فيحتاج فيلماً مائياً على أسطح الأوراق لإطلاق الزويدات السابحة (Zoospores) وإتمام الإصابة. هذا يُفسر لماذا البياض الدقيقي ينتشر في الجو الجاف بينما البياض الزغبي ينفجر بعد أمطار أو ندى.'},
{q:'مزارع أضاف مبيداً فطرياً من مجموعة الدميثيل مورفولين (DMI / Sterol biosynthesis inhibitors) ضد البياض الزغبي فلم يُعطِ نتيجة. ما التفسير العلمي؟',
opts:['الجرعة كانت منخفضة','مبيدات DMI فعّالة ضد الفطريات الحقيقية التي تحتوي على الأرجوستيرول، لكن الأوميسيتات (سبب البياض الزغبي) تفتقر لهذا الستيرول في أغشيتها','المبيد انتهت صلاحيته','الرش كان في وقت خاطئ'],
cor:1,exp:'مبيدات DMI (مثل Tebuconazole, Propiconazole) تعمل بتثبيط إنزيمات تخليق الأرجوستيرول في أغشية الفطريات الحقيقية. الأوميسيتات (كمسبب البياض الزغبي) تستخدم الفيتوستيرول وليس الأرجوستيرول في أغشيتها، لذا هذه المبيدات عديمة الأثر عليها. يجب استخدام مبيدات مخصصة للأوميسيتات مثل Metalaxyl, Cymoxanil, أو Mandipropamid.'}
]},
p7:{title:'اختبار: عفن الجذور والذبول',questions:[
{q:'مزارع فلفل يجد نباتات تذبل في منتصف النهار وتعود للانتعاش مساءً في البداية، ثم تذبل نهائياً. عند اقتلاع النبات الجذور سليمة لكن الساق الداخلية لونها بني. ما التشخيص الأرجح؟',
opts:['جفاف التربة','ذبول الفيوزاريوم (Fusarium oxysporum)','عفن Pythium','نقص الحديد'],
cor:1,exp:'التسلسل المميز: ذبول نهاري + انتعاش ليلي أولاً ثم ذبول دائم = علامة كلاسيكية لأمراض الذبول الوعائية. اللون البني في القطاع العرضي للساق يؤكّد انسداد الأوعية الخشبية بالميسليوم الفطري. Fusarium oxysporum يتخصص بمحاصيل بعينها (f.sp. radicis-lycopersici للطماطم، f.sp. capsici للفلفل).'},
{q:'ما الاختلاف الجوهري في طريقة انتقال Fusarium oxysporum مقارنةً بـ Pythium وPhytophthora؟',
opts:['لا فرق، كلها تنتقل بنفس الطريقة','Fusarium ينتقل بالتربة الملوثة والبذور والشتلات وتبقى جراثيمه حيّة لسنوات، بينما Pythium/Phytophthora تحتاج رطوبة عالية وماءً حراً لانتشار الزويدات','Pythium أكثر خطورة دائماً','Fusarium لا ينتقل إلا بالهواء'],
cor:1,exp:'Fusarium ينتج كلاميدوسبورات صلبة تبقى حية في التربة 15-20 سنة دون عائل. هذا يجعل مكافحته صعبة جداً لأن الحرث والدورة الزراعية لا تكفيان. Pythium وPhytophthora أوميسيتات تحتاج رطوبة عالية وتنتشر بزويدات سابحة في الماء، لذا الصرف الجيد والتربة غير المشبعة يُقلّلان خطرها بشكل كبير.'},
{q:'ما الأسلوب الأكثر فاعلية لمنع انتشار Rhizoctonia solani في مشتل خضروات؟',
opts:['رفع معدل التسميد النيتروجيني','تعقيم بيئة الزراعة حرارياً أو كيميائياً قبل الزراعة + تجنّب الإفراط في الري + تحسين الصرف','رش مبيدات حشرية','رفع درجة حرارة البيت المحمي'],
cor:1,exp:'Rhizoctonia solani تتكاثر في بيئات زراعة غير معقّمة رطبة. أهم الإجراءات: تعقيم البيئة (بخار أو Dazomet)، استخدام بيئات نظيفة معقّمة، تجنّب الري الزائد خصوصاً ليلاً، تهوية جيدة لتقليل الرطوبة. المبيد الفطري Iprodione أو Tolclofos-methyl فعّال كعلاج.'},
{q:'مزارع يجد ذبولاً مفاجئاً سريعاً لشتلات الطماطم في بيت محمي بعد يومين من زراعتها مباشرةً مع رائحة كريهة من الجذور المتعفنة. ما الآفة الأرجح؟',
opts:['ذبول Fusarium','عفن Pythium damping-off (الموت المبكر)','نيماتودا الجذور','الذبول البكتيري'],
cor:1,exp:'الموت المبكر السريع جداً (يومان) مع تعفّن الساق الجذرية ورائحة كريهة هو النمط الكلاسيكي لـ Pythium damping-off. Pythium يُهاجم الشتلات الصغيرة الحديثة تحديداً وهي في أضعف حالاتها. رائحة التعفّن الرطب تميّزه عن Fusarium الذي يُسبب تعفّناً جافاً بنياً.'},
{q:'لماذا تُعدّ أمراض الذبول الوعائية (Fusarium/Verticillium) من أصعب الأمراض علاجاً بعد ظهور الأعراض؟',
opts:['لأن المبيدات المتاحة سامة جداً للإنسان','لأن الفطر يعيش داخل الأوعية الخشبية للنبات بعيداً عن وصول المبيدات التقليدية، والأعراض تظهر بعد أن يكون الضرر الوعائي قد تحقق','لأن الأعراض تظهر قبل الإصابة','لأن هذه الأمراض لا تصيب إلا البذور'],
cor:1,exp:'الفطر في أمراض الذبول يسكن الأوعية الخشبية (Xylem) التي تنقل الماء من الجذور للأوراق. عند وصول الأعراض يكون الانسداد الوعائي قد حدث. المبيدات الجهازية المُطبَّقة على التربة تصل الأوعية بشكل محدود. لهذا الوقاية أهم بكثير من العلاج: أصناف مقاومة، تعقيم التربة، بيئة مُعقَّمة.'}
]},
p8:{title:'اختبار: الأمراض البكتيرية والفيروسية',questions:[
{q:'مزارع طماطم يجد بقعاً مائية الشكل على الأوراق تتحول لبنية داكنة محاطة بهالة صفراء، تظهر بعد موجة أمطار وبرودة. ما المسبب الأرجح؟',
opts:['مرض فيروسي','البكتيريا Pseudomonas syringae (تبقّع الطماطم البكتيري)','نقص الكالسيوم','البياض الدقيقي'],
cor:1,exp:'الهالة الصفراء حول البقعة البنية المائية الشكل هي العلامة الكلاسيكية للأمراض البكتيرية الورقية. Pseudomonas syringae pv. tomato تدخل عبر الثغور والجروح وتُنتج سموماً (كورونتين) تُسبب موت الأنسجة. تكتسح خلال الأمطار الباردة (18-24°م) وتنتقل بقطرات المطر والتقطير.'},
{q:'ما الفرق في أسلوب مكافحة الأمراض البكتيرية مقارنةً بالفطرية؟',
opts:['لا فرق، نفس المبيدات تعمل للاثنين','الأمراض البكتيرية تُعالج بمركبات النحاس والمضادات الحيوية المعتمدة زراعياً (كـ Streptomycin) وليس بالمبيدات الفطرية، وليس لها مبيدات علاجية قوية مثل الفطريات','الأمراض البكتيرية أسهل علاجاً دائماً','المبيدات الفطرية تعمل على البكتيريا أيضاً'],
cor:1,exp:'المبيدات الفطرية لا تؤثر على البكتيريا. الأمراض البكتيرية تُكافح بـ: مركبات النحاس (Copper hydroxide, Copper oxychloride) وقائياً، Streptomycin أو Kasugamycin علاجياً في الحالات المسموح بها، وإجراءات زراعية (تجنّب الري الرذاذي، تقليل الرطوبة، زراعة بذور معقّمة). الوقاية أهم من العلاج لأن البكتيريا تتكاثر بسرعة هائلة.'},
{q:'مزارع خيار يجد نباتاً تجعّدت أوراقه وأصابها تبرقش (نقط خضراء فاتحة وداكنة متناوبة) مع تشوّه في الثمار. ما التشخيص؟',
opts:['نقص المغنيسيوم','مرض البياض الدقيقي','إصابة فيروسية (على الأرجح CMV أو ZYMV)','الذبول البكتيري'],
cor:2,exp:'التبرقش والتجعّد والتشوّه نمط مميز جداً للإصابة الفيروسية. في الخيار والقرعيات أكثر الفيروسات شيوعاً: CMV (Cucumber Mosaic Virus) ينقله المن، ZYMV (Zucchini Yellow Mosaic) ينقله المن أيضاً، WMV ينقله المن كذلك. لا علاج كيميائي للفيروسات — المكافحة تتمحور حول مكافحة ناقل الفيروس (المن) وإزالة النباتات المصابة فوراً.'},
{q:'لماذا يُعدّ TYLCV (فيروس تجعّد وأصفرار الطماطم) من أخطر الفيروسات في مصر؟',
opts:['لأنه ينتقل بالتربة فقط','لأنه ينتقل بالذبابة البيضاء المستمرة الانتشار ولا يوجد له علاج كيميائي وقد دمّر محاصيل طماطم كاملة في مصر','لأنه يصيب الجذور فقط','لأنه لا يظهر بأعراض واضحة'],
cor:1,exp:'TYLCV (Tomato Yellow Leaf Curl Virus) من أشد الفيروسات تدميراً للطماطم في مصر. ينقله الذباب الأبيض Bemisia tabaci بكفاءة عالية جداً. أعراضه: تجعّد وأصفرار الأوراق الحديثة، تقزّم، انعدام الإنتاج في الإصابات المبكرة. لا علاج — المكافحة الوحيدة: أصناف مقاومة تحمل جين Ty، ومكافحة الذباب الأبيض بقوة، والشبك الحشري على فتحات البيوت المحمية.'},
{q:'ما أفضل نهج للتعامل مع نبات مصاب بفيروس في حقل تجاري؟',
opts:['رشّه بمبيد فطري قوي','علاجه بمحلول النحاس','اقتلاعه فوراً وإتلافه خارج الحقل مع مكافحة الناقل الحشري لمنع الانتشار','ريّه بكميات أكبر من الماء'],
cor:2,exp:'لا يوجد علاج كيميائي لأي مرض فيروسي نباتي حتى الآن. النبات المصاب يصبح خزاناً للفيروس ومصدر عدوى للنباتات المجاورة عبر الناقل الحشري. الإجراء الصحيح: اقتلاع النبات المصاب في كيس بلاستيكي وإتلافه بعيداً عن الحقل، ثم مكافحة الناقل (المن أو الذباب الأبيض) فوراً لوقف الانتشار.'}
]},
p9:{title:'اختبار: المكافحة المتكاملة للآفات (IPM)',questions:[
{q:'مهندس زراعي رصد آفة في حقله لم تتجاوز عتبة الضرر الاقتصادي. ما القرار الأصح في إطار IPM؟',
opts:['رش فوري وقائي قبل أن تنتشر الآفة','مراقبة منتظمة دقيقة دون تدخل حتى الاقتراب من مستوى التدخل الحرج','إطلاق أعداء طبيعيين فوراً بصرف النظر عن الكثافة','حرث الأرض فوراً للقضاء على الآفة'],
cor:1,exp:'في إطار IPM التدخل قبل بلوغ العتبة الاقتصادية إهدار مالي وبيئي. المراقبة المنتظمة مع تسجيل كثافة الآفة هي الإجراء الصحيح حتى يقترب الوضع من مستوى التدخل الحرج (Action Threshold). الرش الوقائي غير المبرر يقضي على الأعداء الطبيعيين ويُسرّع ظهور المقاومة.'},
{q:'مزارع أطلق حشرة Trichogramma بيولوجية ضد دودة الحشد، ثم رش في اليوم التالي مبيد Lambda-cyhalothrin (بيريثرويد واسع الطيف). ما الخطأ الجوهري في هذا الإجراء؟',
opts:['لا خطأ، الأسلوبان يكمّلان بعضهما','المبيد واسع الطيف يُبيد Trichogramma المُطلَقة قبل أن تؤثر في الآفة، مما يُهدر تكلفة الإطلاق البيولوجي','Trichogramma تُقلل من فاعلية المبيد الكيميائي','يجب رش المبيد قبل الإطلاق البيولوجي بساعة واحدة فقط'],
cor:1,exp:'المبيدات واسعة الطيف كالبيريثرويدات لا تُميّز بين الآفة وأعدائها الطبيعيين. Lambda-cyhalothrin شديد السمية للحشرات المفيدة بما فيها Trichogramma والنحل وأبو العيد. الجمع بين الإطلاق البيولوجي والرش واسع الطيف يعني إهدار الأعداء الطبيعيين مالياً وبيولوجياً. يُشترط استخدام مبيدات انتقائية (مجموعة 28 أو 5) أو فصل توقيت كافٍ.'},
{q:'أيّ من هذه الإجراءات يُصنَّف ضمن المكافحة الزراعية (Cultural Control) في نظام IPM؟',
opts:['رش Spinosad ضد التربس','إطلاق حشرة Orius المفترسة','تغيير ميعاد الزراعة لتجنب ذروة نشاط الآفة الرئيسية','تركيب مصائد فيرومون'],
cor:2,exp:'المكافحة الزراعية تشمل كل الإجراءات التي تُعدّل البيئة لتُقلل ملاءمتها للآفة قبل ظهورها: توقيت الزراعة، الدورة الزراعية، الأصناف المقاومة، تنظيم الكثافة النباتية، إزالة بقايا المحصول. الشبك والمصائد مكافحة فيزيائية، وOrius بيولوجية، وSpinosad كيميائي حيوي.'},
{q:'ما المقصود بـ "تفجّر الآفة الثانوية" (Secondary Pest Outbreak) وكيف يرتبط بسوء استخدام المبيدات؟',
opts:['انفجار عبوة مبيد أثناء الخلط الخاطئ','ظهور آفة كانت أعدادها ضئيلة وتُبقيها أعداؤها الطبيعيون تحت السيطرة، ثم تتفجّر بعد أن يُبيد المبيد واسع الطيف تلك الأعداء','الآفة الرئيسية تعود أشد بعد زوال المبيد','آفة تهاجر من حقل مجاور بعد الرش'],
cor:1,exp:'تفجّر الآفة الثانوية توثّقه عشرات الدراسات: العنكبوت الأحمر مثلاً كان دائماً موجوداً بأعداد ضئيلة لكن الأكاروسات المفترسة كانت تُبقيه تحت السيطرة. رش بيريثرويد واسع الطيف ضد آفة أخرى يُبيد الأكاروسات المفترسة، فيجد العنكبوت الأحمر مجالاً مفتوحاً ويتفجّر في أسبوعين ليُصبح مشكلة أكبر من الآفة الأصلية.'},
{q:'مزارع طبّق برنامج IPM كاملاً على بيوت محمية طماطم وانتظر نتائج بعد أسبوعين فلم يلاحظ فرقاً واضحاً وأراد التخلي عن البرنامج. ما النصيحة العلمية الصحيحة؟',
opts:['تخلّ عن IPM وعُد للرش الكيميائي المنتظم فوراً','استمر في التطبيق — برامج IPM تحتاج 2-3 مواسم لتُثبّت توازن الأعداء الطبيعيين وتُعطي نتائجها الكاملة','ضاعف جرعة المبيدات الانتقائية','IPM لا تُناسب البيوت المحمية'],
cor:1,exp:'IPM ليست حلاً فورياً بل استثمار في استدامة الإنتاج. الأعداء الطبيعيون يحتاجون وقتاً لبناء مستعمراتهم وتثبيت التوازن البيولوجي. في الموسم الأول قد تبدو النتائج متشابهة مع الرش التقليدي أو أقل وضوحاً. من الموسم الثاني والثالث تبدأ التكاليف تنخفض والتوازن يتحسن تراكمياً — وهذا ما أثبتته دراسات الحالة في مزارع الخضروات المصرية.'}
]},
p10:{title:'اختبار: المبيدات الكيميائية والاستخدام الآمن',questions:[
{q:'مزارع استخدم Imidacloprid لثلاثة مواسم متتالية ضد المن ثم لاحظ انخفاضاً واضحاً في فاعليته. ما التفسير العلمي الأرجح؟',
opts:['صلاحية المبيد انتهت في المخزن','تطوير سلالة مقاومة بسبب الضغط الانتقائي المتكرر لنفس مجموعة IRAC دون تناوب','الجرعة أصبحت منخفضة وتحتاج مضاعفة','تغيّرت صيغة المبيد في المصنع'],
cor:1,exp:'الاستخدام المتكرر لـ Imidacloprid (مجموعة IRAC 4A — نيونيكوتينويد) يُفرز ضغطاً انتقائياً يُبقي الأفراد الحاملة لطفرات المقاومة. بعد عدة أجيال تُصبح الغالبية مقاومة. مضاعفة الجرعة لا تحل المشكلة وتُفاقمها. الحل الصحيح: التوقف عن المجموعة 4A وقتياً والتناوب مع مجموعة مختلفة كـ Spirotetramat (23) أو Flonicamid (29).'},
{q:'ما المقصود بـ PHI وما أثرها العملي المباشر على مزارع يُصدّر خضرواته للخارج؟',
opts:['نسبة المادة الفعّالة في المبيد المسموح بها قانونياً','الحد الأدنى للفترة الزمنية بين آخر رشة والحصاد لضمان أن بقايا المبيد انخفضت دون الحد الأقصى المسموح (MRL)','فترة تأثير المبيد على الآفة قبل أن يتحلل','فترة الانتظار لدخول العمال للحقل بعد الرش'],
cor:1,exp:'PHI (Pre-Harvest Interval) هي الفترة الدنيا المحددة علمياً بين آخر رشة والحصاد. تجاوزها يعني وصول منتج يحمل بقايا تتجاوز الحد الأقصى المسموح (MRL) المعتمد دولياً. في أسواق التصدير (أوروبا - الخليج) يُتلَف الإرسال كاملاً عند الرصد. مثال: PHI لـ Chlorpyrifos على الخضروات الورقية 14 يوماً، ولـ Abamectin 7 أيام.'},
{q:'مزارع يُريد مكافحة دودة القطن (Helicoverpa armigera) بأقل ضرر ممكن على النحل وأبو العيد الموجودَين في الحقل. أيّ مجموعة IRAC تُناسب هذا الهدف؟',
opts:['المجموعة 3A (بيريثرويدات) — واسعة الطيف وسريعة التأثير','المجموعة 1B (أوبي) — رخيصة ومتاحة','المجموعة 28 (ديامايد) — انتقائية جداً ليرقات القارضات وأقل خطورة على الحشرات المفيدة','المجموعة 4A (نيونيكوتينويد) — مناسبة لكل الحشرات'],
cor:2,exp:'مجموعة الديامايد (28) كـ Chlorantraniliprole وFlubendiamide تعمل على مستقبلات Ryanodine في عضلات الحشرات. هذه المستقبلات موجودة بتركيز عالٍ في يرقات القارضات ومنخفض جداً في الحشرات المفيدة والثدييات، مما يمنح انتقائية عالية. البيريثرويدات (3A) على العكس تماماً — شديدة السمية للنحل وكل الحشرات المفيدة.'},
{q:'ما الشرط العلمي الصحيح لتناوب المبيدات بهدف منع ظهور المقاومة؟',
opts:['التناوب بين أي مبيدين مختلفَي الاسم التجاري فقط','التناوب بين مجموعات IRAC مختلفة — أي آليات عمل مختلفة — مع عدم تكرار نفس المجموعة أكثر من مرتين متتاليتين في الموسم','التناوب بين منتجَين من شركتين مصنّعتين مختلفتين','تغيير المبيد كل أسبوع بصرف النظر عن مجموعته'],
cor:1,exp:'الاسم التجاري مُضلّل في التناوب. Imidacloprid وThiamethoxam وAcetamiprid ثلاثة أسماء تجارية لكنها جميعاً مجموعة IRAC 4A (نيونيكوتينويد) وتعمل بنفس الآلية — التناوب بينها لا يمنع المقاومة. التناوب الفعّال: مثلاً المجموعة 4A ← ثم 28 ← ثم 5 ← ثم 4A مجدداً. الجدول يُبنى على مجموعة IRAC حصراً.'},
{q:'عامل زراعي رش مبيداً في منتصف يوليو الساعة الثانية عشرة ظهراً. ما الاعتراض العلمي الأساسي على هذا التوقيت؟',
opts:['الحرارة تُسرّع تأثير المبيد وهذا مفيد','الحرارة الشديدة تُبخّر المادة الفعّالة قبل امتصاصها وتزيد خطر تسمم العامل وتُبيد النحل النشط وتُقلل الامتصاص لأن الثغور النباتية مغلقة وقت الحرارة','الاعتراض الوحيد هو إهدار ماء الرش بالتبخر','لا اعتراض ما دام العامل يرتدي قفازات'],
cor:1,exp:'الرش وقت ذروة الحرارة يجمع أربع مشاكل: 1) تبخّر المادة الفعّالة قبل الامتصاص يُقلل الفاعلية بنسبة تصل 30-40%، 2) الحرارة تُسرّع امتصاص المبيد عبر جلد العامل وتزيد خطر التسمم، 3) النحل وحشرات الملاقيح في ذروة نشاطها وتتعرض للمبيد مباشرةً، 4) الثغور النباتية تنغلق عند الحرارة (فوق 35°م) فيقل الامتصاص. الوقت الأمثل: الفجر أو ساعة قبل الغروب.'}
]},
p11:{title:'اختبار: المكافحة البيولوجية والوسائل الطبيعية',questions:[
{q:'ما السبب الجوهري الذي يجعل Bacillus thuringiensis (Bt) آمناً للإنسان والثدييات بينما يكون قاتلاً ليرقات الحشرات؟',
opts:['لأن الإنسان يمتلك جهازاً مناعياً يُبطّل الذيفان','لأن بروتينات Cry الذيفانية تُفعَّل فقط عند الرقم الهيدروجيني القلوي لأمعاء الحشرات (pH 9-11) وفي وجود مستقبلات ظهارة خاصة بها غير موجودة في أمعاء الثدييات','لأن تركيزه في المبيدات التجارية منخفض جداً','لأنه يتحلل قبل أن يصل للمعدة'],
cor:1,exp:'ذيفانات Bt (Cry proteins) تعمل في ثلاث خطوات: أولاً تُذاب البلورات في البيئة القلوية (pH 9-11) لأمعاء الحشرة الوسطى، ثانياً يرتبط الذيفان بمستقبلات بروتينية خاصة (cadherin, APN) في ظهارة الأمعاء الوسطى، ثالثاً تُحدث ثقوباً تُفضي لموت الخلية. أمعاء الإنسان حمضية (pH 1.5-3) ولا تحتوي هذه المستقبلات البروتينية، لذا لا يُفعَّل الذيفان.'},
{q:'فنّي زراعي يُخطط لرش فطر Beauveria bassiana لمكافحة المن في بيت محمي. ما أهم الشرط البيئي الواجب توافره لضمان فاعليته؟',
opts:['درجة حرارة تتجاوز 40°م لتنشيط الفطر','رطوبة نسبية تتجاوز 80% لتمكين إنبات الجراثيم (conidia) على جسم الحشرة','إضاءة قوية لتحفيز نمو الفطر','إيقاف التهوية تماماً لمدة 24 ساعة بعد الرش'],
cor:1,exp:'Beauveria bassiana يُصيب الحشرات عبر اتصال مباشر: تنبت جراثيمه (conidia) على سطح الهيكل الكيتيني الخارجي ثم تخترقه. هذا الإنبات يتطلب رطوبة نسبية لا تقل عن 80%. في البيئة الجافة، تفشل الجراثيم في الإنبات ويُفقد المبيد الحيوي فاعليته كلياً. لذا يُناسب البيوت المحمية حيث يُمكن ضبط الرطوبة، ويُنصح برشه مساءً عند تراجع الإضاءة.'},
{q:'ما الفرق الجوهري بين المكافحة البيولوجية التكميلية (Augmentative) والمكافحة البيولوجية بالحفاظ (Conservation)؟',
opts:['لا فرق حقيقي، المصطلحان مترادفان','التكميلية تعتمد إنتاج أعداء طبيعيين في المختبر وإطلاقها دورياً، بينما الحفاظية تعتمد تعديل بيئة المزرعة لحماية الأعداء الموجودة أصلاً','التكميلية أرخص وأكثر استدامة دائماً','الحفاظية تعني استخدام مبيدات انتقائية فقط'],
cor:1,exp:'للمكافحة البيولوجية ثلاثة مسارات: الكلاسيكية (استيراد عدو طبيعي من موطن الآفة)، والتكميلية Augmentative (إنتاج وإطلاق Trichogramma أو دعسوقات مرباة)، والحفاظية Conservation (تقليل المبيدات واسعة الطيف وزراعة نباتات مصاحبة وتوفير مخابئ). الحفاظية الأقل تكلفة والأكثر استدامة في المزارع التجارية.'},
{q:'مزارع استبدل البيريثرويدات بـ Spinosad فلاحظ بعد أسبوعين تراجع المن وزيادة أعداد دعسوقة سبع النقاط. ما التفسير العلمي الصحيح؟',
opts:['Spinosad يُنتج رائحة جاذبة للدعسوقة','البيريثرويدات كانت تقتل الدعسوقة والأعداء الطبيعيين، وإيقافها أتاح تعافي مجتمعها وعودته للعمل كضابط بيولوجي','المن طوّر مقاومة للبيريثرويدات فأتلف نفسه','الدعسوقة كانت مختبئة في التربة وخرجت مصادفةً'],
cor:1,exp:'البيريثرويدات (مجموعة IRAC 3A) واسعة الطيف وشديدة السمية للدعسوقة والأبو العيد والدبابير الطفيلية. رشّها المتكرر يُفرغ الحقل من الأعداء الطبيعيين ويُوجد فراغاً بيولوجياً تشغله الآفة. Spinosad انتقائي ويُبقي على الأعداء الطبيعيين. هذا جوهر المكافحة البيولوجية بالحفاظ: أحياناً عدم قتل الأعداء الطبيعيين أهم من إطلاق أعداء مُرباة.'},
{q:'ما الميزة التي تجعل زيت النيم (Azadirachtin) مختلفاً جوهرياً عن المبيدات الكيميائية التقليدية في آلية تأثيره؟',
opts:['يقتل الحشرات فوراً بالاتصال المباشر','يحتوي Azadirachtin الذي يُعطّل منظومة الهرمونات الحشرية فيمنع الانسلاخ وتكوين البيض دون قتل فوري، مما يُقلل احتمالية تطوّر المقاومة','هو مجرد طارد للحشرات بلا تأثير قاتل','يعمل كمبيد معوي مماثل لـ Bt'],
cor:1,exp:'Azadirachtin تعمل على عدة مستويات: تُعطّل هرمون الانسلاخ (ecdysone) فتمنع اليرقة من الانتقال للطور التالي، وتُثبّط هرمون الجونيدي فتُقلل وضع البيض والخصوبة، وتُثبّط الشهية. هذا التأثير متعدد الأهداف يجعل احتمالية المقاومة منخفضة جداً. فاعليته أعلى على الأطوار غير الكاملة (يرقات وحوريات) وأقل على البالغات.'}
]},
p12:{title:'اختبار: التشخيص الميداني وكتابة تقرير الآفة',questions:[
{q:'مهندس زراعي يزور حقل طماطم ويجد ذبولاً في بقع متفرقة قرب خطوط الري. ما الخطوة الأولى الأصح في التشخيص الميداني؟',
opts:['رش فوري بمبيد واسع الطيف احتياطاً','تسجيل نمط توزّع الإصابة ثم اقتلاع نبات مصاب لفحص الجذور والأنسجة الوعائية مع مراجعة تاريخ الري والتسميد','الاتصال بمورد المبيدات لوصف الأعراض','انتظار أسبوع لمعرفة مدى انتشار الإصابة'],
cor:1,exp:'التشخيص الميداني يبدأ بالملاحظة المنهجية: توثيق نمط الانتشار (بقع قرب الري = مشكلة وعائية أو فطرية مرتبطة بالرطوبة)، ثم الفحص التشريحي (قطاع عرضي في الساق يكشف التلوّن الوعائي، فحص الجذور يكشف النيماتودا أو العفن). الرش الفوري دون تشخيص المسبب الأول لفشل برامج الإدارة.'},
{q:'كيف يُساعد نمط توزّع الإصابة في الحقل على تحديد المسبب قبل الفحص المجهري؟',
opts:['لا تأثير لنمط التوزّع على التشخيص','التوزّع أداة تشخيصية قوية: بقع في المناطق المنخفضة = Pythium/Phytophthora. إصابة تبدأ من الحواف = آفة هجومية قادمة. إصابة عشوائية كاملة = آفة قديمة الاستيطان. توزيع في صفوف = شتلات ملوّثة أو خط ري مسدود','يُحدد عدد العمال اللازمين للرش فقط','يُحدد نوع المبيد مباشرةً دون الحاجة للفحص'],
cor:1,exp:'نمط التوزّع المكاني (Spatial Distribution Pattern) معلومة تشخيصية لا تُعوَّض: بقع في الأماكن المنخفضة قرب الري = Pythium أو Phytophthora. إصابة من حدود الحقل تتقدم للداخل = آفة هجومية كالمن أو التربس. إصابة عشوائية منتشرة = مرض تربة (Fusarium). إصابة في صفوف = مشكلة في الشتلات. هذه المعلومة وحدها تُضيّق الاحتمالات من عشرات لاثنين.'},
{q:'ما المقصود بمبدأ التشخيص التفريقي في علم الآفات ولماذا هو أساسي للمهندس الزراعي؟',
opts:['استخدام أكثر من مبيد في آن واحد لتغطية كل الاحتمالات','منهجية مقارنة الأعراض المشاهدة بقائمة المسببات المحتملة واستبعادها واحداً بواحد بناءً على دليل حتى الوصول للمسبب الأرجح','الفرق بين مكافحة الآفة وقائياً وعلاجياً','إرسال العينات للمختبر بدلاً من التشخيص الحقلي'],
cor:1,exp:'التشخيص التفريقي (Differential Diagnosis) مبدأ طبي مستعار لعلم الآفات. ذبول النبات قد يكون Fusarium، Verticillium، Ralstonia، Pythium، نيماتودا، إجهاد مائي، أو نقص عناصر. المهندس يُفكّر: ما الدليل الذي يُثبت أو يُبطل كل احتمال؟ قطاع الساق، اختبار اللبن في الماء، فحص الجذور — كل واحدة تستبعد احتمالات وتُرجّح أخرى وتُوفّر تكلفة علاجات خاطئة.'},
{q:'ما أهمية التوثيق الفوتوغرافي في إعداد تقرير آفة احترافي؟',
opts:['لا فائدة عملية، الوصف الكتابي الدقيق كافٍ','الصور توثّق الحالة لحظة التشخيص للمقارنة بعد العلاج، وتُتيح الاستشارة عن بُعد، وتُشكّل سجلاً قانونياً في النزاعات التأمينية والتصديرية','تُستخدم للعرض في الاجتماعات الرسمية فقط','مطلوبة للمحاصيل التصديرية فقط'],
cor:1,exp:'التوثيق الفوتوغرافي جزء أساسي لأربعة أسباب: يُجمّد الحالة وقت التشخيص للمقارنة بعد العلاج وتقييم نجاحه، يُتيح لخبير بعيد تقديم رأي ثانٍ دقيق، يُشكّل وثيقة قانونية في نزاعات التأمين الزراعي، ويبني أرشيفاً للإصابات يُساعد في التنبؤ. الصورة الجيدة تُظهر: نمط الإصابة عاماً، الأعراض عن قرب، مقياس للحجم، والقطاع الوعائي أو الجذور إن لزم.'},
{q:'ما المكوّن الجوهري الذي يُفرّق التقرير الميداني الاحترافي عن مجرد وصف الأعراض؟',
opts:['طول التقرير وكثرة المصطلحات اللاتينية','توصية مبنية على الأدلة تشتمل على المسبب المرجّح ومستوى الإصابة مقارنةً بالعتبة الاقتصادية وأسلوب المكافحة المقترح والجدول الزمني ومؤشرات تقييم النجاح','إرفاق فاتورة مشتريات المبيدات المقترحة','تقديم ثلاثة بدائل علاجية دون ترجيح'],
cor:1,exp:'التقرير الاحترافي يتضمن ستة عناصر: 1) وصف الأعراض موثّقاً بصور، 2) نتائج الفحص والرصد، 3) التشخيص المرجّح بمستوى الثقة، 4) مستوى الإصابة مقارنةً بالعتبة الاقتصادية ومبرر التدخل، 5) التوصية التفصيلية (مادة فعّالة، جرعة، توقيت، PHI)، 6) خطة المتابعة. التقرير بلا توصية قابلة للتطبيق ورقة لا قيمة إدارية لها.'}
]}};
var PEST_QUIZZES=AC_QUIZZES;

function acRenderQuiz(){
var q=AC_QUIZZES[AC.lid];
if(!q){return '<div class="acad-quiz-pg"><div class="acad-breadcrumb"><span role="button" onclick="NAcademy.goHome()">الأكاديمية</span></div><div class="acad-coming"><div class="acad-coming-ico">'+acIco('wrench',30)+'</div><h4>الاختبار قيد الإعداد</h4><p>سيكون متاحاً قريباً.</p></div><button class="acad-btn acad-btn-ghost" onclick="NAcademy.goHome()" style="margin-top:20px">‹ العودة</button></div>'}
var st=AC.qState;var qs=st.qs||q.questions;
if(st.step>=qs.length){
var score=Math.round(st.answers.filter(function(a,i){return a===qs[i].cor}).length/qs.length*100);
var msg=score>=80?'ممتاز! أتقنت هذه المحاضرة بجدارة.':score>=60?'جيد! راجع الأسئلة التي أخطأت فيها وكرر المحاضرة.':'تحتاج لمراجعة المحاضرة مجدداً قبل الانتقال للتالية.';
return '<div class="acad-quiz-pg"><div class="acad-result">'+
'<div class="acad-result-score">'+score+'%</div>'+
'<div class="acad-result-lbl">نتيجتك في الاختبار</div>'+
'<div class="acad-result-msg">'+msg+'</div>'+
'<div class="acad-result-acts">'+
'<button class="acad-btn acad-btn-ghost" onclick="NAcademy.openLesson(\''+AC.lid+'\')">إعادة قراءة المحاضرة</button>'+
'<button class="acad-btn acad-btn-primary" onclick="NAcademy._finishQuiz(\''+AC.lid+'\','+score+')">'+
(score>=60?'متابعة الدورة ←':'حسناً، عدت للمراجعة')+'</button>'+
'</div></div></div>'}
var cur=qs[st.step];
var letters=['أ','ب','ج','د'];
var stepsHTML=qs.map(function(_,i){var cl=i<st.step?'done':i===st.step?'cur':'';return '<div class="acad-step '+cl+'"></div>'}).join('');
var optsHTML=cur.opts.map(function(o,i){return '<button class="acad-opt" data-idx="'+i+'" onclick="NAcademy._pickOpt(this,'+i+')">'+
'<span class="acad-opt-lt">'+letters[i]+'</span>'+o+'</button>'}).join('');
return '<div class="acad-quiz-pg">'+
'<div class="acad-breadcrumb"><span role="button" onclick="NAcademy.goHome()">الأكاديمية</span><span class="sep">›</span><span>'+q.title+'</span></div>'+
'<div class="acad-quiz-hdr"><div class="acad-quiz-title">'+q.title+'</div><div class="acad-quiz-sub">'+qs.length+' أسئلة تقيس الفهم والتطبيق</div></div>'+
'<div class="acad-steps">'+stepsHTML+'</div>'+
'<div class="acad-qcard">'+
'<div class="acad-qnum">السؤال '+(st.step+1)+' من '+qs.length+'</div>'+
'<div class="acad-qtext">'+cur.q+'</div>'+
'<div class="acad-opts" id="acad-opts">'+optsHTML+'</div>'+
'<div class="acad-exp" id="acad-exp"></div>'+
'</div>'+
'<div style="display:flex;justify-content:center">'+
'<button class="acad-quiz-next" id="acad-qnext" onclick="NAcademy._nextQ()">'+
(st.step===qs.length-1?'عرض النتيجة':'السؤال التالي ←')+'</button></div></div>'}

function acBindQuiz(){}

/* ── FINAL EXAM ENGINE (50-question comprehensive exam) ──── */

var AC_FINAL_EXAM={title:'الاختبار النهائي الشامل — مكافحة الآفات الزراعية',passScore:70,questions:[
{q:'ما الكلمة الجوهرية في التعريف العلمي الدقيق للآفة الزراعية؟',opts:['الحجم','الاقتصادي','اللون','عدد الأفراد'],cor:1,exp:'الآفة الزراعية هي أي كائن حي يُلحق ضرراً اقتصادياً بالمحاصيل. الكلمة الجوهرية هي «اقتصادي» — فالكائن لا يُعدّ آفة إلا إذا تجاوز ضرره تكلفة مكافحته، بصرف النظر عن حجمه أو عدد أفراده.'},
{q:'مزارع وجد دعسوقة سبع النقاط بأعداد كبيرة على نباتات الطماطم المصابة بالمن. ما الإجراء الصحيح؟',opts:['رشّها فوراً لأنها حشرة غريبة عن المحصول','تركها دون تدخل لأنها مفترس طبيعي يتغذى على المن','جمعها ونقلها لحقل آخر','اعتبارها آفة ثانوية يجب رصدها'],cor:1,exp:'دعسوقة سبع النقاط مفترس نافع يتغذى على المن ويُعدّ عدوّاً حيوياً مهماً. قتلها بالخطأ يُزيل ضابطاً بيولوجياً مجانياً ويُفاقم مشكلة المن لاحقاً.'},
{q:'وفق تقديرات الفاو، ما النسبة التقريبية للخسائر العالمية في الإنتاج الغذائي السنوي بسبب الآفات؟',opts:['أقل من 5%','بين 20 و40%','أكثر من 90%','لا توجد خسائر تُذكر'],cor:1,exp:'تُقدّر منظمة الأغذية والزراعة (الفاو) خسائر الآفات بين 20 و40% من الإنتاج الغذائي العالمي سنوياً قبل وبعد الحصاد، وفي مصر تتجاوز هذه النسبة 30% في بعض المحاصيل بالمواسم السيئة.'},
{q:'ما العامل الأكثر تأثيراً في انتشار الآفات بظروف الزراعة المصرية الحديثة؟',opts:['استخدام الأصناف المحلية','زراعة محصول واحد على مساحات واسعة (Monoculture)','الري بالتنقيط','تقليل الكثافة النباتية'],cor:1,exp:'زراعة محصول واحد على مساحات شاسعة توفّر مصدراً غذائياً متواصلاً للآفة وتُغيّب التنوع البيولوجي اللازم لوجود الأعداء الطبيعية، وهذا هو المسبب الرئيسي لانفجارات الآفات في الزراعة التجارية الحديثة.'},
{q:'حقل به كثافة حشرية أقل من عتبة الضرر الاقتصادي المحددة للآفة. ما القرار الصحيح؟',opts:['رش وقائي فوري لتجنّب أي احتمال ضرر','الاستمرار في المراقبة المنتظمة دون تدخل كيميائي','حرث الأرض فوراً','إهمال الحقل تماماً لبقية الموسم'],cor:1,exp:'إذا لم تبلغ الكثافة الحشرية عتبة الضرر الاقتصادي فالتدخل الكيميائي غير مبرر مالياً وبيئياً؛ الإجراء الصحيح هو المراقبة المنتظمة لرصد أي تصاعد في الكثافة.'},
{q:'إذا ارتفعت تكلفة المبيد وانخفض سعر بيع المحصول في نفس الموسم، ماذا يحدث لعتبة الضرر الاقتصادي؟',opts:['تنخفض العتبة','ترتفع العتبة','تبقى ثابتة دائماً','تُلغى العتبة تماماً'],cor:1,exp:'معادلة العتبة تعتمد على تكلفة المكافحة مقسومة على قيمة المحصول. عندما ترتفع تكلفة المكافحة أو ينخفض سعر المحصول، ترتفع العتبة لأن المكافحة تصبح مجدية اقتصادياً فقط عند مستويات إصابة أعلى.'},
{q:'ما أكبر مشكلة في قرار الرش الوقائي قبل ظهور أي إصابة فعلية؟',opts:['لا توجد مشكلة، الوقاية دائماً أفضل','تكلفة غير مبررة وقتل للأعداء الطبيعية وتسريع ظهور المقاومة','الجرعة الوقائية أرخص من العلاجية','يُعتبر مخالفة قانونية في كل الحالات'],cor:1,exp:'الرش غير المبرر يُهدر المال، يقضي على الأعداء الطبيعية، ويُسرّع ظهور المقاومة الكيميائية. المبدأ العلمي الصحيح هو عدم التدخل إلا عند بلوغ عتبة الضرر الاقتصادي الفعلية.'},
{q:'لماذا تختلف عتبة الضرر الاقتصادي بين مرحلة الإزهار ومرحلة النضج في نفس المحصول؟',opts:['لأن نوع المبيدات المستخدمة يتغير','لأن حساسية النبات للضرر ومردوده الاقتصادي يختلفان حسب مرحلة النمو','لأن سعر المحصول يتغير يومياً','العتبة لا تختلف إطلاقاً بين المراحل'],cor:1,exp:'النبات في مرحلة الإزهار والعقد أكثر حساسية، وفقدان الأزهار يعني خسارة مباشرة في الإنتاج، ما يُخفّض عتبة الضرر ويستوجب تدخلاً أبكر مقارنةً بمرحلة النضج الأقل حساسية.'},
{q:'تلتفّ أوراق نبات الفلفل للأسفل حول البراعم مع وجود إفرازات لزجة شفافة (عسل ندي). ما الآفة الأرجح؟',opts:['التربس','المن','الذبابة البيضاء','النيماتودا'],cor:1,exp:'تجعّد والتفاف الأوراق حول مستعمرات الآفة + إفرازات العسل الندي علامتان مميزتان للمن، الذي يمتص عصارة البراعم والأوراق الحديثة ويُفرز مادة سكرية تُشجّع نمو العفن الأسود.'},
{q:'لماذا يُعدّ التربس من أصعب الحشرات الماصة مكافحةً رغم صغر حجمه؟',opts:['لأنه يهاجم الجذور فقط','لأنه يعيش محمياً داخل الأزهار والبراعم بعيداً عن معظم المبيدات','لأنه لا يتكاثر بسرعة','لأنه يقاوم كل المبيدات الحيوية فقط'],cor:1,exp:'التربس حشرة شبه مجهرية تعيش داخل الأزهار والبراعم حيث تكون محمية من رش المبيدات السطحي، ما يجعل الوصول إليها أصعب بكثير من حشرات تعيش على سطح الأوراق.'},
{q:'ما السبب البيولوجي الذي يجعل مكافحة الذبابة البيضاء بالمبيدات صعبة وتحتاج رشّتين متتاليتين؟',opts:['أنها تطير بسرعة كبيرة','امتلاك أطوارها الأولى الثابتة طبقة شمعية تحميها من تأثير بعض المبيدات','أنها لا تتكاثر إلا في الشتاء','أنها مقاومة طبيعياً لكل المبيدات'],cor:1,exp:'الأطوار الأولى الثابتة للذبابة البيضاء لا تتحرك وتمتلك طبقة شمعية واقية، فلا تتأثر بالمبيدات الفعّالة ضد البالغين، لذا تحتاج رشّتين بفارق 7-10 أيام لتغطية الجيل الجديد بعد الفقس.'},
{q:'ما الخطر المشترك الأخطر بين المن والتربس والذبابة البيضاء إلى جانب الامتصاص المباشر؟',opts:['تغيير لون التربة','نقل الفيروسات النباتية للنبات السليم','جذب القوارض','تثبيط الإنبات في البذور'],cor:1,exp:'الحشرات الماصة الثلاث ناقلات فعّالة للفيروسات النباتية (مثل فيروسات الموزاييك والتجعّد والذبول البقعي)، وغالباً ما يكون الضرر الناتج عن نقل الفيروس أشد بكثير من ضرر الامتصاص المباشر.'},
{q:'يجد مزارع شتلات طماطم مقطوعة من عند سطح التربة صباحاً دون أي أثر للقضم على الأوراق. ما التشخيص الأرجح؟',opts:['دودة الحشد الخريفية','الدودة الحارقة (Agrotis ipsilon)','المن','التربس'],cor:1,exp:'القطع الليلي لسيقان الشتلات من عند سطح التربة هو العلامة المميزة للدودة الحارقة، التي تختبئ في التربة نهاراً وتخرج ليلاً لقطع السيقان، تاركةً المزارع أمام شتلات غائبة في الصباح.'},
{q:'ما الذي يجعل دودة القطن (Helicoverpa armigera) من أخطر عشر آفات في العالم وفق تصنيف الفاو؟',opts:['أنها تصيب نوعاً نباتياً واحداً فقط','تعدد العوائل النباتية (أكثر من 180 نوعاً) وقدرتها على تطوير مقاومة كيميائية سريعة','أنها لا تتكاثر إلا مرة واحدة سنوياً','ضعف انتشارها الجغرافي'],cor:1,exp:'خطورة هذه الآفة تكمن في اتساع نطاق عوائلها النباتية (أكثر من 180 نوعاً) وقدرتها الاستثنائية على إنتاج إنزيمات تُحيّد المبيدات، ما يُسرّع ظهور سلالات مقاومة.'},
{q:'لماذا تُعدّ فخاخ الفيرومون أداة أساسية في مكافحة الحشرات القارضة كدودة القطن ودودة الحشد؟',opts:['لأنها تقتل اليرقات مباشرة','لأنها تكشف بداية طيران الفراشات وتُحدد التوقيت الأمثل للرش قبل وضع البيض','لأنها تُغني عن أي رش كيميائي نهائياً','لأنها تستهدف الذكور والإناث بنفس الفاعلية القاتلة'],cor:1,exp:'فخاخ الفيرومون أداة رصد لا مكافحة مباشرة؛ ترصد بداية طيران الفراشات البالغة فترتفع أعداد الصيد فجأة قبل وضع البيض، ما يُتيح التدخل خلال 5-7 أيام قبل أن تفقس اليرقات وتُسبب الضرر.'},
{q:'لماذا تفشل المبيدات الجهازية الفعّالة ضد المن (مثل Imidacloprid) في مكافحة دودة القطن؟',opts:['لأن دودة القطن مقاومة لكل المبيدات بلا استثناء','لأن آلية عمل هذه المبيدات مصمّمة أساساً للحشرات الماصة وأقل فاعلية على الجهاز الهضمي للحشرات القارضة','لأن دودة القطن لا تتغذى على النبات إطلاقاً','لأن هذه المبيدات تُستخدم فقط في الشتاء'],cor:1,exp:'المبيدات الفعّالة ضد الحشرات الماصة (كنيونيكوتينويدات Imidacloprid) لا تتمتع بنفس الفاعلية ضد الحشرات القارضة ذات الجهاز الهضمي المختلف؛ تحتاج القارضات مبيدات اتصالية أو معوية مثل البكيليوس ثورينجنسيس Bt أو مبيدات الديامايد.'},
{q:'لماذا لا تُؤثر المبيدات الحشرية التقليدية على العنكبوت الأحمر؟',opts:['لأنه يعيش تحت سطح التربة فقط','لأنه عنكبوتي (Arachnida) له 8 أرجل وليس حشرة، فيختلف هدف عمل المبيد الحشري بيولوجياً','لأنه مقاوم بطبيعته لكل المواد الكيميائية','لأنه لا يتغذى على النباتات الحية'],cor:1,exp:'الأكاروسات عنكبوتيات لها 8 أرجل وليست حشرات؛ هذا الاختلاف البيولوجي يعني أن المبيدات الحشرية التقليدية لا تُؤثر عليها، بل قد تقتل أعداءها الطبيعية وتُبقيها سليمة، فتحتاج مبيدات أكاروسية متخصصة.'},
{q:'ما الأسلوب الأمثل لإدارة نيماتودا الجذور بدلاً من الاعتماد على النيماتيسيدات وحدها؟',opts:['رش مبيدات كيميائية بتركيزات عالية على الأوراق فقط','تكامل الأساليب: تعقيم شمسي للتربة + دورة زراعية + أصناف مقاومة + نيماتيسيدات عند الضرورة','عدم اتخاذ أي إجراء لأن لا علاج لها','الغمر الكيميائي للتربة بالميثيل برومايد فقط'],cor:1,exp:'إدارة نيماتودا الجذور تتطلب نهجاً تكاملياً: التعقيم الشمسي يقتل 80-90% من الأفراد، الدورة الزراعية مع محاصيل غير عائلة تقطع دورة الحياة، والأصناف المقاومة تمنع التكاثر. الاعتماد على المبيدات وحدها حل غير مستدام.'},
{q:'أي الظروف المناخية الأكثر تحفيزاً لانفجار أعداد العنكبوت الأحمر في الحقل؟',opts:['البرودة والرطوبة العالية المستمرة','الحرارة المرتفعة والجفاف','الأمطار الغزيرة المتكررة','انخفاض شدة الإضاءة'],cor:1,exp:'الأكاروسات (مثل العنكبوت الأحمر) تزدهر في الظروف الحارة الجافة، حيث تتسارع دورة حياتها القصيرة أصلاً وتنفجر أعدادها بسرعة كبيرة مقارنةً بالظروف الباردة الرطبة.'},
{q:'ما الأثر العملي لقصر دورة حياة الأكاروسات (7-14 يوماً) على استراتيجية المكافحة؟',opts:['لا تأثير يُذكر على القرارات الإدارية','تُتيح 20+ جيلاً سنوياً وتسريع تطوّر المقاومة الكيميائية، ما يستوجب تناوب المبيدات الأكاروسية بحذر','تجعل المكافحة الكيميائية غير ضرورية إطلاقاً','تمنع الأكاروسات من التكاثر في الصيف'],cor:1,exp:'دورة الحياة القصيرة (7-14 يوماً) تعني عدداً كبيراً من الأجيال سنوياً (20+ جيلاً)، وهذا يُسرّع ظهور سلالات مقاومة للمبيد الأكاروسي إذا استُخدم بشكل متكرر دون تناوب مدروس.'},
{q:'ما الفرق البيولوجي الجوهري بين البياض الدقيقي والبياض الزغبي؟',opts:['لا فرق، المرضان متطابقان تماماً','البياض الدقيقي فطر حقيقي (Ascomycete)، بينما البياض الزغبي أوميسيتي وليس فطراً حقيقياً','البياض الزغبي بكتيري المنشأ','البياض الدقيقي فيروسي المنشأ'],cor:1,exp:'البياض الدقيقي مسببه فطر حقيقي من رتبة Erysiphales، بينما البياض الزغبي مسببه كائن أوميسيتي (مجموعة أقرب تطورياً للطحالب)، وهذا الاختلاف الجوهري هو سبب اختلاف مجموعات المبيدات الفعّالة لكل منهما تماماً.'},
{q:'مزارع رشّ مبيد Myclobutanil (مبيد بياض دقيقي) مرتين على إصابة ظهرت كبقع زاويّة على السطح العلوي مع نمو رمادي على السطح السفلي، دون أي نتيجة. ما سبب الفشل؟',opts:['الجرعة كانت قليلة جداً','التشخيص الفعلي بياض زغبي وليس دقيقي، وMyclobutanil مبيد DMI يستهدف الفطريات الحقيقية فقط ولا يُؤثر على الأوميسيتات','المبيد منتهي الصلاحية','الرش تم في الوقت الخطأ من اليوم فقط'],cor:1,exp:'المظهر الموصوف (بقع زاويّة محدودة بالأوردة + نمو رمادي على السطح السفلي) هو بياض زغبي. مبيدات DMI مثل Myclobutanil تستهدف تخليق الأرجوستيرول في الفطريات الحقيقية، والأوميسيتات لا تحتوي عليه، فلا يُجدي هذا المبيد نفعاً.'},
{q:'أين يظهر البياض الدقيقي بشكل رئيسي مقارنةً بالبياض الزغبي؟',opts:['البياض الدقيقي على السطح السفلي، والزغبي على العلوي','البياض الدقيقي على السطح العلوي أساساً، والزغبي على السطح السفلي أساساً','كلاهما يظهر على الجذور فقط','كلاهما يظهر فقط على الثمار'],cor:1,exp:'البياض الدقيقي يظهر مسحوقه الأبيض على السطح العلوي للورقة أساساً، بينما البياض الزغبي ينمو نموه الرمادي-البنفسجي على السطح السفلي أساساً مع بقع صفراء إلى بنية على السطح العلوي المقابل.'},
{q:'أي الظروف المناخية تُهيّئ لانتشار البياض الزغبي أكثر من البياض الدقيقي؟',opts:['جو جاف نسبياً مع تفاوت حراري بسيط','رطوبة عالية جداً مع وجود ماء حر على سطح الأوراق','حرارة شديدة فوق 40 درجة مئوية فقط','الجفاف التام دون أي رطوبة'],cor:1,exp:'البياض الزغبي (أوميسيتي) يحتاج رطوبة عالية جداً ووجود ماء حر على الأوراق لانتشار جراثيمه السابحة، بينما البياض الدقيقي ينتشر جيداً في رطوبة معتدلة (50-70%) دون الحاجة لماء حر على السطح.'},
{q:'أي مجموعة مبيدات تُستخدم لعلاج البياض الزغبي وليس البياض الدقيقي؟',opts:['DMI مثل Tebuconazole','QoI مثل Azoxystrobin','Metalaxyl وCymoxanil','بيكربونات البوتاسيوم فقط'],cor:2,exp:'مبيدات Metalaxyl وCymoxanil وMandipropamid مصمّمة لاستهداف الأوميسيتات المسببة للبياض الزغبي، بينما مجموعتا DMI وQoI تستهدفان الفطريات الحقيقية المسببة للبياض الدقيقي ولا تُؤثران على الأوميسيتات.'},
{q:'شتلة طماطم صغيرة أظهرت اسمراراً ورقّة في الساق عند خط التربة مع انهيار سريع بعد إفراط في الري. ما المسبب الأرجح؟',opts:['Fusarium oxysporum','Pythium spp.','Ralstonia solanacearum','التربس'],cor:1,exp:'Pythium أوميسيتي ينتشر بزويدات سابحة في الماء ويُهاجم الشتلات الصغيرة الضعيفة مُسبباً الموت المبكر (Damping-off)، ويُشجَّع بالإفراط في الري وسوء الصرف وضعف التعقيم.'},
{q:'كيف يُفرّق المهندس الزراعي ميدانياً وبسرعة بين الذبول البكتيري (Ralstonia) والذبول الفطري؟',opts:['بقياس درجة حرارة التربة فقط','قطع الساق ووضعها في كوب ماء نظيف؛ ظهور خيط أبيض لبني خلال دقيقة يُؤكّد الذبول البكتيري','فحص لون الأزهار','عدّ عدد الأوراق الذابلة فقط'],cor:1,exp:'اختبار اللبن في الماء اختبار ميداني بسيط: قطع الساق ووضعها في كوب ماء نظيف؛ إذا ظهر خيط أبيض لبني يتصاعد خلال دقيقة فهذا يُشير إلى Ralstonia solanacearum، ويُفرّق بسرعة بين الذبول البكتيري والفطري.'},
{q:'لماذا لا يُجدي رش مبيد فطري ورقي نفعاً مع نبات يُظهر أعراض ذبول وعائي من الداخل (كالفيوزاريوم)؟',opts:['لأن المبيدات الورقية لا تصل بكميات كافية للأنسجة الوعائية الداخلية المصابة','لأن الفيوزاريوم لا يُسبب أي ضرر فعلي للنبات','لأن المبيدات الورقية تقتل النبات قبل الفطر','لأن الفيوزاريوم لا يستجيب لأي علاج كيميائي بتاتاً'],cor:0,exp:'عندما يستوطن الفطر الأنسجة الوعائية الداخلية للنبات، لا يصل المبيد الورقي المرشوش على السطح الخارجي بتركيز كافٍ لمعالجة العدوى الداخلية، ولهذا فإن القاعدة الذهبية هي أن الوقاية أساسية لأن العلاج بعد ظهور الأعراض غير فعّال غالباً.'},
{q:'ما نسبة تقليل كثافة مسببات أمراض التربة (مثل Fusarium وRhizoctonia) التي يُحققها التعقيم الشمسي للتربة؟',opts:['لا يُحقق أي تأثير يُذكر','حوالي 70-90%','حوالي 5-10% فقط','يُحقق 100% قضاءً كاملاً دائماً'],cor:1,exp:'التعقيم الشمسي (تغطية التربة الرطبة بنايلون شفاف لمدة 4-6 أسابيع صيفاً) يرفع حرارة التربة إلى 50-60°م ويُقلّل كثافة Fusarium وRhizoctonia والنيماتودا بنسبة 70-90%، وهو من أكثر الإجراءات الوقائية فاعلية وانخفاضاً في التكلفة.'},
{q:'ما الفرق العملي بين البقعة البكتيرية والبقعة الفطرية على الأوراق في بداية ظهورها؟',opts:['لا فرق ملحوظ بينهما إطلاقاً','البقعة البكتيرية مائية الشكل ومحاطة بهالة صفراء، بينما البقعة الفطرية عادةً جافة وتحمل نسيجاً داكناً في مركزها','البقعة البكتيرية دائماً بيضاء اللون','البقعة الفطرية لا تظهر إلا على الجذور'],cor:1,exp:'القاعدة العملية في التشخيص الميداني: البقعة البكتيرية تبدو مائية الشكل (كأنها مبلّلة) ومحاطة بهالة صفراء وغالباً بلا نمو فطري ظاهر، بينما البقعة الفطرية تكون جافة وغالباً ذات نسيج داكن مركزي، والتمييز مهم لاختلاف أسلوب المكافحة.'},
{q:'لماذا لا توجد مكافحة كيميائية مباشرة للفيروسات النباتية مثل TYLCV؟',opts:['لأن الفيروسات غير موجودة أصلاً في النبات','لأن أي مادة قادرة على إبادة الفيروس داخل الخلية ستُبيد الخلية النباتية نفسها معه','لأن الفيروسات تموت تلقائياً خلال يوم واحد','لأن المبيدات الفطرية تكفي لعلاجها'],cor:1,exp:'الفيروسات النباتية تتكاثر داخل خلايا النبات الحية ولا يمكن فصلها عنها كيميائياً؛ أي مادة قادرة على إبادتها ستُتلف الخلية النباتية المضيفة معها، لذا تنحصر المكافحة في قطع حلقة النقل (الحشرات الناقلة) لا علاج الفيروس مباشرة.'},
{q:'ما الاستراتيجية الصحيحة لحماية محصول الطماطم من فيروس TYLCV؟',opts:['رش مبيد مضاد للفيروسات مباشرة على النبات','التركيز على مكافحة الذباب الأبيض الناقل + استخدام أصناف مقاومة + شبك حشري','انتظار ظهور الأعراض ثم العلاج الكيميائي','زيادة التسميد النيتروجيني فقط'],cor:1,exp:'لأن TYLCV ينقله الذباب الأبيض Bemisia tabaci ولا يوجد علاج كيميائي مباشر للفيروس، فإن الاستراتيجية الصحيحة تتركز على قطع حلقة النقل: مكافحة الناقل، استخدام أصناف مقاومة تحمل جين Ty، وتركيب شبك حشري على فتحات البيوت المحمية.'},
{q:'ما الإجراء الوقائي الصحيح ضد الأمراض البكتيرية مثل Pseudomonas syringae قبل موجات الأمطار؟',opts:['رش مركبات النحاس وقائياً قبل ارتفاع الرطوبة','رش مبيد فطري فقط بعد ظهور الأعراض','زيادة الري الرذاذي على الأوراق','لا حاجة لأي إجراء وقائي'],cor:0,exp:'رش مركبات النحاس (مثل Copper hydroxide) وقائياً قبل موجات الأمطار والرطوبة العالية يمنع انتشار البكتيريا، رغم أن النحاس لا يُعالج الإصابة القائمة فعلياً بل يحدّ من انتشارها لاحقاً.'},
{q:'متى اعتمدت منظمة الأغذية والزراعة (الفاو) رسمياً تعريف الإدارة المتكاملة للآفات IPM؟',opts:['1920','1966','2010','2020'],cor:1,exp:'اعتمدت الفاو في عام 1966 تعريفاً رسمياً لـ IPM يقوم على الجمع بين أساليب متعددة مع إعطاء الأولوية للأساليب غير الكيميائية وجعل المبيدات خط الدفاع الأخير، وذلك استجابةً لأزمة المبيدات في الستينيات.'},
{q:'ما العمود الأول والأساسي الذي تُبنى عليه كل قرارات IPM الأخرى؟',opts:['المكافحة الكيميائية الفورية','المراقبة والرصد الحقلي المنتظم (Scouting)','استيراد مبيدات جديدة كل موسم','زيادة الكثافة النباتية'],cor:1,exp:'لا قرار سليم بدون بيانات؛ المراقبة الحقلية المنتظمة (الرصد الأسبوعي وتسجيل أعداد الآفة) هي الأساس الذي يُحدد هل وصلت الآفة لعتبة الضرر الاقتصادي أم لا، وبدونها يصبح أي تدخل عشوائياً غير مبني على دليل.'},
{q:'ما الخطأ الشائع في فهم مفهوم IPM؟',opts:['الخلط بينها وبين المكافحة العضوية، رغم أن IPM لا ترفض المبيدات الكيميائية بل تضعها كخط دفاع أخير','اعتبارها أرخص دائماً من المكافحة الكيميائية البحتة','الاعتماد على الرصد الأسبوعي المنتظم','استخدام الأصناف المقاومة كخطوة وقائية أولى'],cor:0,exp:'خطأ شائع جداً هو الخلط بين IPM والمكافحة العضوية الكاملة؛ في الواقع لا ترفض IPM استخدام المبيدات الكيميائية إطلاقاً، بل تُعطي الأولوية للأساليب غير الكيميائية وتجعل المبيد الانتقائي أداةً تُستخدم فقط عند تجاوز عتبة الضرر الاقتصادي وفشل الأساليب الأخرى.'},
{q:'لماذا لا يصحّ الحكم على نجاح أو فشل برنامج IPM بعد موسم زراعي واحد فقط؟',opts:['لأن برامج IPM تحتاج عادةً 2-3 مواسم حتى يتحقق توازن مستدام للأعداء الطبيعيين وتتحسن البيئة الحقلية تراكمياً','لأن IPM لا تُحقق أي نتائج إطلاقاً مهما طالت المدة','لأن الموسم الواحد كافٍ دائماً لإثبات الفشل التام','لأن نتائج IPM تظهر خلال 24 ساعة فقط من التطبيق'],cor:0,exp:'بناء توازن الأعداء الطبيعيين وتحسين البيئة الحقلية عملية تراكمية تحتاج عادةً موسمين إلى ثلاثة مواسم لتُثمر نتائجها الكاملة؛ الحكم على البرنامج بعد موسم واحد فقط يُعطي صورة غير مكتملة عن فاعليته الحقيقية.'},
{q:'ما الغرض الأساسي من تصنيف المبيدات الحشرية حسب مجموعات IRAC؟',opts:['تحديد سعر المبيد في السوق','توفير أساس علمي لتناوب المبيدات بآليات عمل مختلفة لمنع تطور المقاومة','تصنيف المبيدات حسب لون عبوتها','تحديد موسم الزراعة المناسب للرش'],cor:1,exp:'لجنة IRAC تُصنّف المبيدات حسب آلية عملها على الجهاز العصبي أو الهضمي للحشرة. المبيدات من نفس المجموعة تعمل بنفس الطريقة، لذا فإن التناوب الفعّال لمنع المقاومة يجب أن يكون بين مجموعات IRAC مختلفة وليس داخل المجموعة نفسها.'},
{q:'ما المقصود بفترة ما قبل الحصاد (PHI) ولماذا هي حاسمة؟',opts:['فترة تخزين المبيد قبل استخدامه','أقل فترة زمنية واجب انتظارها بين آخر رشة والحصاد لضمان أمان المحصول وتجنّب مخالفات التصدير','فترة بقاء العامل خارج الحقل بعد الرش','المدة التي يبقى فيها المبيد في عبوته الأصلية'],cor:1,exp:'PHI هي الفترة الواجب انتظارها بين آخر رشة والحصاد. تجاهلها يُعرّض المحصول لبقايا كيميائية زائدة، ويُعرّض المزارع لمخالفات وغرامات في أسواق التصدير وخطر صحي على المستهلك.'},
{q:'ما الفرق بين PHI وREI في قراءة ملصق المبيد؟',opts:['PHI تخص فترة دخول العمال، وREI تخص فترة الحصاد','PHI أقل فترة بين الرش والحصاد، وREI أقل فترة قبل السماح بدخول العمال للحقل بعد الرش','لا فرق بينهما، المصطلحان مترادفان تماماً','PHI تخص المبيدات الفطرية فقط وREI تخص الحشرية فقط'],cor:1,exp:'PHI (Pre-Harvest Interval) هي أقل فترة بين آخر رشة والحصاد لحماية المستهلك، بينما REI (Re-Entry Interval) هي أقل فترة قبل السماح للعمال بدخول الحقل بعد الرش لحماية صحتهم من التعرّض المباشر للمبيد الطازج.'},
{q:'لماذا تُعدّ مبيدات البيريثرويدات (مثل Cypermethrin) خطيرة رغم فعاليتها الواسعة؟',opts:['لأنها بطيئة المفعول جداً','لأنها واسعة الطيف وتُبيد الأعداء الطبيعيين والنحل بشكل مرتفع جداً','لأنها لا تقتل أي حشرة على الإطلاق','لأنها مكلفة جداً ونادرة في السوق'],cor:1,exp:'البيريثرويدات واسعة الطيف وتُصنَّف بأثر مرتفع جداً على النحل والأعداء الطبيعيين، فاستخدامها غير المدروس يُخلّ بالتوازن البيولوجي في الحقل ويُمهّد لانفجارات آفات ثانوية بعد إبادة أعدائها الطبيعية.'},
{q:'ما القاعدة الذهبية لتناوب المبيدات لمنع ظهور المقاومة؟',opts:['استخدام نفس المادة الفعّالة طوال الموسم لضمان الفاعلية','عدم تكرار مبيد من نفس مجموعة IRAC أكثر من مرتين متتاليتين، والتناوب بين ثلاث مجموعات على الأقل','مضاعفة الجرعة كلما شُكّ في ضعف الفاعلية','الخلط بين مبيدين من نفس المجموعة لمضاعفة الأثر'],cor:1,exp:'القاعدة الذهبية في إدارة المقاومة هي عدم تكرار مبيد من نفس مجموعة IRAC أكثر من مرتين متتاليتين في الموسم، والتناوب بين ثلاث مجموعات مختلفة الآلية على الأقل، لأن الأفراد الناجية من مبيد معين تُورّث الطفرة المقاومة لأجيالها.'},
{q:'ما الفرق الجوهري بين الحشرات المفترسة والحشرات الطفيلية في المكافحة البيولوجية؟',opts:['لا فرق بينهما إطلاقاً','المفترسة تلتهم عدة فرائس مباشرةً طوال حياتها، بينما الطفيلية (مثل Trichogramma) تضع بيضها داخل أو على الآفة لتقتلها من الداخل وغالباً تستهدف آفة واحدة بعينها','المفترسة تهاجم النباتات بدلاً من الآفات','الطفيلية لا تتغذى على الحشرات إطلاقاً'],cor:1,exp:'المفترسات مثل دعسوقة أبو العيد تلتهم عدة أفراد فريسة مباشرة طوال حياتها، أما الطفيليات مثل Trichogramma فتضع بيضها داخل الآفة (كبيض الحشرات) فتتغذى يرقتها عليها من الداخل حتى الموت، وهي عادة أكثر تخصصاً من المفترسات.'},
{q:'كيف تعمل بكتيريا Bacillus thuringiensis (Bt) بأمان على الثدييات بينما تقتل اليرقات؟',opts:['تُفعَّل بلوراتها فقط في القناة الهضمية القلوية لليرقات، وأمعاء الثدييات حمضية وتفتقر لمستقبلاتها الخاصة','تتجنب أمعاء الثدييات بسبب رائحتها','لا تدخل جسم أي كائن إطلاقاً','تعمل فقط على الحشرات البالغة الطائرة'],cor:0,exp:'بلورات Bt البروتينية (Cry proteins) لا تُفعَّل إلا في وسط قلوي (pH 9-11) كما في أمعاء اليرقات، فترتبط بمستقبلات خاصة هناك وتُحدث ثقوباً قاتلة. أمعاء الثدييات حمضية (pH 2-4) وتفتقر لتلك المستقبلات، لذا لا تتأثر بها.'},
{q:'ما الشرط البيئي الأساسي لنجاح فطر Beauveria bassiana في إصابة الحشرات؟',opts:['حرارة منخفضة جداً دون أي رطوبة','رطوبة نسبية تتجاوز 80% لإنبات الجراثيم على الهيكل الخارجي للحشرة','جفاف تام لمدة أسبوعين على الأقل','ضوء شمس مباشر طوال اليوم'],cor:1,exp:'جراثيم Beauveria bassiana تحتاج رطوبة نسبية تتجاوز 80% لتنبت على الهيكل الخارجي للحشرة وتخترقه؛ في الظروف الجافة تنخفض فاعليته بشكل كبير، لذا يُفضَّل الرش مساءً أو ليلاً عند ارتفاع الرطوبة.'},
{q:'ما الخطأ الذي يُبطل فاعلية إطلاق أعداء طبيعيين كـ Encarsia formosa في برنامج مكافحة متكامل؟',opts:['إطلاقها في الصباح الباكر','رش مبيد واسع الطيف (مثل البيريثرويدات) قبل أو بعد الإطلاق مباشرة دون انتظار فترة السمية المتبقية','استخدام مصائد لاصقة صفراء للرصد','تركيب شبك حشري على فتحات البيت المحمي'],cor:1,exp:'رش مبيد واسع الطيف بالقرب من توقيت إطلاق الأعداء الطبيعيين يُبيدهم قبل أن يبدأ تأثيرهم؛ يجب الانتظار حتى تنتهي فترة السمية المتبقية الكاملة للمبيد قبل أي إطلاق بيولوجي حتى يُحقق نتيجة فعلية.'},
{q:'مهندس زراعي يصل لحقل طماطم يُظهر ذبولاً في بقع متفرقة قرب خطوط الري. ما الخطوة الأولى الصحيحة في التشخيص الميداني؟',opts:['رش فوري بمبيد واسع الطيف احتياطاً قبل أي فحص','تسجيل نمط توزّع الإصابة ثم فحص الجذور والأنسجة الوعائية لنبات مصاب مع مراجعة تاريخ الري والتسميد','الاتصال بمورد المبيدات لوصف الأعراض هاتفياً فقط','الانتظار أسبوعاً كاملاً لمعرفة مدى الانتشار قبل أي إجراء'],cor:1,exp:'التشخيص الميداني يبدأ بالملاحظة المنهجية: توثيق نمط الانتشار (بقع قرب الري قد تُشير لمشكلة وعائية أو فطرية مرتبطة بالرطوبة) ثم الفحص التشريحي للساق والجذور. الرش الفوري دون تشخيص يُهدر المال ويُفشل برنامج الإدارة.'},
{q:'كيف يساعد نمط توزّع الإصابة المكاني في الحقل على تضييق احتمالات التشخيص قبل الفحص المجهري؟',opts:['لا تأثير لنمط التوزيع على عملية التشخيص إطلاقاً','بقع في المناطق المنخفضة قرب الري تُشير لـ Pythium أو Phytophthora، وإصابة من حدود الحقل للداخل تُشير لآفة هجومية، وإصابة عشوائية منتشرة تُشير لمرض تربة قديم الاستيطان','يُحدد فقط عدد العمال اللازمين للرش','يُحدد نوع المبيد المناسب مباشرة دون أي فحص آخر'],cor:1,exp:'نمط التوزّع المكاني معلومة تشخيصية قيّمة: بقع بالمناطق المنخفضة قرب الري = Pythium/Phytophthora، إصابة تتقدم من الحدود للداخل = آفة هجومية كالمن، إصابة عشوائية منتشرة = مرض تربة مثل Fusarium. هذه الملاحظة وحدها تُضيّق الاحتمالات قبل أي فحص دقيق.'},
{q:'ما المقصود بمبدأ التشخيص التفريقي الذي يستعيره علم الآفات من الطب؟',opts:['استخدام أكثر من مبيد في وقت واحد لتغطية كل الاحتمالات','منهجية مقارنة الأعراض المشاهدة بقائمة المسببات المحتملة، واستبعادها واحداً بواحد بناءً على دليل حتى الوصول للمسبب الأرجح','إرسال كل العينات للمختبر بدلاً من أي تشخيص حقلي','الفرق بين المكافحة الوقائية والعلاجية فقط'],cor:1,exp:'التشخيص التفريقي منهجية تقارن الأعراض (كذبول النبات) بقائمة المسببات المحتملة (Fusarium، Ralstonia، نيماتودا، إجهاد مائي...) وتستخدم أدلة فعلية (قطاع الساق، اختبار اللبن، فحص الجذور) لاستبعاد احتمالات وترجيح أخرى، فتُوفّر تكلفة علاجات خاطئة.'},
{q:'ما المكوّن الجوهري الذي يُميّز تقرير الآفة الميداني الاحترافي عن مجرد وصف للأعراض؟',opts:['طول التقرير وكثرة المصطلحات اللاتينية فيه','توصية مبنية على الأدلة تشمل المسبب المرجّح، ومستوى الإصابة مقارنةً بالعتبة الاقتصادية، وأسلوب المكافحة المقترح، والجدول الزمني، ومؤشرات تقييم النجاح','إرفاق فاتورة شراء المبيدات المقترحة فقط','تقديم ثلاثة بدائل علاجية متساوية دون أي ترجيح بينها'],cor:1,exp:'التقرير الاحترافي يتضمن وصفاً موثّقاً بالصور، نتائج الفحص والرصد، تشخيصاً مرجّحاً بمستوى ثقة، مقارنة مستوى الإصابة بالعتبة الاقتصادية، توصية تفصيلية قابلة للتطبيق، وخطة متابعة. تقرير بلا توصية عملية لا قيمة إدارية حقيقية له.'}
]};
var PEST_FINAL_EXAM=AC_FINAL_EXAM;

