var FEED_QUIZZES={
fd1:{title:'اختبار المحاضرة الأولى — مقدمة في تغذية الحيوان وإدارة الأعلاف',questions:[
{q:'ما الفرق الجوهري بين "العلف" (Feed) و"العليقة" (Ration) كما يُستخدمان في هذا المجال؟',
opts:['العلف مادة صالحة للأكل تمد الحيوان بعنصر غذائي، والعليقة وجبة واحدة عابرة لا علاقة لها بيوم كامل','لا فرق حقيقي بينهما، فكلاهما يدل على أي مادة يتناولها الحيوان بصرف النظر عن الزمن أو التركيب','العلف مادة صالحة للأكل تمد الحيوان بعنصر غذائي، والعليقة مجموع الأعلاف التي يتناولها خلال يوم كامل','العليقة مصطلح خاص بتغذية الدواجن حصرياً، والعلف مصطلح خاص بالمجترات دون غيرها من الأنواع'],
cor:2,exp:'العلف (Feed) مصطلح عام لأي مادة صالحة للأكل تزوّد الحيوان بعنصر غذائي واحد أو أكثر، بينما العليقة (Ration) هي التركيبة الكاملة من الأعلاف المختلفة التي يتناولها الحيوان خلال يوم واحد لتغطية احتياجاته. فهم هذا الفرق أساسي قبل حساب أي عليقة في المحاضرات القادمة.'},
{q:'وفق تقرير Alltech لعام 2026 حول إنتاج الأعلاف العالمي، ما الرقم التقريبي لإنتاج الأعلاف المُصنّعة عالمياً في عام 2025؟',
opts:['نحو 140 مليون طن متري فقط في العام كاملاً حول العالم','أقل من 50 مليون طن متري في مجمل الإنتاج السنوي المُسجَّل','نحو 1.44 مليار طن متري من الأعلاف المُصنّعة حول العالم','أكثر من 10 مليارات طن متري بقليل حسب تقديرات المسح الأخير'],
cor:2,exp:'قدّر التقرير إنتاج الأعلاف العالمي في 2025 بنحو 1.44 مليار طن متري، بزيادة 2.9% عن العام السابق، استناداً لبيانات من 142 دولة وأكثر من 38 ألف مصنع أعلاف. هذا الرقم يعكس حجم صناعة الأعلاف وثقلها الاقتصادي العالمي الهائل.'},
{q:'مربي دواجن يلاحظ أن تكلفة العلف تمثل الجزء الأكبر من مصروفاته الكلية. ما النسبة التقريبية الشائعة لتكلفة العلف من إجمالي تكلفة إنتاج الدجاج اللاحم في أغلب المزارع التجارية؟',
opts:['نحو 65-70% من إجمالي التكلفة المتغيرة للمزرعة غالباً','نحو 10-15% فقط من إجمالي التكلفة الكلية للمزرعة','أقل من 5% من التكلفة الكلية مهما ارتفعت أسعار الحبوب','نحو 25% كحد أقصى ثابت في كل الحالات والظروف'],
cor:0,exp:'يمثّل العلف في إنتاج الدجاج اللاحم عادة نحو 65-70% من إجمالي التكلفة المتغيرة، وهي أعلى نسبة بين أنواع الإنتاج الحيواني الرئيسية بسبب سرعة النمو ومعدل التحويل الغذائي المرتفع نسبياً. لهذا فإن أي تحسين بسيط في كفاءة التغذية له أثر مالي كبير على هامش الربح.'},
{q:'ما الذي تغيّر تحديداً في اسم المرجع الأمريكي الشهير لاحتياجات الحيوان الغذائية (NRC) اعتباراً من عام 2015؟',
opts:['توقف المرجع نهائياً عن الصدور منذ ذلك التاريخ ولم تُنشر عنه أي طبعة جديدة بعدها إطلاقاً','اندمج ضمن الأكاديميات الوطنية للعلوم والهندسة والطب، فصارت الإصدارات الجديدة تُنشر باسم NASEM','تغيّر اسمه فقط إلى منظمة الفاو دون أي تغيير مؤسسي أو بحثي حقيقي وراء هذا التغيير','اقتصر المرجع بعدها على تغطية الدواجن فقط، وتوقف إصداره لباقي الأنواع الحيوانية الأخرى'],
cor:1,exp:'في 2015 اندمج المجلس القومي للبحوث (NRC) ضمن الأكاديميات الوطنية للعلوم والهندسة والطب (NASEM)، فصارت كل الإصدارات الجديدة لجداول الاحتياجات الغذائية، كطبعة الألبان 2021 وطبعة اللحوم المُحدَّثة 2024 وطبعة الدواجن العاشرة، تُنشر باسم NASEM بدلاً من NRC.'},
{q:'ما التعريف الأدق لـ"الكفاءة التحويلية للعلف" (Feed Conversion Ratio – FCR)؟',
opts:['كمية العلف بالكيلوجرام المطلوبة لإنتاج وحدة واحدة من الوزن الحي أو المنتج','نسبة البروتين الموجودة في العلف مقارنةً بنسبة الكربوهيدرات الكلية فيه','السعر النهائي لكيلوجرام واحد من العلف المُباع في السوق المحلي حالياً','عدد الوجبات التي يتناولها الحيوان الواحد يومياً بصرف النظر عن كميتها'],
cor:0,exp:'الكفاءة التحويلية للعلف (FCR) تقيس كمية العلف اللازمة لإنتاج وحدة واحدة من المنتج، كوحدة وزن حي مكتسب أو كيلوجرام بيض أو لتر حليب. كلما انخفض هذا الرقم دلّ ذلك على كفاءة أعلى في تحويل العلف إلى منتج، وهو من أهم المؤشرات الاقتصادية في أي منشأة إنتاج حيواني.'},
{q:'ما الأساس العلمي الذي تُحسب عليه احتياجات الحيوان الغذائية عملياً، بدلاً من الاعتماد على وزن العلف كما هو بمحتواه المائي؟',
opts:['وزن العلف الطازج بكامل محتواه المائي دون أي خصم أو تعديل عليه','المادة الجافة بعد استبعاد نسبة الماء من الوزن الكلي للعلف','حجم العلف بالسنتيمتر المكعب داخل وعاء تخزين قياسي معتمد','لون العلف ورائحته العامة كمؤشر تقديري سريع على جودته'],
cor:1,exp:'تحتوي كثير من الأعلاف على نسبة ماء متفاوتة قد تتجاوز 80% في بعضها، ما يجعل وزنها الطازج مضللاً عند المقارنة. لذلك تُحسب كل الاحتياجات الغذائية والعلائق أساساً على المادة الجافة، أي وزن العلف بعد استبعاد الماء تماماً، لضمان مقارنة عادلة بين مصادر العلف المختلفة.'},
{q:'ما الفارق الأساسي بين الحيوانات المجترة وغير المجترة من حيث التركيب الهضمي؟',
opts:['المجترات لها معدة واحدة بسيطة أحادية الحجرة، بينما غير المجترة لها أربع حجرات معدية متتالية ومعقدة','لا يوجد فرق تشريحي حقيقي بين النوعين، والفرق كله يكمن فقط في نوع العلف المُقدَّم لكل منهما','المجترات لها معدة من أربع حجرات تتيح تخميراً ميكروبياً واسعاً للألياف، بعكس معدة غير المجترة البسيطة','المجترات لا تحتاج إطلاقاً لأي كائنات دقيقة مساعدة في هضمها، بعكس غير المجترة التي تعتمد عليها كلياً'],
cor:2,exp:'تمتلك الحيوانات المجترة كالأبقار والجاموس والأغنام والماعز معدة مقسمة لأربع حجرات، ما يتيح تخميراً ميكروبياً هائلاً يُمكّنها من الاستفادة من الألياف الخشنة بكفاءة عالية. أما غير المجترة كالدواجن فمعدتها بسيطة أحادية الحجرة، فتحتاج علائق أعلى تركيزاً وأقل ألياف، وهذا محور المحاضرة الرابعة بالتفصيل.'},
{q:'مزرعة تستخدم إضافة علفية حديثة تُخفّض انبعاثات غاز الميثان من الأبقار الحلاب بنسبة تقارب 30% دون أي تأثير على إنتاج الحليب. إلى أي فئة تنتمي هذه الإضافة؟',
opts:['مضاد حيوي تقليدي يُستخدم أساساً لعلاج الأمراض البكتيرية الشائعة داخل القطيع بأكمله','إضافة علفية حديثة من فئة مثبطات الميثان، تعمل داخل الكرش على مسار التخمر الميكروبي','فيتامين أساسي عادي لا علاقة مباشرة له بعملية الهضم أو التخمر الكرشي داخل الكرش','ملح معدني تقليدي يُستخدم غالباً فقط لتحسين طعم العليقة المُقدَّمة للحيوان'],
cor:1,exp:'هذا وصف دقيق لفئة مثبطات الميثان الحديثة (كمركّب 3-NOP المعروف تجارياً)، وهي إضافات تعمل داخل الكرش على تثبيط إنزيم أساسي في مسار إنتاج الميثان لدى الكائنات الدقيقة، فتخفض الانبعاثات نحو 30% في الأبقار الحلاب وأكثر في أبقار اللحم أحياناً، دون التأثير على الحليب أو صحة الحيوان.'},
{q:'مربٍ مبتدئ يفترض أنه يمكنه استخدام العليقة نفسها بالضبط لجميع أبقاره بصرف النظر عن عمرها أو مرحلة إنتاجها. ما التقييم الأصح لهذا الافتراض؟',
opts:['افتراض صحيح تماماً ولا داعي لأي تمييز، فكل الأبقار من نفس السلالة تحتاج الكمية ذاتها بالضبط دوماً','افتراض خاطئ، فالاحتياجات الغذائية تختلف باختلاف العمر والوزن ومرحلة الإنتاج كالحلابة أو الجفاف','افتراض صحيح، لكن فقط في حالة الجاموس تحديداً دون باقي سلالات الأبقار العادية الأخرى','لا توجد علاقة حقيقية بين مرحلة الإنتاج وكمية العلف المطلوبة يومياً في أي حال من الأحوال'],
cor:1,exp:'من أشيع الأخطاء عند المبتدئين افتراض أن عليقة واحدة تناسب كل حيوانات القطيع. عملياً تحتاج البقرة عالية الإدرار كمية وتركيزاً مختلفين تماماً عمّا تحتاجه بقرة جافة أو عجلة نامية، لأن احتياجات الصيانة تظل شبه ثابتة بينما تضاف فوقها احتياجات إنتاجية متغيرة حسب المرحلة. هذا محور محاضرات لاحقة في الكورس.'},
{q:'ما الدور الأساسي لـ"إدارة الأعلاف" كمنظومة متكاملة، بخلاف مجرد اختيار نوع العلف المناسب فقط؟',
opts:['تقتصر فقط على شراء أرخص عرض متاح من الأعلاف في السوق المحلي كل شهر دون أي اعتبار آخر','تنحصر تماماً في مرحلة تخزين الأعلاف داخل المخازن المخصصة لها دون أي دور إضافي بعد ذلك','تعني فقط تسجيل كمية العلف المُستهلكة يومياً في دفتر خاص دون اتخاذ أي قرارات فعلية بناءً عليه','تشمل تقييم المواد العلفية وتصميم العليقة والتخزين والخلط والتوزيع ومتابعة الفاقد والتكلفة'],
cor:3,exp:'إدارة الأعلاف منظومة متكاملة تبدأ من تقييم جودة المواد العلفية المتاحة، وتصميم العليقة المناسبة لكل فئة إنتاجية، مروراً بالتخزين السليم وأساليب الخلط والتوزيع داخل المزرعة، وانتهاءً بالمتابعة المستمرة لضبط التكلفة وتقليل الفاقد. الاكتفاء باختيار نوع العلف فقط يُفوّت جزءاً كبيراً من الفرصة الاقتصادية الحقيقية لهذا المجال.'}
]},
fd2:{title:'اختبار المحاضرة الثانية — مكونات الأعلاف والقيمة الغذائية',questions:[
{q:'كيف يُحسب "المستخلص الخالي من النيتروجين" (NFE) في التحليل التقريبي التقليدي؟',
opts:['يُحسب بالطرح: 100 ناقص مجموع الرطوبة والبروتين والدهن والألياف والرماد','يُقاس مباشرة بجهاز مستقل تماماً عن باقي مكونات التحليل الخمسة الأخرى','يُقاس بنفس جهاز وطريقة قياس البروتين الخام دون أي فرق حقيقي بينهما','لا يُحسب إطلاقاً في أي شهادة تحليل تقريبي حديثة أو تقليدية معتمدة'],
cor:0,exp:'على عكس المكونات الخمسة الأخرى التي تُقاس مباشرة، يُحسب NFE بالطرح: 100% ناقص مجموع نسب الرطوبة والبروتين الخام والدهن الخام والألياف الخام والرماد. لهذا يجب أن يساوي مجموع الأرقام الستة كلها 100% دائماً في أي شهادة تحليل تقريبي صحيحة.'},
{q:'عينة علف أظهر تحليلها أنها تحتوي على 2.8% نيتروجين. ما نسبة البروتين الخام فيها؟',
opts:['2.8% بالضبط دون أي تعديل أو معامل حسابي إضافي يُطبَّق عليها','6.25% بصرف النظر عن نسبة النيتروجين المقاسة أصلاً في العينة','28% بعد ضرب نسبة النيتروجين في عشرة كاملة كمعامل تقريبي','17.5% بعد ضرب نسبة النيتروجين في المعامل الثابت المعتمد 6.25'],
cor:3,exp:'البروتين الخام = نسبة النيتروجين × 6.25 = 2.8 × 6.25 = 17.5%. هذا المعامل الثابت مبني على افتراض أن البروتين يحتوي في المتوسط على نحو 16% نيتروجين تقريباً.'},
{q:'لماذا لا يكفي رقم "البروتين الخام" وحده للحكم الكامل على جودة مصدر بروتين في علائق الدواجن تحديداً؟',
opts:['لأن رقم البروتين الخام غير دقيق إطلاقاً ولا يجب الاعتماد عليه في أي حساب','لأنه يقيس الكمية الكلية فقط، بينما تحتاج الدواجن أحماضاً أمينية محدِّدة كالليسين','لأن الدواجن لا تستفيد من البروتين بأي شكل من الأشكال مهما كان مصدره','لأن هذا الرقم يخص المجترات حصرياً ولا ينطبق على الدواجن من الأساس'],
cor:1,exp:'البروتين الخام يقيس الكمية الكلية للنيتروجين المحوَّل لبروتين افتراضي، دون تمييز بين مصادر بروتين مختلفة في تركيبة الأحماض الأمينية. الدواجن تحديداً حساسة لنقص أحماض أمينية "محدِّدة" كالليسين والميثيونين، فمصدران بنفس نسبة البروتين الخام قد يختلفان كثيراً في الأداء الفعلي.'},
{q:'ما الفرق الجوهري بين "البروتين الحقيقي" و"النيتروجين غير البروتيني" (NPN) كاليوريا؟',
opts:['لا فرق عملي حقيقي بينهما، وتستفيد كل الحيوانات منهما بنفس الكفاءة تماماً','وحيدات المعدة فقط قادرة على الاستفادة من النيتروجين غير البروتيني بكفاءة عالية','المجترات يمكنها الاستفادة من NPN عبر الكائنات الدقيقة في الكرش، بعكس وحيدات المعدة','النيتروجين غير البروتيني مصدر طاقة فقط ولا علاقة له بالبروتين من الأساس'],
cor:2,exp:'المجترات كالأبقار والأغنام يمكنها الاستفادة من مصادر النيتروجين غير البروتيني كاليوريا، لأن الكائنات الدقيقة في الكرش تُحوّلها لبروتين ميكروبي مفيد. أما الدواجن ووحيدات المعدة فلا تملك هذه القدرة، فلا يمكنها الاستفادة من NPN بنفس الطريقة إطلاقاً.'},
{q:'ما الميزة العملية الأهم لمقياس NDF مقارنةً بمقياس "الألياف الخام" (CF) التقليدي؟',
opts:['NDF يشمل كل مكونات الجدار الخلوي بدقة أعلى من الألياف الخام التقليدية','NDF أرخص تكلفة في القياس المخبري من الألياف الخام في كل الأحوال','لا فرق حقيقي بينهما، وهما اسمان مختلفان لنفس القياس بالضبط','الألياف الخام التقليدية أدق من NDF في كل أنواع الأعلاف بلا استثناء'],
cor:0,exp:'مقياس الألياف الخام التقليدي يفقد جزءاً من الألياف الحقيقية أثناء التحليل، بينما يشمل NDF كل مكونات الجدار الخلوي (هيميسليلوز وسليلوز ولجنين) بدقة أعلى، ولهذا أصبح المعيار العالمي المعتمد اليوم في تقييم الألياف بالمعامل الجادة.'},
{q:'لماذا تُستخدم "الدهون المحمية من الكرش" (Rumen-Protected Fat) في علائق الأبقار عالية الإنتاج تحديداً؟',
opts:['لتعويض نقص المعادن الكبرى في العليقة دون أي علاقة حقيقية بالطاقة أصلاً','لأنها المصدر الوحيد الممكن للطاقة في أي عليقة حديثة على الإطلاق','لأنها أرخص بكثير من أي مصدر طاقة تقليدي آخر متاح في السوق المحلي','لرفع كثافة الطاقة في العليقة دون تعطيل التخمر الميكروبي الطبيعي في الكرش'],
cor:3,exp:'الدهن العادي بكميات كبيرة قد يُعطّل عمل الكائنات الدقيقة في الكرش. الدهون المحمية مُعالَجة لتمرّ عبر الكرش دون تفاعل معه، فتُهضَم لاحقاً في الأمعاء الدقيقة وتمنح طاقة إضافية مركّزة دون التأثير على التخمر الكرشي الطبيعي.'},
{q:'لماذا يُعد النحاس مثالاً كلاسيكياً على مخاطر "زيادة المعادن الصغرى" رغم كونه معدناً أساسياً ضرورياً؟',
opts:['لأن نطاق الأمان بين الكمية المفيدة والسامة منه ضيق جداً، خصوصاً في الأغنام','لأنه لا فائدة حقيقية له في أي عليقة حيوانية على الإطلاق مهما كانت الكمية','لأنه يُصنَّف ضمن المعادن الكبرى لا الصغرى، فتزداد كمياته المطلوبة كثيراً','لأنه العنصر الوحيد الذي لا تحتاجه الدواجن إطلاقاً مقارنة بباقي الأنواع'],
cor:0,exp:'النحاس معدن ضروري بكميات دقيقة جداً (يُقاس بأجزاء بالمليون)، لكن الفارق بين الجرعة المفيدة والجرعة السامة منه ضيق نسبياً، والأغنام تحديداً أكثر حساسية له وأقل تحملاً من الأبقار، ما يجعله مثالاً كلاسيكياً على أن "الزيادة ليست دائماً أضمن من النقص".'},
{q:'ما الفرق العملي الأهم بين الفيتامينات الذوابة في الدهون (A,D,E,K) والذوابة في الماء (مجموعة B وC)؟',
opts:['الذوابة في الماء هي فقط من تتراكم وتُسبب تسمماً عند الإفراط في إعطائها','لا فرق حقيقي بينهما، وكلاهما يُطرَح بنفس السرعة والكفاءة من الجسم','الذوابة في الدهون لا يحتاجها الحيوان إطلاقاً وتُعد زائدة عن أي احتياج','الذوابة في الدهون تتراكم في الجسم فيرتفع خطر التسمم منها عند الإفراط'],
cor:3,exp:'الفيتامينات الذوابة في الدهون تُخزَّن في الكبد والأنسجة الدهنية، فقد تتراكم وتسبب تسمماً عند الإفراط لفترة طويلة. أما الذوابة في الماء فيُطرَح فائضها بسهولة نسبياً في البول، فخطر التسمم منها أقل بكثير مقارنة بالمجموعة الأولى.'},
{q:'ما السبب الرئيسي في أن نفس المادة العلفية قد تختلف قيمتها الغذائية من شحنة لأخرى حتى من نفس المورد؟',
opts:['لأن كل مادة علفية تُصنَّع صناعياً بمواصفة موحّدة تماماً لا تتغيّر بين الدفعات','لأن جهاز التحليل المخبري نفسه يُعطي نتائج عشوائية وغير موثوقة دوماً','لاختلاف عوامل مثل التربة والمناخ ومرحلة الحصاد وظروف التخزين والنقل','لأن التسمية التجارية للمادة تتغيّر باستمرار دون علاقة حقيقية بتركيبها'],
cor:2,exp:'تتأثر القيمة الغذائية الفعلية لأي مادة علفية بعوامل زراعية وبيئية عديدة كنوع التربة والمناخ والسلالة النباتية ومرحلة الحصاد، إضافة لظروف التخزين والنقل لاحقاً؛ لهذا قد تختلف نفس المادة من نفس المصدر بين شحنة وأخرى، ما يستدعي تحليل كل شحنة على حدة بدل الاعتماد فقط على جدول مرجعي عام.'},
{q:'ما الميزة الرئيسية لتقنية التحليل بالأشعة تحت الحمراء القريبة (NIRS) مقارنةً بالتحليل الكيميائي الرطب التقليدي؟',
opts:['تقتصر فائدتها على قياس الرطوبة فقط دون أي مكون غذائي آخر في العلف','سرعة كبيرة ونتائج خلال ثوانٍ دون الحاجة لأي تحضير كيميائي للعينة','تحتاج كميات أكبر بكثير من المواد الكيميائية الخطرة مقارنة بالطرق التقليدية','نتائجها أقل دقة بكثير من التحليل الكيميائي التقليدي في كل الحالات'],
cor:1,exp:'تعتمد تقنية NIRS على تمرير ضوء الأشعة تحت الحمراء على العينة مباشرة دون أي تحضير كيميائي، وتحليل نمط الانعكاس لتقدير البروتين والدهن والألياف والرطوبة والنشا خلال ثوانٍ معدودة، بدقة قريبة جداً من التحليل الكيميائي التقليدي الذي يستغرق ساعات أو أياماً.'}
]},
fd3:{title:'اختبار المحاضرة الثالثة — احتياجات الحيوانات من العناصر الغذائية',questions:[
{q:'ما جوهر "الطريقة العاملية" (Factorial Method) في بناء جداول الاحتياجات الغذائية؟',
opts:['الاعتماد فقط على وزن الحيوان وحده لتقدير كل احتياجاته الغذائية دون أي عامل آخر','حساب كل عامل كالصيانة والنمو والحمل والإنتاج على حدة، ثم جمعها لاحتياج كلي','قياس الاحتياج الكلي للحيوان دفعة واحدة دون تقسيمه لأي عوامل فرعية منفصلة','استخدام متوسط ثابت واحد لكل الحيوانات من نفس النوع بصرف النظر عن أي فرق'],
cor:1,exp:'تعتمد المؤسسات المرجعية كـNASEM على حساب كل عامل من عوامل الاحتياج (الصيانة، والنمو، والحمل، والإنتاج) بشكل منفصل أولاً، ثم جمع كل العوامل المنطبقة على حالة الحيوان لتكوين احتياجه الكلي الفعلي في تلك المرحلة تحديداً.'},
{q:'ما الترتيب الصحيح لمسار تقسيم الطاقة بدءاً من الطاقة الكلية في العلف؟',
opts:['الطاقة الصافية (NE) ثم الممثلة (ME) ثم المهضومة (DE) ثم الكلية (GE) أخيراً','الطاقة الممثلة (ME) ثم الصافية (NE) ثم الكلية (GE) ثم المهضومة (DE)','لا يوجد ترتيب ثابت، وتختلف تسلسل هذه الأنواع باختلاف نوع العلف المُستخدَم','الطاقة الكلية (GE) ثم المهضومة (DE) ثم الممثلة (ME) ثم الصافية (NE) أخيراً'],
cor:3,exp:'يبدأ المسار من الطاقة الكلية (GE) التي تُقاس بحرق العينة كاملة، ثم تُطرَح فواقد الروث للحصول على DE، ثم فواقد البول والغازات للحصول على ME، ثم زيادة الحرارة أخيراً للحصول على الطاقة الصافية (NE) التي يستخدمها الجسم فعلياً.'},
{q:'أي نظام طاقة هو الأكثر شيوعاً في جداول احتياجات الدواجن تحديداً؟',
opts:['الطاقة المهضومة (DE) فقط دون أي نظام آخر بديل لها في أي جدول مرجعي','الطاقة الصافية (NEm/NEg/NEl) كما في الأبقار بالضبط دون أي فرق حقيقي','الطاقة الممثلة (ME)، غالباً بوحدة كيلو كالوري لكل كجم علف مُقدَّم','لا تستخدم الدواجن أي نظام طاقة محدد في جداولها المرجعية إطلاقاً'],
cor:2,exp:'تعتمد جداول احتياجات الدواجن غالباً على الطاقة الممثلة (ME) كمقياس رئيسي، بعكس الأبقار التي تعتمد أنظمة الطاقة الصافية (NE) الأكثر دقة لتنبؤ أدائها المعقّد عبر الكرش والتخمر الميكروبي.'},
{q:'لماذا تحتاج عليقة بقرة عالية الإدرار أحياناً لمصدر بروتين "محمي" يرفع نسبة RUP إلى جانب المصادر العادية؟',
opts:['لأن الكائنات الدقيقة في الكرش لا تحتاج أي بروتين متحلل (RDP) إطلاقاً في هذه الحالة','لأن البروتين المحمي أرخص ثمناً من أي مصدر بروتين عادي متاح في السوق دوماً','لأن الأبقار عالية الإدرار لا تستطيع هضم أي بروتين عابر (RUP) نهائياً بأي حال','لأن البروتين الميكروبي الناتج من تخمّر RDP وحده قد لا يكفي احتياج الإنتاج المرتفع'],
cor:3,exp:'قد يفوق احتياج البروتين لدى البقرة عالية الإنتاج ما يمكن أن ينتجه الكرش ميكروبياً من RDP وحده. لذلك تُضاف مصادر بروتين "محمية" ترفع نسبة RUP العابر الذي يصل مباشرة للأمعاء الدقيقة، لتكمل الفارق دون التأثير على توازن التخمر الكرشي الطبيعي.'},
{q:'ما المفهوم الذي تعتمد عليه جداول احتياجات البروتين للدواجن ووحيدات المعدة بدلاً من نظام RDP/RUP الخاص بالمجترات؟',
opts:['عدم وجود أي نظام محدد لتقدير احتياج البروتين لدى هذه الأنواع من الأساس','البروتين المثالي (Ideal Protein) وتركيبة الأحماض الأمينية المحدِّدة كالليسين','نفس نظام RDP/RUP بالضبط دون أي تعديل، لأنه عام لكل الأنواع الحيوانية','الاعتماد فقط على رقم البروتين الخام الكلي دون النظر لأي تفصيل آخر إطلاقاً'],
cor:1,exp:'لا تملك الدواجن ووحيدات المعدة كرشاً وتخميراً ميكروبياً واسعاً، لذا لا ينطبق عليها نظام RDP/RUP. بدلاً من ذلك تعتمد جداولها على مفهوم "البروتين المثالي": تركيبة دقيقة من الأحماض الأمينية الأساسية بالنسب التي يحتاجها الحيوان فعلياً، مع تركيز خاص على الأحماض الأمينية المحدِّدة.'},
{q:'لماذا يُعامَل الماء علمياً كعنصر غذائي أساسي رغم أنه لا يُحسَب عادة ضمن "المغذيات" في الحديث اليومي؟',
opts:['لأنه يحتوي على تركيز عالٍ جداً من البروتين والمعادن مقارنة بمعظم الأعلاف','لأن الجسم يخزّنه لفترات طويلة جداً فلا حاجة متجددة له مطلقاً في أي وقت','لأنه المصدر الوحيد للطاقة المتاح لأي حيوان في أي عليقة حديثة على الإطلاق','لأن نقصه القصير يؤثر على استهلاك العلف والأداء بسرعة تفوق أي عنصر آخر'],
cor:3,exp:'رغم عدم وجود سعرات حرارية أو بروتين في الماء نفسه، فإن نقصه ينعكس بسرعة كبيرة وبشدة على استهلاك العلف والأداء الإنتاجي، غالباً أسرع من ظهور أي أثر لنقص عنصر غذائي آخر، ما يجعله عنصراً غذائياً أساسياً له احتياج محسوب مثل باقي العناصر تماماً.'},
{q:'لماذا يُستخدم "الوزن الأيضي" (الوزن مرفوعاً للأس 0.75) بدلاً من الوزن الفعلي المباشر عند حساب احتياجات الصيانة؟',
opts:['لأن هذا الأس يُستخدم حصرياً في الدواجن دون أي نوع حيواني آخر على الإطلاق','لأن معدل الأيض الأساسي في الجسم يرتبط بالوزن بعلاقة غير خطية أقرب لهذا الأس','لأنه يجعل الحسابات دائماً أبسط حتى لو لم يعكس أي حقيقة بيولوجية فعلية','لأن الوزن الفعلي المباشر غير قابل للقياس بدقة في أغلب المزارع التجارية'],
cor:1,exp:'أثبتت الدراسات العلمية أن معدل الأيض الأساسي لا يتناسب خطياً مع حجم الجسم الفعلي، بل بعلاقة أقرب للأس 0.75؛ فحيوان وزنه ضعف حيوان آخر لا يحتاج بالضرورة ضعف الطاقة تماماً. لهذا تُستخدم هذه الصيغة لحساب احتياجات الصيانة بدقة أعلى عبر أوزان مختلفة.'},
{q:'لماذا يحتاج الحيوان الصغير عادة تركيزاً غذائياً أعلى نسبياً لكل وحدة وزن من الجسم مقارنة بالحيوان البالغ؟',
opts:['لأن الحيوانات الصغيرة تحتاج طاقة أقل بكثير من البالغة في كل الأحوال والظروف','لا علاقة حقيقية بين عمر الحيوان وتركيز العليقة المطلوبة له في أي وقت من الأوقات','لأن معدل نموه أسرع نسبياً لحجمه مقارنة بالحيوان البالغ الذي توقف نموه تقريباً','لأن جهازها الهضمي أكبر حجماً نسبياً من جهاز الحيوان البالغ في كل الحالات'],
cor:2,exp:'يمر الحيوان الصغير بمرحلة نمو سريعة نسبياً لحجمه، فيحتاج عليقة أعلى تركيزاً في الطاقة والبروتين لكل وحدة وزن مقارنة بالحيوان البالغ الذي يغطي احتياج الصيانة أساساً مع إنتاج محدود نسبياً بعد اكتمال النمو الأساسي.'},
{q:'لماذا قد تحتاج أبقار في منطقة مناخية حارة صيفاً احتياج صيانة أعلى من أبقار مطابقة لها في الوزن والسلالة لكن في مناخ معتدل؟',
opts:['لأن الأبقار في المناخ الحار تستهلك طاقة إضافية لتنظيم حرارة جسمها الداخلية','لا فرق حقيقي بينهما إطلاقاً، والمناخ لا يؤثر على احتياج الصيانة بأي شكل','لأن الأبقار في المناخ الحار تتوقف عن أي نمو أو إنتاج بشكل كامل ونهائي','لأن جداول الاحتياجات العالمية مصمَّمة خصيصاً للمناخات الحارة فقط دون غيرها'],
cor:0,exp:'الإجهاد الحراري يرفع احتياجات الصيانة نفسها، لأن الجسم يستهلك طاقة إضافية في آليات تنظيم الحرارة كزيادة معدل التنفس. لهذا تحتاج برامج التغذية تعديلاً بحسب الظروف المناخية المحلية بدلاً من تطبيق جدول عالمي موحّد دون أي تعديل.'},
{q:'بقرة حلوب احتياج صيانتها 12 ميجاكالوري طاقة صافية يومياً، وتنتج 25 كجم حليب يحتاج كل كيلوجرام منه 0.74 ميجاكالوري إضافية. ما إجمالي احتياجها اليومي؟',
opts:['25 ميجاكالوري بالضبط بصرف النظر عن احتياج الصيانة الأساسي للبقرة نفسها','12 ميجاكالوري فقط دون أي إضافة تُذكر بصرف النظر عن إنتاجها من الحليب','29.5 ميجاكالوري بعد جمع احتياج الصيانة مع احتياج إنتاج الحليب الكلي معاً','18.5 ميجاكالوري بعد ضرب كمية الحليب في القيمة المطلوبة لكل كيلوجرام فقط'],
cor:2,exp:'احتياج إنتاج الحليب = 25 × 0.74 = 18.5 ميجاكالوري. الاحتياج الكلي = احتياج الصيانة + احتياج الإنتاج = 12 + 18.5 = 29.5 ميجاكالوري يومياً، وهذا تطبيق مباشر للطريقة العاملية التي تعلمتها في هذه المحاضرة.'}
]},
fd4:{title:'اختبار المحاضرة الرابعة — هضم وامتصاص المغذيات في المجترة وغير المجترة',questions:[
{q:'ما الفارق الجوهري بين الخيل والدواجن رغم أن كليهما "وحيد المعدة" من الناحية التشريحية؟',
opts:['لا فرق حقيقي بينهما إطلاقاً، وكلاهما يهضم بنفس الطريقة تماماً بلا استثناء','الخيل يمتلك أعوراً وقولوناً ضخمين يُخمّران الألياف ميكروبياً، بعكس الدواجن محدودة القدرة','الدواجن هي من تُخمّر الألياف ميكروبياً بكفاءة عالية، بعكس الخيل عديم التخمر تماماً','الخيل يمتلك كرشاً متعدد الحجرات تماماً كالأبقار، بعكس الدواجن ذات المعدة البسيطة'],
cor:1,exp:'رغم أن كليهما وحيد المعدة (لا يملك كرشاً متعدد الحجرات)، يمتلك الخيل أعوراً وقولوناً ضخمين يقومان بتخمر ميكروبي حقيقي للألياف في نهاية القناة الهضمية، بينما تخمر الدواجن في أعورَيها محدود القدرة نسبياً ولا يُعد مصدراً رئيسياً للطاقة.'},
{q:'ما ترتيب مرور العلف الصحيح عبر حجرات معدة المجترات الأربع بدءاً من البلع؟',
opts:['الشبكية، ثم الإنفحة، ثم الكرش، ثم الورقية أخيراً في نهاية المسار','لا يوجد ترتيب ثابت لمرور العلف، ويختلف باختلاف نوع المادة العلفية المُقدَّمة','الإنفحة، ثم الورقية، ثم الشبكية، ثم الكرش أخيراً في نهاية المسار','الكرش، ثم الشبكية، ثم الورقية، ثم الإنفحة أخيراً في نهاية المسار'],
cor:3,exp:'يدخل العلف الكرش أولاً كأكبر الحجرات وموقع معظم التخمر، ثم الشبكية العاملة معه كوحدة شبه واحدة، ثم الورقية التي تمتص الماء وتُصغّر الجزيئات، وأخيراً الإنفحة حيث يبدأ الهضم الإنزيمي الحقيقي بالحمض والببسين.'},
{q:'أي الأحماض الدهنية الطيارة الثلاثة يُعد المصدر الأساسي لتصنيع دهن الحليب في الأبقار الحلوب؟',
opts:['الخليك، وهو الحمض الأكثر إنتاجاً غالباً في العلائق الغنية بالمواد الخشنة','البيوتيريك، لأنه المصدر الوحيد للطاقة المباشرة في جدار الكرش نفسه فقط','البروبيونيك، وهو نفسه السليفة الأساسية لتصنيع الجلوكوز في الكبد أيضاً','لا فرق بين الأحماض الثلاثة في هذا الدور، وكلها بنفس الأهمية بالضبط له'],
cor:0,exp:'الخليك (Acetate) هو المصدر الأساسي لتصنيع دهن الحليب في الغدة اللبنية، وترتفع نسبته نسبياً في العلائق الغنية بالمواد الخشنة، بعكس البروبيونيك الذي يرتفع في العلائق عالية الحبوب ويُستخدَم أساساً لتصنيع الجلوكوز لا الدهن.'},
{q:'لماذا لا يتجمع الحليب في كرش العجل الرضيع رغم مروره عبر منطقة المريء والكرش تشريحياً؟',
opts:['لأن الحليب يتبخر بالكامل قبل وصوله لأي جزء من الجهاز الهضمي للعجل الرضيع','لأن كرش العجل الرضيع يكون في الغالب ممتلئاً بالعلف الصلب مسبقاً فلا يتسع للحليب','لأن الأخدود المريئي ينغلق انعكاسياً أثناء الرضاعة، فيوصّل الحليب مباشرة للإنفحة','لأن الكائنات الدقيقة في كرش العجل الرضيع تُحلّل الحليب فوراً دون أي تجمّع'],
cor:2,exp:'ينغلق تجويف يُسمى الأخدود المريئي انعكاسياً بفعل تحفيز الرضاعة، فيتحول الحليب مباشرة من المريء إلى الإنفحة متجاوزاً الكرش والشبكية تماماً، ما يمنع تجمّعه وتخمّره بشكل ضار في هذه المرحلة المبكرة من العمر.'},
{q:'ما المحفّز الفسيولوجي الحقيقي الذي يدفع كرش العجل الصغير للنمو والتطور استعداداً للفطام؟',
opts:['تناول العلف الصلب، وما ينتج عن تخمره من أحماض دهنية طيارة كالبروبيونيك','زيادة كمية الحليب أو بديله المُقدَّمة للعجل يومياً بصرف النظر عن أي عامل آخر','إبقاء العجل بعيداً تماماً عن أي مصدر غذائي صلب لأطول فترة زمنية ممكنة قبل الفطام','درجة حرارة الحظيرة المحيطة بالعجل فقط، بصرف النظر تماماً عن نوع الغذاء المُقدَّم'],
cor:0,exp:'لا يتطور الكرش بتناول الحليب، لأنه يتجاوزه عبر الأخدود المريئي أصلاً. المحفّز الحقيقي هو تناول علف صلب (كالعلف البادئ)، حيث تُحفّز الأحماض الدهنية الطيارة الناتجة عن تخمره، وتحديداً البروبيونيك والبيوتيريك، نمو حليمات الكرش الماصة.'},
{q:'ما السبب الأشيع للإصابة بالحماض الكرشي (Ruminal Acidosis) في أبقار التسمين؟',
opts:['انخفاض درجة حرارة الجو المحيط بالحيوان بشكل مفاجئ وحاد لفترة قصيرة','زيادة نسبة الألياف الخشنة في العليقة بشكل تدريجي وبطيء على مدى أسابيع','التحول المفاجئ من علف خشن إلى مركّزات عالية النشا دون تدرّج كافٍ للتكيف','نقص شديد ومفاجئ في كمية الماء المتاحة للحيوان دون أي علاقة بنوع العلف'],
cor:2,exp:'التحول المفاجئ من علف خشن إلى مركّزات غنية بالنشا يجعل بكتيريا منتجة لحمض اللاكتيك تتكاثر بسرعة كبيرة، فينخفض الرقم الهيدروجيني للكرش بشدة ويضر ببطانته. التدرّج التدريجي على مدى أسبوعين تقريباً يمنح الكائنات الدقيقة وقتاً كافياً للتكيف.'},
{q:'ما وظيفة "القونصة" (Gizzard) تحديداً في الجهاز الهضمي للدواجن؟',
opts:['امتصاص معظم العناصر الغذائية النهائية عبر زغابات دقيقة متخصصة فيها','تخزين الغذاء مؤقتاً فقط بعد المريء دون أي دور ميكانيكي أو كيميائي فيها','إفراز حمض الهيدروكلوريك وإنزيم الببسين لبدء الهضم الكيميائي الحقيقي','طحن الغذاء ميكانيكياً، أحياناً بمساعدة حصى صغيرة، تعويضاً عن غياب الأسنان'],
cor:3,exp:'القونصة عضو عضلي قوي جداً يطحن الغذاء ميكانيكياً، أحياناً بمساعدة حصى صغيرة (Grit) يبتلعها الطائر عمداً لهذا الغرض تحديداً، معوّضاً بذلك غياب الأسنان تماماً عند الطيور، بينما يحدث الهضم الكيميائي في عضو مختلف هو المعدة الغدية.'},
{q:'مربي خيول غيّر نوع العلف المركّز فجأة وبكمية كبيرة، معتمداً على أن الخيل ليس مجتراً فلن يتأثر مثل الأبقار. ما التقييم الأصح لهذا الافتراض؟',
opts:['افتراض صحيح تماماً، فالخيل بلا كرش لا يتأثر بأي تحول مفاجئ في نوع العلف إطلاقاً','افتراض خاطئ؛ أعور الخيل وقولونه الضخمان يتأثران بنفس منطق التحول المسبب للحماض','افتراض صحيح جزئياً فقط في حالة المهور الصغيرة دون الخيول البالغة تحديداً','لا علاقة حقيقية بين نوع الجهاز الهضمي وسرعة تغيير العلف في أي حيوان مهما كان'],
cor:1,exp:'رغم أن الخيل ليس مجتراً، فإن أعوره وقولونه الضخمين بهما تخمر ميكروبي حقيقي حساس لنفس منطق التحول المفاجئ الذي يسبب الحماض في المجترات، وقد يؤدي التغيير المفاجئ لمغص شديد أو حتى التهاب صفائح القدم عند الخيول تحديداً.'},
{q:'لماذا تحتاج الدواجن والخنازير عموماً علائق أعلى تركيزاً وأقل ألياف مقارنة بالمجترات؟',
opts:['لأن أجهزتها الهضمية أكبر حجماً بكثير من أجهزة المجترات فتحتاج كمية أقل فقط','لأنها لا تحتاج طاقة أو بروتين بالقدر نفسه الذي تحتاجه المجترات في أي مرحلة','لأن الألياف مضرة بصحتها بشكل مباشر ومطلق بصرف النظر عن الكمية المُقدَّمة','لأنها لا تملك "مساعداً ميكروبياً" قوياً يُرقّي الألياف الرخيصة لطاقة وبروتين جيد'],
cor:3,exp:'المجترات تملك مصنعاً ميكروبياً ضخماً في الكرش يُرقّي الألياف الرخيصة والنيتروجين غير البروتيني لطاقة وبروتين عالي الجودة. الدواجن والخنازير لا تملك هذه الميزة بنفس القوة، فتعتمد مباشرة على ما تحتويه العليقة فعلياً من طاقة سهلة الهضم وأحماض أمينية جاهزة.'},
{q:'ما الرابط الفسيولوجي بين "انخفاض زمن الاجترار" لدى بقرة و"وجود مشكلة صحية أو غذائية محتملة"؟',
opts:['يرتبط زمن الاجترار فقط بعمر الحيوان دون أي علاقة بحالته الصحية الفعلية','انخفاض الاجترار غالباً من أول المؤشرات المبكرة لمشكلة، قبل ظهور أعراض أخرى','ارتفاع زمن الاجترار فقط هو من يدل على مشكلة صحية، لا انخفاضه بأي حال','لا رابط حقيقي بينهما، وزمن الاجترار لا يعكس أي حالة صحية للحيوان إطلاقاً'],
cor:1,exp:'الاجترار سلوك حساس جداً لحالة الحيوان العامة، ولذلك تراقب مزارع الألبان الحديثة زمنه يومياً بأجهزة استشعار؛ لأن انخفاضه المفاجئ غالباً ما ينذر بمشكلة صحية أو غذائية قبل ظهور أي أعراض مرضية واضحة أخرى بأيام أحياناً.'}
]},
fd5:{title:'اختبار المحاضرة الخامسة — تقييم الأعلاف وتحليل مكوناتها الغذائية',questions:[
{q:'ما الفرق الجوهري بين "تركيب" العلف و"تقييمه" الغذائي كما تعلمت في هذه المحاضرة؟',
opts:['لا فرق حقيقي بينهما، وكلاهما يقيس نفس الشيء تماماً بطريقتين مختلفتين فقط','التركيب يخبرك بما يحتويه العلف كيميائياً، والتقييم يخبرك بكمية ما يُستفاد منه فعلياً','التقييم يخص الأعلاف الخشنة فقط، والتركيب يخص المركّزات والحبوب حصراً','التركيب أدق علمياً من التقييم في كل الحالات، لذا لا حاجة فعلية للتقييم أصلاً'],
cor:1,exp:'التركيب الكيميائي (كنسبة البروتين أو الألياف) يخبرك بما يحتويه العلف نظرياً، بينما التقييم الغذائي (كقابلية الهضم أو RFV) يخبرك بكمية هذه المكونات المُستفاد منها فعلياً داخل جسم الحيوان، وقد يختلف الاثنان بشدة حتى لو تطابق التركيب الكيميائي بين مادتين.'},
{q:'لماذا تُعد التجربة الحيوانية (In Vivo) "المعيار الذهبي" رغم أنها غير عملية للاستخدام اليومي على كل شحنة؟',
opts:['لأنها الأدق في قياس قابلية الهضم الفعلية، وهي أساس معايرة الطرق الأسرع الأخرى','لأنها الأرخص تكلفة والأسرع تنفيذاً مقارنة بكل الطرق المعملية والكيسية الأخرى','لأنها الطريقة الوحيدة القادرة على كشف السموم الفطرية بدقة عالية جداً','لأنها لا تحتاج أي حيوانات فعلية، بل تعتمد فقط على المحاكاة الحاسوبية الرياضية'],
cor:0,exp:'التجربة الحيوانية المباشرة تقيس قابلية الهضم الفعلية على حيوان حي بدقة عالية جداً، لكنها بطيئة ومكلفة، فتُستخدم أساساً لبناء الجداول المرجعية ومعايرة طرق أسرع وأرخص كالتقييم المعملي والكيسي، لا لفحص كل شحنة واردة يومياً.'},
{q:'على أي مقياسين تُبنى معادلة "القيمة الغذائية النسبية" (RFV) للأعلاف الخشنة؟',
opts:['نسبة البروتين الخام ونسبة الدهن الخام في العينة المُحلَّلة فقط','السعر السوقي للكيلوجرام ونسبة الرطوبة في العينة المُحلَّلة فقط','الألياف المتعادلة (NDF) والألياف الحمضية (ADF) في العينة المُحلَّلة','نسبة الكالسيوم والفوسفور في العينة المُحلَّلة دون أي مقياس آخر'],
cor:2,exp:'تُبنى معادلة RFV على ADF لتقدير المادة الجافة المهضومة (DDM)، وعلى NDF لتقدير الاستهلاك المتوقع من وزن الجسم (DMI)، ثم يُجمع الناتجان في مؤشر واحد؛ وكلاهما مقياسان تعرفت عليهما في المحاضرة الثانية ضمن نظام فان سويست للألياف.'},
{q:'دريس برسيم ADF فيه 30% وNDF فيه 38%. ما القيمة الغذائية النسبية (RFV) التقريبية لهذه العينة؟',
opts:['نحو 95 تقريباً، وهي قيمة متوسطة الجودة نسبياً حسب مقياس RFV','نحو 40 تقريباً فقط، وهي قيمة منخفضة جداً تدل على جودة رديئة','نحو 300 تقريباً، وهي قيمة تفوق كل النطاق الطبيعي المعتاد لأي دريس','نحو 160 تقريباً، وهي قيمة ممتازة تعكس دريساً منخفض الألياف نسبياً'],
cor:3,exp:'DDM = 88.9 − (0.779×30) ≈ 65.5%. DMI = 120 ÷ 38 ≈ 3.16%. RFV = (65.5 × 3.16) ÷ 1.29 ≈ 160، وهي قيمة عالية جداً تقع ضمن فئة "ممتاز"، لأن كلا المقياسين (ADF وNDF) منخفضان نسبياً في هذه العينة.'},
{q:'ما الذي يمكن أن يكتشفه مزارع خبير بحواسه المجردة (لون، رائحة، ملمس) قبل أي تحليل مخبري رسمي؟',
opts:['مشكلات حقيقية كالعفن أو التخمر غير الطبيعي أو سوء التخزين المبكر','النسبة الدقيقة للبروتين الخام والدهن الخام في العينة بدقة تضاهي المعمل','لا شيء ذا قيمة حقيقية؛ التقييم الحسي غير علمي تماماً ولا يُعتد به إطلاقاً','القيمة الغذائية النسبية (RFV) بدقة كاملة دون أي حاجة لحساب رقمي'],
cor:0,exp:'يمكن للتقييم الحسي (اللون، الرائحة، الملمس، وجود عفن مرئي) اكتشاف مشكلات حقيقية كسوء التخزين أو التلف المبكر أو التخمر غير الطبيعي قبل وصول أي نتيجة معملية رسمية، رغم أنه لا يُغني عن التحليل الدقيق لتحديد الأرقام الفعلية.'},
{q:'لماذا لا يكفي تحليل البروتين والطاقة الجيد وحده للتأكد من أن شحنة علف آمنة تماماً للاستخدام؟',
opts:['لأن تحليل البروتين والطاقة غير موثوق أصلاً في أي معمل تجاري عادي مهما كان مستواه','لأن السموم الفطرية والعوامل المضادة للتغذية لا تظهر في هذا التحليل التقريبي المعتاد','لأن البروتين والطاقة لا علاقة لهما بسلامة العلف من الأساس في أي حال من الأحوال','لأن كل شحنات الأعلاف آمنة تلقائياً بمجرد اجتيازها لتحليل البروتين والطاقة فقط'],
cor:1,exp:'التحليل التقريبي المعتاد (بروتين، دهن، ألياف) لا يكشف عن وجود السموم الفطرية كالأفلاتوكسين أو العوامل المضادة للتغذية كمثبطات التربسين؛ فعلف "مثالي" كيميائياً قد يحمل مخاطر صحية حقيقية تحتاج فحصاً متخصصاً منفصلاً تماماً.'},
{q:'وفق مسح دي إس إم-فيرمينيش العالمي لعام 2025، ما النسبة التقريبية لعينات الأعلاف التي احتوت على أكثر من نوع واحد من السموم الفطرية في آنٍ واحد؟',
opts:['نحو 25% فقط من العينات المفحوصة، وهي نسبة منخفضة نسبياً حسب هذا المسح','لم تُسجَّل أي حالة تلوث مزدوج بأكثر من سم فطري واحد إطلاقاً في هذا المسح','أقل من 10% فقط من إجمالي العينات المفحوصة عالمياً ضمن هذا المسح الشامل','أكثر من 80% من إجمالي العينات المفحوصة عالمياً ضمن هذا المسح الشامل والحديث'],
cor:3,exp:'فحص المسح أكثر من 19,000 عينة من أكثر من 85 دولة، ووجد أن أكثر من 80% منها احتوت على أكثر من نوع واحد من السموم الفطرية معاً، مع ارتفاع مستويات كل الأنواع الستة الرئيسية مقارنة بالعام السابق، ما يعكس تحدياً متصاعداً لا خطراً نظرياً نادراً.'},
{q:'مصدر بروتين سعره أعلى للكيلوجرام لكن قابلية هضمه أعلى بكثير من مصدر أرخص. ما الأساس الأصح لمقارنتهما اقتصادياً؟',
opts:['اختيار الأرخص سعراً دائماً بلا أي حساب إضافي مهما كانت الفروق في الجودة','مقارنة تكلفة كل وحدة من البروتين المهضوم فعلياً بين المصدرين، لا السعر الخام','اختيار الأغلى سعراً دائماً باعتباره الأفضل تلقائياً دون أي حساب فعلي','تجاهل السعر تماماً والاعتماد فقط على نسبة البروتين الخام المكتوبة على الكيس'],
cor:1,exp:'المقارنة الاقتصادية السليمة تعتمد على تكلفة الوحدة الغذائية المهضومة فعلياً (كتكلفة كل كجم بروتين مهضوم)، وليس على سعر الكيلوجرام الخام وحده، لأن المصدر الأرخص ظاهرياً قد يكون أغلى فعلياً إذا انخفضت قابلية هضمه بشكل كبير.'},
{q:'ما الغرض العملي من "الحيوان المُناظَر" (Fistulated Animal) في تقنيتي التقييم المعملي والكيسي؟',
opts:['حساب الوزن الحي للحيوان بدقة أعلى من الميزان التقليدي العادي','قياس كمية الحليب المُنتَجة يومياً بدقة أعلى من الطرق المعتادة','تحديد عمر الحيوان بدقة أكبر من فحص الأسنان التقليدي المعروف','إتاحة الوصول المباشر لسائل الكرش، أو تعليق أكياس عينات داخله فعلياً'],
cor:3,exp:'الفتحة الجراحية الدائمة في الحيوان المُناظَر تتيح الوصول المباشر لسائل الكرش لاستخدامه في التقييم المعملي (كتقنية تيلي وتيري)، أو تعليق أكياس نايلون صغيرة بعينات علف داخل الكرش نفسه لقياس اختفائها تدريجياً في التقييم الكيسي.'},
{q:'ما الذي تشترك فيه مثبطات التربسين في فول الصويا الخام والجوسيبول في كسب بذرة القطن؟',
opts:['كلاهما عوامل مضادة للتغذية أو سامة محتملة لا تظهر في التحليل التقريبي المعتاد','كلاهما فيتامينات أساسية ضرورية يجب زيادتها عمداً في أي عليقة حديثة','كلاهما مصدر طاقة مركّز يُضاف عمداً لرفع كثافة الطاقة في العليقة','كلاهما معادن كبرى أساسية يجب حسابها ضمن نسبة الكالسيوم والفوسفور'],
cor:0,exp:'مثبطات التربسين تُعطِّل هضم البروتين إن لم تُعالَج حرارياً، والجوسيبول قد يكون ساماً خصوصاً لوحيدات المعدة والعجول الصغيرة؛ وكلاهما مثال على عوامل مضادة للتغذية أو سامة محتملة لا يكشفها التحليل التقريبي العادي، وتحتاج معرفة ومعالجة متخصصة قبل الاستخدام.'}
]},
fd6:{title:'اختبار المحاضرة السادسة — تصميم علائق الأبقار والجاموس الحلاب',questions:[
{q:'لماذا تُقسَّم أبقار المزرعة الحلابة إلى مجموعات إنتاجية بدلاً من عليقة واحدة للقطيع بأكمله؟',
opts:['لأن كل بقرة تحتاج علفاً مختلف النوع تماماً عن باقي أبقار القطيع دون أي تشابه','لأن التقسيم إجراء تجميلي فقط لا يؤثر على التكلفة أو الإنتاج الفعلي بأي شكل','لأن احتياجات الصيانة والإنتاج تختلف باختلاف مرحلة الإنتاج، فتحتاج فئات متجانسة','لأن القانون يُلزم كل مزرعة ألبان تجارية بتقسيم قطيعها إلى فئات منفصلة رسمياً'],
cor:2,exp:'تعلمت أن الاحتياج الكلي = صيانة + عوامل إنتاجية متغيرة، وهذه العوامل تختلف بشدة بين بقرة طازجة وأخرى في ذروة الإنتاج أو جافة. تقسيم القطيع لمجموعات متقاربة الاحتياج يتيح تصميم عليقة مناسبة اقتصادياً لكل فئة دون إهدار أو نقص.'},
{q:'بقرة وزنها 480 كجم. باستخدام تقدير 3.5% من وزن الجسم، ما الاستهلاك المتوقع تقريباً من المادة الجافة يومياً؟',
opts:['نحو 4.8 كجم فقط يومياً بصرف النظر عن مستوى إنتاجها الفعلي','نحو 48 كجم يومياً، وهي كمية كبيرة جداً غير واقعية لهذا الوزن','نحو 168 كجم يومياً حسب هذا التقدير التقريبي البسيط','نحو 16.8 كجم يومياً حسب هذا التقدير التقريبي البسيط'],
cor:3,exp:'480 × 0.035 = 16.8 كجم مادة جافة تقريباً، وهو تقدير أولي سريع يُستخدم كنقطة انطلاق قبل أي ضبط أدق بمعادلات مرجعية أكثر تفصيلاً.'},
{q:'لماذا يجب الحفاظ على حد أدنى من الألياف الخشنة في عليقة الأبقار الحلابة حتى عند السعي لرفع كثافة الطاقة؟',
opts:['لأن الألياف الخشنة تحتوي بروتيناً أعلى بكثير من أي مركّز متاح في السوق','تجاهل هذا الحد يرفع خطر الحماض الكرشي المزمن ويضر بصحة الكرش والإنتاج','لأن المركّزات ممنوعة قانونياً في تغذية الأبقار الحلابة في أغلب الدول','لا سبب حقيقي لذلك؛ الألياف الخشنة تفصيلة تقليدية يمكن الاستغناء عنها كلياً'],
cor:1,exp:'تعلمت في المحاضرة الرابعة أن التحول المفاجئ لعلف مركّز يسبب الحماض الكرشي؛ نفس المنطق ينطبق هنا: تجاوز الحد الأدنى الآمن من الألياف الخشنة يرفع خطر الحماض المزمن، وقد يقلل الإنتاج فعلياً رغم ارتفاع كثافة الطاقة الظاهرية على الورق.'},
{q:'ما الميزة الجوهرية للعليقة الكاملة المخلوطة (TMR) مقارنة بتقديم الخشن والمركّز منفصلَين؟',
opts:['تمنع الحيوان من الفرز الانتقائي، فيحصل على نسبة متوازنة في كل قضمة تقريباً','لا تحتاج أي معدات خلط خاصة على الإطلاق، وتُحضَّر يدوياً في كل الأحوال والظروف','تُلغي تماماً الحاجة لأي تحليل غذائي مسبق لمكونات العليقة قبل التقديم للحيوان','مناسبة فقط للقطعان الصغيرة جداً التي تقل عن عشرة رؤوس في المزرعة الواحدة'],
cor:0,exp:'خلط كل المكونات معاً يمنع الحيوان من اختيار الأجزاء الأكثر جاذبية وترك الباقي (الفرز الانتقائي)، فيضمن حصوله على نفس النسبة المتوازنة المُصمَّمة بعناية في كل قضمة، بعكس التغذية المنفصلة التي تسمح بهذا الفرز.'},
{q:'بقرة تحتاج 28 ميجاكالوري طاقة صافية يومياً. عليقة من 10 كجم سيلاج (1.4 ميجاكالوري/كجم) و10 كجم مركّز (1.8 ميجاكالوري/كجم). هل تكفي هذه العليقة احتياجها؟',
opts:['لا تكفي؛ العليقة توفر 25 ميجاكالوري فقط وهو أقل من الاحتياج البالغ 28','تكفي تماماً؛ العليقة توفر 32 ميجاكالوري وهو أكبر من الاحتياج البالغ 28','تكفي بالضبط دون أي هامش؛ العليقة توفر 28 ميجاكالوري بالتمام','لا يمكن الحكم دون معرفة نسبة البروتين في كلا المكونين أولاً'],
cor:1,exp:'الطاقة المُقدَّمة = (10×1.4) + (10×1.8) = 14 + 18 = 32 ميجاكالوري. بما أن 32 أكبر من الاحتياج (28)، فالعليقة تكفي بهامش أمان قدره 4 ميجاكالوري إضافية، بنفس منهجية التحقق التي تعلمتها في هذه المحاضرة.'},
{q:'لماذا يحتاج الجاموس الحلاب عادة طاقة أكبر نسبياً لإنتاج نفس حجم اللتر من الحليب مقارنة بالأبقار؟',
opts:['لأن الجاموس أثقل وزناً من كل سلالات الأبقار المعروفة دون أي استثناء يُذكر','لا يوجد فرق حقيقي في الاحتياج بين الجاموس والأبقار لإنتاج نفس حجم اللتر تماماً','لأن حليب الجاموس يحتوي عادة على نسبة دهن أعلى بكثير، ما يتطلب طاقة أكبر لتصنيعه','لأن الجاموس لا يستطيع هضم أي مركّزات على الإطلاق، فيعتمد فقط على المراعي الطبيعية'],
cor:2,exp:'يحتوي حليب الجاموس عادة على نسبة دهن تقارب ضعف نسبتها في حليب الأبقار، وبما أن دهن الحليب يُصنَّع أساساً من حمض الخليك الناتج عن التخمر الكرشي، فإن إنتاج نفس حجم اللتر من حليب الجاموس يتطلب طاقة إضافية حقيقية لتغطية هذا الدهن الزائد.'},
{q:'ما الذي يميّز "البقرة الانتقالية" (Transition Cow) عن باقي مراحل دورة الإنتاج؟',
opts:['هي المرحلة الوحيدة التي لا تحتاج فيها البقرة لأي ماء أو معادن إضافية إطلاقاً','هي أطول مرحلة في دورة الإنتاج الكاملة، وتمتد عادة لأكثر من ستة أشهر متواصلة','هي فترة الحلابة القياسية العادية تماماً دون أي حساسية غذائية خاصة تُذكر','هي الفترة الأكثر حساسية غذائياً حول الولادة، حيث تنخفض الشهية وتقفز الاحتياجات فجأة'],
cor:3,exp:'الفترة المحيطة بالولادة (نحو ثلاثة أسابيع قبلها وثلاثة بعدها) هي الأكثر حساسية في دورة إنتاج البقرة بأكملها: تنخفض الشهية طبيعياً مع اقتراب الولادة، بينما تقفز الاحتياجات فجأة بعدها مع بدء إدرار الحليب، ما يخلق فجوة طاقة سلبية شبه حتمية لفترة قصيرة.'},
{q:'ما الهدف الأساسي من ضبط "فرق الكاتيونات والأنيونات الغذائي" (DCAD) في عليقة الأبقار قريبة الولادة؟',
opts:['زيادة إنتاج الحليب فوراً بعد الولادة مباشرة بصرف النظر عن أي مخاطر محتملة','المساعدة في الوقاية من نقص الكالسيوم الحاد بعد الولادة المعروف بحمى الحليب','خفض تكلفة العليقة في هذه المرحلة الحرجة تحديداً دون أي هدف صحي آخر مقصود','تعويض نقص الطاقة الكلي في عليقة البقرة الجافة قبل الولادة مباشرة بالكامل'],
cor:1,exp:'ضبط توازن معادن معينة عبر مفهوم DCAD في عليقة الأبقار قريبة الولادة يساعد في الوقاية من نقص الكالسيوم الحاد (حمى الحليب) الذي قد يحدث نتيجة الطلب المفاجئ لإنتاج اللبأ والحليب بعد الولادة مباشرة، وليس هدفاً اقتصادياً أو إنتاجياً مباشراً.'},
{q:'في مثال المحاضرة المحلول (بقرة 600 كجم، إنتاج 25 كجم)، ما نسبة الخشن إلى المركّز تقريباً في العليقة المقترحة (12 كجم سيلاج و9 كجم مركّز)؟',
opts:['نحو 57% خشن مقابل 43% مركّز تقريباً من إجمالي المادة الجافة','نحو 90% خشن مقابل 10% مركّز فقط من إجمالي المادة الجافة','نحو 20% خشن مقابل 80% مركّز فقط من إجمالي المادة الجافة','نسبة متساوية تماماً بين الخشن والمركّز، أي 50% لكل منهما بالضبط'],
cor:0,exp:'12 كجم من إجمالي 21 كجم = 57.1% خشن، و9 كجم = 42.9% مركّز تقريباً. هذه نسبة واقعية ومعقولة لبقرة في هذا المستوى الإنتاجي، دون الاقتراب من الحد الأدنى الآمن للألياف الخشنة.'},
{q:'مزرعة صغيرة لديها 15 بقرة فقط، ويرى صاحبها أن تقسيمها لمجموعات إنتاجية "مبالغة" غير ضرورية لهذا الحجم. ما التقييم الأصح لهذا الرأي؟',
opts:['رأي صحيح تماماً؛ مبدأ التقسيم لا ينطبق إطلاقاً على القطعان الصغيرة دون العشرين رأساً','رأي خاطئ جزئياً؛ يمكن تحقيق نفس فكرة التمايز الغذائي بوسائل أبسط دون خلاطات ضخمة','رأي صحيح لأن كل الأبقار الخمس عشرة متطابقة الاحتياج تلقائياً بحكم صغر القطيع','لا علاقة لحجم القطيع بمبدأ التقسيم؛ القرار يعتمد فقط على السلالة المرباة'],
cor:1,exp:'حتى في القطعان الصغيرة يظل مبدأ التقسيم مفيداً، وإن لم يتطلب خلاطات ضخمة أو مجموعات فيزيائية منفصلة بالضرورة؛ يمكن تحقيق نفس الفكرة بتقديم كميات مركّز مختلفة يدوياً حسب إنتاج كل بقرة فوق عليقة أساسية مشتركة.'}
]},
fd7:{title:'اختبار المحاضرة السابعة — برامج تغذية عجول التسمين والأبقار النامية',questions:[
{q:'ما المؤشران الأساسيان اللذان تراقبهما برامج تغذية اللحم، بخلاف مؤشرات إنتاج الحليب في الألبان؟',
opts:['معدل الزيادة الوزنية اليومية (ADG) والكفاءة التحويلية للعلف (FCR)','نسبة الدهن في الحليب وكمية اللاكتوز المُنتَجة يومياً لكل حيوان','عدد مرات الحلب اليومية ومتوسط زمن كل جلسة حلب على حدة','نسبة البروتين في الحليب فقط دون أي مؤشر إنتاجي آخر يُحسَب'],
cor:0,exp:'يتحول الهدف في برامج تغذية اللحم من إنتاج سائل يومي إلى بناء أنسجة جديدة بأسرع معدل ممكن اقتصادياً، فيصبح معدل الزيادة الوزنية اليومية (ADG) والكفاءة التحويلية للعلف (FCR) هما المؤشران الأساسيان اللذان يخدمهما كل قرار تصميمي تقريباً.'},
{q:'لماذا لا يُنصَح عادة بتقديم عليقة تسمين عالية التركيز لعجل صغير مباشرة بعد الفطام؟',
opts:['لأن العجول الصغيرة لا تستطيع هضم أي مركّزات إطلاقاً مهما كانت الكمية المقدَّمة','قد يُسرِّع الترسيب الدهني قبل اكتمال النمو الهيكلي والعضلي المطلوب أولاً','لأن ذلك أرخص تكلفة من مرحلة تنمية تقليدية بكثير في كل الأحوال والظروف','لأن القانون يمنع تقديم أي مركّزات للعجول قبل بلوغها عمر سنة كاملة'],
cor:1,exp:'وفق مبدأ النمو التفاضلي، يستثمر العجل الصغير موارده أساساً في بناء الهيكل العظمي والعضلي أولاً؛ تغذية عالية الطاقة مبكرة جداً تُخاطر بدفع الجسم نحو ترسيب دهني قبل أوانه، على حساب اكتمال الإطار الهيكلي والعضلي المرغوب اقتصادياً.'},
{q:'وفق مبدأ النمو التفاضلي الذي وثّقه جون هاموند، ما ترتيب تتابع نمو أنسجة الجسم الرئيسية؟',
opts:['الدهن أولاً، ثم العضلة، ثم العظم أخيراً في نهاية التسلسل الزمني','العضلة أولاً، ثم الدهن، ثم العظم أخيراً في نهاية التسلسل الزمني','تنمو الأنسجة الثلاثة بنفس المعدل تماماً دون أي تفاوت حقيقي بينها','العظم أولاً، ثم العضلة، ثم الدهن الذي يتسارع قرب النضج تحديداً'],
cor:3,exp:'وثّق هاموند أن العظم أسرع نمواً نسبياً في المراحل المبكرة، تليه العضلة بمعدل متوسط يمتد لفترة أطول، ثم الدهن الذي يتسارع ترسيبه بقوة قرب اكتمال النضج ومرحلة التسمين تحديداً.'},
{q:'لماذا تكون قيمة "الطاقة الصافية للنمو" (NEg) لعلف معين أقل دائماً من قيمة "الطاقة الصافية للصيانة" (NEm) لنفس العلف؟',
opts:['لأن كفاءة استخدام الجسم للطاقة في بناء أنسجة جديدة أقل من كفاءتها في الصيانة','لأن NEg تُقاس بوحدات مختلفة تماماً عن NEm في كل الجداول المرجعية','لأن NEg تخص الدواجن فقط، ولا تُحسب إطلاقاً لأبقار اللحم أصلاً','لا سبب علمي حقيقي؛ الفارق تقليدي بين المراجع دون أي أساس بيولوجي'],
cor:0,exp:'جزء من الطاقة المخصصة لبناء أنسجة جديدة يُفقَد كحرارة إضافية أثناء عملية البناء نفسها، أكثر مما يحدث عند استخدام الطاقة للصيانة وحدها؛ ولهذا السبب البيولوجي الدقيق تكون NEg دائماً أقل رقمياً من NEm لنفس العلف بالضبط.'},
{q:'عجل نامٍ احتياج صيانته 6 ميجاكالوري NEm. عليقة من 7 كجم مادة جافة قيمتها NEm = 1.6 ميجاكالوري/كجم. هل تغطي هذه العليقة احتياج الصيانة؟',
opts:['لا يمكن الحكم دون معرفة قيمة NEg للعليقة نفسها أولاً قبل أي حساب','لا تغطيه؛ العليقة توفر 9.2 ميجاكالوري وهو أقل من الاحتياج البالغ 6','تغطيه بفائض؛ العليقة توفر 11.2 ميجاكالوري وهو أكبر من الاحتياج البالغ 6','تغطيه بالضبط دون أي هامش؛ العليقة توفر 6 ميجاكالوري بالتمام تقريباً'],
cor:2,exp:'الطاقة المتاحة = 7 × 1.6 = 11.2 ميجاكالوري. بما أن 11.2 أكبر من احتياج الصيانة (6)، فالعليقة تغطي الصيانة بفائض 5.2 ميجاكالوري متاح للنمو، بنفس منهجية الفحص المزدوج التي تعلمتها في هذه المحاضرة.'},
{q:'ما المقصود بظاهرة "النمو التعويضي" (Compensatory Growth)؟',
opts:['انخفاض دائم غير قابل للتعويض في معدل النمو طوال حياة الحيوان بأكملها','ظاهرة تخص الدواجن فقط، ولا تنطبق على الأبقار أو أي مجترات أخرى','توقف النمو نهائياً بعد أي فترة تغذية محدودة بصرف النظر عن العليقة اللاحقة','تسارع النمو بعد فترة تغذية محدودة عند الانتقال لعليقة أغنى بالطاقة'],
cor:3,exp:'حيوان مرّ بفترة تغذية محدودة نسبياً ثم انتقل لعليقة عالية الطاقة يُظهر غالباً معدل نمو أسرع من المعتاد لفترة، وكأن الجسم يعوّض جزئياً ما فاته سابقاً، وهي ظاهرة اقتصادية تُستغَل عمداً في كثير من أنظمة إنتاج اللحوم حول العالم.'},
{q:'عجل استهلك 270 كجم علف خلال 30 يوماً، واكتسب 45 كجم وزناً حياً إضافياً. ما الكفاءة التحويلية (FCR) لهذه الفترة؟',
opts:['نحو 1.5 كجم علف لكل كجم زيادة وزن فقط تقريباً','نحو 6 كجم علف لكل كجم زيادة وزن تقريباً فعلياً','نحو 9 كجم علف لكل كجم زيادة وزن تقريباً فعلياً','نحو 0.17 كجم علف لكل كجم زيادة وزن فقط تقريباً'],
cor:1,exp:'FCR = 270 ÷ 45 = 6 كجم علف لكل كجم زيادة وزن، وهو رقم جيد يقع ضمن المدى الواقعي المتوقع لبرنامج تسمين فعّال (تقريباً 6-9 كجم علف لكل كجم زيادة وزن حسب المرحلة والسلالة).'},
{q:'لماذا تميل الكفاءة التحويلية للعلف (FCR) للارتفاع (أي تصبح أقل كفاءة) كلما اقترب الحيوان من وزنه الناضج؟',
opts:['لأن نسبة الترسيب الدهني ترتفع، والدهن أغلى طاقياً في بنائه من العظم أو العضلة','لأن الحيوان يتوقف عن تناول أي علف تقريباً في هذه المرحلة المتأخرة تحديداً','لأن جودة العلف المُقدَّم تنخفض تلقائياً كلما تقدم عمر الحيوان نفسه','لا علاقة حقيقية بين عمر الحيوان أو وزنه وقيمة الكفاءة التحويلية إطلاقاً'],
cor:0,exp:'وفق مبدأ النمو التفاضلي، ترتفع نسبة الترسيب الدهني كلما اقترب الحيوان من نضجه، والدهن أكثر الأنسجة تكلفة طاقياً في بنائه مقارنة بالعظم أو العضلة؛ لهذا ترتفع الكفاءة التحويلية (FCR) تدريجياً، أي تصبح أقل كفاءة، مع تقدم مرحلة التسمين.'},
{q:'ما الوضع التنظيمي لمنشطات النمو (كالزرعات الهرمونية) في تسمين الأبقار عالمياً؟',
opts:['مسموحة بلا أي قيود تُذكر في كل دول العالم دون أي استثناء واحد','ممنوعة كلياً وبلا أي استثناء في كل الدول والأسواق حول العالم','غير موجودة أصلاً كتقنية، ولم تُستخدَم في أي نظام إنتاج حتى اليوم','يختلف بشدة بين الدول؛ بعضها يسمح تحت إشراف بيطري، وبعضها يحظرها'],
cor:3,exp:'يختلف الوضع التنظيمي لمنشطات النمو اختلافاً كبيراً بين الدول: بعضها يسمح باستخدامها تحت إشراف بيطري صارم، بينما يحظرها الاتحاد الأوروبي ودول أخرى كلياً؛ ما يستدعي الاستناد دوماً للتشريعات المحلية وشروط سوق التصدير المستهدف قبل أي قرار.'},
{q:'ما المقصود بـ"الرخام" (Marbling) في سياق تسمين الأبقار وجودة الذبيحة؟',
opts:['نوع خاص من الأعلاف المركّزة يُستخدَم حصراً في المراحل الأخيرة من التسمين','الدهن المتخلل داخل نسيج العضلة نفسها، وهو مؤشر جودة مهم في بعض الأسواق','مرض شائع يصيب العظام في الأبقار المُسمَّنة بعلائق عالية التركيز باستمرار','أداة قياس تُستخدَم لتقدير الوزن الحي للحيوان قبل الذبح مباشرة'],
cor:1,exp:'الرخام هو الدهن المتخلل داخل نسيج العضلة نفسها (لا الدهن الخارجي تحتها)، ويُعد مؤشر جودة مهماً في بعض أسواق اللحوم، ويرتبط مباشرة بمبدأ النمو التفاضلي إذ يتشكل أساساً في المراحل المتأخرة من التسمين مع تسارع ترسيب الدهن.'}
]},
fd8:{title:'اختبار المحاضرة الثامنة — برامج تغذية الأغنام والماعز',questions:[
{q:'ما الفارق السلوكي الغذائي الأساسي بين الأغنام والماعز في الرعي الحر؟',
opts:['الأغنام راعية تفضل العشب القريب من الأرض، والماعز متصفحة تفضل أوراق الشجيرات المرتفعة','الماعز راعية تفضل العشب القريب من الأرض، والأغنام متصفحة تفضل أوراق الشجيرات المرتفعة','كلاهما يعتمد فقط على المركّزات الجاهزة، ولا سلوك رعي طبيعي حقيقي لأي منهما','لا فرق سلوكي حقيقي بين النوعين؛ كلاهما يرعى بنفس الطريقة تماماً في كل الظروف'],
cor:0,exp:'تميل الأغنام طبيعياً للرعي، أي تناول العشب والنباتات القريبة من سطح الأرض، بينما تميل الماعز للتصفح الانتقائي لأوراق الشجيرات والأشجار على ارتفاعات مختلفة، وهو فارق سلوكي حقيقي له انعكاسات عملية على تصميم أنظمة الرعي المختلطة.'},
{q:'لماذا يجب تحديد الغرض الإنتاجي الأساسي (لحم، حليب، صوف) قبل تصميم أي برنامج تغذية لقطيع أغنام أو ماعز؟',
opts:['لأن القانون المحلي يُلزم بتصنيف كل قطيع حسب غرض إنتاجي واحد ثابت رسمياً','لأن نفس القطيع بالضبط قد يحتاج برنامجاً مختلفاً تماماً حسب الهدف الإنتاجي المحدد','لأن الأغنام والماعز لا يمكنها إنتاج أكثر من منتج واحد طوال حياتها بأي حال','لا سبب حقيقي لذلك؛ العليقة نفسها تناسب كل الأغراض الإنتاجية دون أي تمييز'],
cor:1,exp:'بعكس أبقار الألبان أو اللحم المُربّاة غالباً لغرض واحد واضح، كثيراً ما تُربَّى الأغنام والماعز لأكثر من غرض، ونفس القطيع بالضبط قد يحتاج برنامجاً مختلفاً تماماً حسب كون الهدف الأساسي إنتاج اللحم أو الحليب أو الصوف.'},
{q:'لماذا يرتفع احتياج الصيانة لكل كيلوجرام من وزن الجسم في حيوان صغير كالعنزة مقارنة بحيوان أكبر كالبقرة؟',
opts:['لأن العنزة تتحرك مسافات أطول بكثير يومياً من البقرة في كل الأنظمة الإنتاجية','لأن كفاءة هضم العنزة أقل بكثير من كفاءة هضم البقرة لنفس نوع العلف المُقدَّم','بسبب العلاقة غير الخطية بين الوزن ومعدل الأيض، فترتفع نسبة مساحة السطح للحجم','لا توجد علاقة حقيقية بين حجم الجسم واحتياج الصيانة لكل كيلوجرام في أي حيوان'],
cor:2,exp:'معدل الأيض لا يتناسب خطياً مع حجم الجسم (الوزن الأيضي = الوزن مرفوعاً للأس 0.75)، ما يعني ارتفاع نسبة مساحة سطح الجسم إلى حجمه في الأجسام الأصغر؛ ولهذا يرتفع احتياج الصيانة نسبياً لكل كيلوجرام واحد من وزن الحيوانات الصغيرة كالأغنام والماعز.'},
{q:'ما الهدف الأساسي من تقنية "الفلاشينج" (Flushing) في إدارة قطعان الأغنام والماعز؟',
opts:['علاج حالات نقص الوزن الحاد بعد الولادة مباشرة دون أي علاقة بالتناسل','خفض معدل التبويض لتقليل فرص التوائم أو الثلاثيات غير المرغوبة اقتصادياً','تسمين الإناث بسرعة قبل التسويق المباشر للحوم دون أي هدف تناسلي','رفع المستوى الغذائي قبل التناسل مباشرة لزيادة معدل التبويض والتوائم'],
cor:3,exp:'الفلاشينج هو رفع المستوى الغذائي، خصوصاً الطاقة، لفترة قصيرة (نحو أسبوعين إلى ثلاثة) قبل موسم التناسل مباشرة، بهدف رفع معدل التبويض وزيادة احتمال التوائم أو حتى الثلاثيات، وهي معدلات إنجاب شائعة نسبياً في هذين النوعين.'},
{q:'لماذا تُعد الأغنام أكثر عرضة لخطر التسمم النحاسي من الأبقار أو الماعز عملياً؟',
opts:['لأنها لا تحتاج أي نحاس في غذائها إطلاقاً بعكس باقي الأنواع الحيوانية','لأن جسمها يتخلص من كل النحاس الزائد فوراً دون أي تراكم حقيقي يُذكر','لأنها تتناول كميات نحاس أكبر بكثير من باقي الأنواع بحكم سلوكها الطبيعي','لأن جسمها يخزّن النحاس الزائد تدريجياً في الكبد حتى يصل مستوى خطير'],
cor:3,exp:'يخزّن جسم الأغنام النحاس الزائد تدريجياً في الكبد دون أعراض واضحة، حتى يحدث حدث مُجهِد فيُطلَق هذا النحاس المتراكم دفعة واحدة في الدم، مسبباً أزمة انحلال دموي حادة قد تكون قاتلة؛ ولهذا يجب تجنّب خلطات معدنية مخصصة للأبقار عند تغذية الأغنام.'},
{q:'وفق ما تعلمته عن العلاقة بين التغذية ومقاومة الطفيليات، ما الوصف الأدق لدور التغذية الجيدة في هذا السياق؟',
opts:['تُغني كلياً عن أي برنامج مكافحة بيطري متخصص للديدان المعوية بلا استثناء','تحسّن مقاومة الجهاز المناعي وسرعة التعافي، لكنها لا تحل محل المكافحة البيطرية','لا علاقة حقيقية بين مستوى التغذية ومقاومة الحيوان للطفيليات الداخلية إطلاقاً','تزيد فعلياً من شدة العدوى الطفيلية كلما ارتفع مستوى البروتين في العليقة'],
cor:1,exp:'أظهرت أبحاث حديثة أن التغذية الجيدة، وتحديداً كفاية البروتين، تُحسّن قدرة الجهاز المناعي على مقاومة العبء الطفيلي والتعافي منه بشكل أسرع، لكنها تعمل كخط دفاع إضافي مكمّل، لا بديلاً كاملاً عن برامج المكافحة البيطرية المتخصصة كمضادات الديدان.'},
{q:'ما الذي تُميّز به سلالات الأغنام "ذات الذيل السمين" الشائعة في المنطقة العربية؟',
opts:['عدم قدرتها على تخزين أي دهن في جسمها إطلاقاً مهما ارتفع مستوى التغذية','تخزين جزء كبير من احتياطي الدهن في الذيل بدلاً من توزيعه تحت الجلد بانتظام','إنتاجها حليباً فقط دون أي قدرة على إنتاج اللحم في أي ظرف من الظروف','حاجتها لعليقة خالية تماماً من أي مصدر طاقة مركّز طوال فترة حياتها'],
cor:1,exp:'تُخزِّن هذه السلالات، كالعواسي والنجدي، جزءاً كبيراً من احتياطي دهنها في الذيل بدلاً من توزيعه تحت الجلد بانتظام كما في كثير من السلالات الغربية، ما يستدعي معايير محلية مضبوطة لتقييم درجة قوام الجسم تأخذ حجم الذيل في الاعتبار.'},
{q:'نعجة تحتاج 1.8 ميجاكالوري طاقة صافية يومياً. عليقة من 1.2 كجم دريس (0.9 ميجاكالوري/كجم) و0.2 كجم مركّز (1.6 ميجاكالوري/كجم). ما التقييم الصحيح لهذه العليقة؟',
opts:['كافية تماماً بفائض كبير يتجاوز نصف ميجاكالوري إضافي عن الاحتياج','غير كافية؛ توفر 1.40 ميجاكالوري فقط، أقل من الاحتياج بفارق 0.4','كافية بالضبط دون أي فائض أو نقص يُذكر عن الاحتياج المطلوب','لا يمكن الحكم على كفايتها دون معرفة وزن النعجة الدقيق أولاً'],
cor:1,exp:'الطاقة المُقدَّمة = (1.2×0.9) + (0.2×1.6) = 1.08 + 0.32 = 1.40 ميجاكالوري، وهي أقل من الاحتياج (1.8) بفارق 0.4 ميجاكالوري؛ العليقة تحتاج تعديلاً برفع كمية المركّز لتغطية هذا الفارق.'},
{q:'لماذا يُعد استخدام خلطة معدنية واحدة موحّدة للأبقار والأغنام معاً في مزرعة مختلطة قراراً خطيراً؟',
opts:['لأن الأبقار لا تحتاج أي معادن في عليقتها إطلاقاً بعكس الأغنام تماماً','لأن الخلطة الموحّدة أغلى تكلفة دائماً من خلطتين منفصلتين مخصصتين لكل نوع','لأن مستوى النحاس المناسب للأبقار قد يكون خطيراً تراكمياً على الأغنام تحديداً','لا خطورة حقيقية في هذا القرار طالما الكمية المُقدَّمة يومياً صغيرة نسبياً'],
cor:2,exp:'خلطات المعادن المخصصة للأبقار تحتوي عادة نحاساً بمستوى آمن لها لكنه قد يكون خطيراً تراكمياً للأغنام الأكثر حساسية بكثير لهذا المعدن؛ استخدام الخلطة الخطأ من أشيع أسباب حالات التسمم النحاسي القاتلة في قطعان الأغنام عملياً.'},
{q:'ما المقصود بمصطلح "معدل التوائم" أو "الخصوبة الإنجابية" (Prolificacy) في سياق الأغنام والماعز؟',
opts:['عمر الأنثى عند أول ولادة لها في حياتها الإنتاجية الكاملة تقريباً','متوسط الوزن عند الولادة لكل مولود جديد يُسجَّل في القطيع بأكمله','عدد المواسم التناسلية الكاملة التي تمر بها الأنثى طوال حياتها','نسبة المواليد لكل أم في الموسم الواحد، وهي مرتفعة نسبياً في هذين النوعين'],
cor:3,exp:'يشير معدل التوائم أو الخصوبة الإنجابية إلى نسبة المواليد لكل أم في الموسم الواحد، وهي مرتفعة نسبياً في الأغنام والماعز مقارنة بالأبقار، ما يجعل تقنيات كالفلاشينج ذات قيمة اقتصادية حقيقية في هذين النوعين تحديداً.'}
]},
fd9:{title:'اختبار المحاضرة التاسعة — تغذية الدواجن ومراحل الإنتاج المختلفة',questions:[
{q:'ما الفرق الجوهري في الهدف الوراثي بين دجاج اللحم (Broiler) ودجاج البيض (Layer)؟',
opts:['دجاج البيض أسرع نمواً من دجاج اللحم في كل الظروف والأنظمة الإنتاجية','لا فرق حقيقي؛ كلاهما انتُخِب وراثياً لنفس الهدف بالضبط عبر العقود','دجاج اللحم لأقصى زيادة وزنية سريعة، ودجاج البيض لإنتاج مستمر لأكثر من عام','الفرق يقتصر على لون الريش الخارجي دون أي فرق إنتاجي حقيقي بينهما'],
cor:2,exp:'دجاج اللحم انتُخِب وراثياً لأقصى زيادة وزنية ممكنة خلال أسابيع قليلة، بينما انتُخِب دجاج البيض لإنتاج بيض مستمر ومستقر لأكثر من عام كامل؛ هدفان مختلفان جذرياً يحددان كل قرار غذائي لاحق في تصميم برنامج التغذية.'},
{q:'ما المنطق الاقتصادي وراء تقسيم برنامج تسمين الدجاج اللاحم إلى مراحل بادئ ونامٍ وناهٍ؟',
opts:['الاحتياج النسبي للبروتين يقل مع تقدم العمر، فعلف بادئ باهظ طوال الدورة يُهدر مالاً','القانون يُلزم بثلاث مراحل غذائية منفصلة على الأقل لكل قطيع تسمين تجاري','لا منطق اقتصادي حقيقي وراء هذا التقسيم؛ الأمر تقليدي صناعي فقط دون فائدة','كل مرحلة تحتاج لوناً مختلفاً تماماً من العلف لأسباب تسويقية بحتة لا غذائية'],
cor:0,exp:'الاحتياج النسبي للبروتين والأحماض الأمينية يقل تدريجياً مع تقدم عمر الطائر، فتقديم علف "بادئ" باهظ التكلفة طوال دورة الحياة كاملة يُهدر مالاً حقيقياً دون أي فائدة إنتاجية إضافية تُذكر بعد المراحل المبكرة.'},
{q:'ما الفائدة المزدوجة لإضافة أحماض أمينية صناعية مع خفض البروتين الخام الكلي في علائق الدواجن؟',
opts:['إبطاء معدل النمو عمداً لتحسين جودة اللحم النهائية على المدى الطويل','رفع تكلفة العليقة الكلية بشكل عام دون أي فائدة بيئية حقيقية مقابلة','زيادة نسبة الدهن في لحم الطائر فقط دون أي أثر إنتاجي آخر يُذكر','تكلفة أقل نسبياً وتلوث بيئي أقل بسبب انخفاض النيتروجين المطروح في الفضلات'],
cor:3,exp:'إضافة أحماض أمينية صناعية مستهدَفة (كالليسين والميثيونين) مع خفض البروتين الخام الكلي أرخص من رفع البروتين الكلي، وتقلل النيتروجين المطروح في فضلات الطائر، ما يقلل الأثر البيئي مقارنة بالعلائق التقليدية عالية البروتين الخام غير المُعدَّلة.'},
{q:'لماذا يحتاج الدجاج البياض تحديداً نوعاً خاصاً من العظم يُعرف بـ"العظم النخاعي" (Medullary Bone)؟',
opts:['لحماية الدجاجة من الإصابات الجسدية أثناء حركتها داخل العنبر يومياً','لدعم وزن الجسم الإضافي الناتج عن زيادة الشهية خلال موسم الإنتاج','لا علاقة حقيقية له بإنتاج البيض؛ خاصية عشوائية غير وظيفية فعلياً','لتخزين كالسيوم يُستنزَف ليلاً لتغطية احتياج تكلّس قشرة البيض'],
cor:3,exp:'يُعبَّأ العظم النخاعي بالكالسيوم خلال ساعات النهار مع تناول العلف، ثم يُستنزَف تدريجياً ليلاً لتغطية احتياج تكوين قشرة البيض، لأن معظم عملية التكلّس تحدث بينما الطائر لا يتغذى إطلاقاً خلال ساعات الليل.'},
{q:'دجاجة بياضة تستهلك 115 جرام علف يومياً من عليقة تحتوي 3.5% كالسيوم. كم جرام كالسيوم تتناول يومياً تقريباً؟',
opts:['0.4 جرام فقط، وهو رقم منخفض جداً وغير واقعي لأي عليقة بياض','4.0 جرام تقريباً، وهو رقم قريب من الهدف المرجعي الشائع (4 جرام)','40 جرام، وهو رقم مبالغ فيه بشدة ولا يمكن أن يكون صحيحاً منطقياً','1.15 جرام فقط، وهو أقل بكثير من الهدف المرجعي المعتاد للبياض'],
cor:1,exp:'الكالسيوم المُتناوَل = 115 × 0.035 = 4.025 جرام تقريباً، وهو رقم قريب جداً من الهدف المرجعي الشائع (4 جرام)، ما يعني أن هذه العليقة كافية تقريباً لتغطية احتياج تكوين قشرة البيض اليومي.'},
{q:'ما الفائدة العملية لاستخدام نسبة "الماء إلى العلف" كأداة مراقبة صحية في قطعان الدواجن؟',
opts:['لا فائدة عملية حقيقية؛ مراقبة استهلاك العلف وحده كافية تماماً دوماً','تحديد الوزن النهائي المتوقع للطائر عند التسويق بدقة عالية جداً','انحرافها المفاجئ ينذر غالباً بمشكلة صحية أو بيئية قبل ظهور أعراض أخرى واضحة','حساب الكمية الدقيقة من الأحماض الأمينية الصناعية المطلوبة يومياً للقطيع'],
cor:2,exp:'انخفاض مفاجئ في استهلاك الماء نسبياً للعلف قد يشير لمشكلة في جودة الماء أو نظام السقي، بينما ارتفاعها المفاجئ قد يشير لإجهاد حراري أو مشكلة صحية ناشئة، غالباً قبل أن تظهر أي أعراض واضحة أخرى على القطيع بأيام.'},
{q:'لماذا تلجأ أغلب برامج التسمين التجارية لتحويل العلف لشكل "مكعّب" (Pellet) بدلاً من إبقائه "مطحوناً" (Mash) بسيطاً؟',
opts:['العلف المكعّب أرخص تكلفة إنتاج دائماً من العلف المطحون في كل الحالات','لأن الطيور ترفض تناول أي علف مطحون بسيط مهما كانت جودته الغذائية','لمنع الفرز الانتقائي وضمان حصول كل طائر على تركيبة متوازنة في كل قضمة','لأن العلف المطحون غير قابل للتخزين إطلاقاً لأكثر من يوم واحد فقط'],
cor:2,exp:'قد يسمح العلف المطحون البسيط لبعض الطيور بانتقاء الجزيئات الأكبر أو الأكثر جاذبية وترك الباقي، ما يُخل بتوازن العليقة المُصمَّمة بعناية؛ يضمن الشكل المكعّب حصول كل طائر على نفس التركيبة المتوازنة في كل قضمة، بنفس منطق TMR في الأبقار.'},
{q:'ما الهدف الأساسي من "مرحلة التربية" (Pullet Rearing) عند الدجاج البياض قبل بداية الإنتاج الفعلي؟',
opts:['بناء إطار هيكلي وجسدي موحّد عبر القطيع لضمان بداية إنتاج متزامنة','تسمين الدجاجات بأقصى سرعة ممكنة تمهيداً لتسويقها كلحم بدلاً من البيض','تقليل عدد الدجاجات في القطيع تدريجياً استعداداً لموسم الإنتاج القادم','تعليم الدجاجات الصغيرة كيفية وضع البيض عملياً قبل بلوغها سن النضج'],
cor:0,exp:'هدف مرحلة التربية (نحو 18 أسبوعاً) بناء إطار هيكلي وجسدي موحّد عبر القطيع بأكمله، لا مجرد نمو سريع؛ فقطيع متجانس الوزن يبدأ الإنتاج في نفس التوقيت تقريباً بذروة إنتاجية متزامنة، بعكس القطيع غير المتجانس الذي يُنتج بتشتت زمني أوسع وكفاءة أقل.'},
{q:'لماذا يُفضَّل تقديم علف "البادئ" في شكل "مفتّت" (Crumble) بدلاً من مكعّبات كاملة الحجم للكتاكيت الصغيرة جداً؟',
opts:['لأن المفتّت أرخص تكلفة إنتاج بكثير من المكعّبات كاملة الحجم دائماً','لأن الكتاكيت الصغيرة جداً قد تجد الحبيبات الكاملة كبيرة الحجم صعبة التناول','لأن المفتّت يحتوي بروتيناً أعلى تلقائياً من المكعّبات كاملة الحجم نفسها','لا سبب حقيقي لهذا التفضيل؛ كلا الشكلين متطابقان تماماً في التأثير العملي'],
cor:1,exp:'قد تجد الكتاكيت الصغيرة جداً في الأيام الأولى من عمرها صعوبة في تناول حبيبات مكعّبة كاملة الحجم، لذا يُفضَّل غالباً إبقاء علف البادئ في شكل "مفتّت"، وهو مكعّب مُكسَّر لجزيئات أصغر تناسب حجم منقارها الصغير في هذه المرحلة المبكرة.'},
{q:'لماذا تبقى جزيئات الحجر الجيري الخشنة في القونصة فترة أطول من الجزيئات الناعمة، وما أهمية ذلك للدجاج البياض؟',
opts:['لا أهمية عملية حقيقية لحجم الجزيئات؛ النسبة المئوية الكلية هي العامل الوحيد المهم','تتحرر الجزيئات الخشنة تدريجياً طوال الليل، متزامنة مع تكلّس القشرة الليلي','الجزيئات الخشنة تُهضَم بسرعة أكبر من الناعمة، فتُغطي الاحتياج نهاراً فقط','الجزيئات الناعمة هي الأفضل دوماً لأنها تُمتَص فوراً دون أي تأخير زمني'],
cor:1,exp:'تبقى جزيئات الحجر الجيري الخشنة في القونصة لفترة أطول، فتتحرر تدريجياً طوال الليل بالتزامن مع تكلّس القشرة، بعكس الجزيئات الناعمة التي تُهضَم وتُمتَص بسرعة أكبر نهاراً ولا تُغطي الاحتياج الليلي بنفس الكفاءة، رغم تساوي النسبة المئوية الكلية أحياناً.'}
]},
fd10:{title:'اختبار المحاضرة العاشرة — إضافات الأعلاف الحديثة وتحسين الكفاءة الغذائية',questions:[
{q:'ما العامل التاريخي والتنظيمي الذي دفع أكثر من غيره لتطور صناعة إضافات الأعلاف الحديثة؟',
opts:['ارتفاع أسعار الحبوب عالمياً بشكل مفاجئ وحاد خلال العقد الماضي فقط','حظر محفزات النمو المضادة الحيوية في الاتحاد الأوروبي ودول أخرى تدريجياً','انخفاض الطلب العالمي على اللحوم والألبان بشكل عام خلال العقدين الأخيرين','توقف كل الأبحاث في مجال تغذية الحيوان التقليدية لعقود طويلة متتالية'],
cor:1,exp:'حظر الاتحاد الأوروبي محفزات النمو المضادة الحيوية اعتباراً من 2006، وتبعته دول أخرى بقيود مشابهة، ما دفع الصناعة للاستثمار المكثف في بدائل حقيقية كالإنزيمات والبروبيوتيك والأحماض العضوية تحقق نفس الفائدة الإنتاجية دون الاعتماد على المضادات الحيوية.'},
{q:'ما آلية عمل إنزيم الفيتاز تحديداً في علائق الدواجن والخنازير؟',
opts:['يقتل الكائنات الممرضة داخل الجهاز الهضمي مباشرة عبر آلية كيميائية مباشرة','يرفع درجة حرارة العليقة لتحسين حفظها وإطالة عمرها التخزيني الافتراضي','يُحرِّر الفوسفور المحبوس في الفايتات النباتي ليصبح متاحاً للامتصاص الفعلي','يزيد نسبة البروتين الكلية في العليقة دون أي تأثير يُذكر على المعادن'],
cor:2,exp:'يُحرِّر الفيتاز الفوسفور المرتبط بالفايتات في المواد النباتية، فيصبح متاحاً للامتصاص، ما يتيح خفض كمية الفوسفور غير العضوي (كثنائي فوسفات الكالسيوم) المُضاف يدوياً دون الإخلال باحتياج الحيوان الفعلي من هذا المعدن الأساسي.'},
{q:'مصنع أعلاف يخفض إضافة DCP من 8 إلى 3 كجم لكل طن بفضل الفيتاز (سعر DCP = 12 جنيه/كجم)، بتكلفة فيتاز 12 جنيه/طن. ما صافي التوفير لكل طن؟',
opts:['48 جنيه لكل طن، بعد خصم تكلفة الفيتاز من قيمة الفوسفات المُوفَّرة كلياً','60 جنيه لكل طن، بصرف النظر تماماً عن تكلفة الفيتاز المُضافة أصلاً','12 جنيه لكل طن فقط، وهو رقم يساوي تكلفة الفيتاز نفسها بالضبط','96 جنيه لكل طن تقريباً، وهو ضعف القيمة الفعلية لهذا السيناريو'],
cor:0,exp:'توفير DCP = (8-3) × 12 = 60 جنيه لكل طن (القيمة الإجمالية قبل خصم أي تكلفة). صافي التوفير = 60 - 12 (تكلفة الفيتاز) = 48 جنيه لكل طن، وهو الرقم الصحيح بعد احتساب تكلفة الإنزيم نفسه من إجمالي التوفير في ثنائي فوسفات الكالسيوم.'},
{q:'ما الفارق الجوهري بين البروبيوتيك والبريبايوتيك كإضافتين مختلفتين؟',
opts:['البريبايوتيك كائنات حية مفيدة، والبروبيوتيك مركّبات غذائية غير حية بطبيعتها تماماً','البروبيوتيك يخص المجترات حصراً فقط، والبريبايوتيك يخص الدواجن حصراً دون غيرها','لا فرق حقيقي بينهما؛ المصطلحان مترادفان تماماً في كل الاستخدامات العلمية الحديثة','البروبيوتيك كائنات حية تُضاف مباشرة، والبريبايوتيك غذاء للكائنات المفيدة الموجودة أصلاً'],
cor:3,exp:'البروبيوتيك كائنات دقيقة حية مفيدة تُضاف مباشرة للعليقة، بينما البريبايوتيك مركّبات غير حية تُستخدَم كغذاء مفضّل لتحفيز نمو الكائنات المفيدة الموجودة أصلاً في الجهاز الهضمي، دون إضافة أي كائنات جديدة إليه مباشرة.'},
{q:'ما الفرق في اتجاه الاستخدام بين الأحماض العضوية ومنظمات الكرش (Rumen Buffers)؟',
opts:['الأحماض العضوية تخفض الحموضة عند وحيدات المعدة، ومنظمات الكرش تُثبّت حموضة الكرش عند المجترات','كلاهما يخفض الحموضة بنفس الاتجاه تماماً في كل الأنواع الحيوانية دون استثناء','منظمات الكرش تخص الدواجن فقط حصراً، والأحماض العضوية تخص المجترات فقط حصراً دوماً','لا فرق حقيقي بينهما إطلاقاً؛ يمكن استخدام أي منهما بديلاً كاملاً عن الآخر دوماً'],
cor:0,exp:'تُضاف الأحماض العضوية عند وحيدات المعدة لخفض حموضة الجهاز الهضمي وكبح الكائنات الممرضة، بينما تُستخدَم منظمات الكرش كبيكربونات الصوديوم عند المجترات لتثبيت الحموضة ومنع انخفاضها الحاد عند العلائق عالية التركيز؛ اتجاهان مختلفان يخدمان هدفين مختلفين.'},
{q:'كيف يقارَن مركّب 3-NOP (Bovaer) بإضافات الأعشاب البحرية القائمة على البروموفورم من حيث النضج التجاري؟',
opts:['كلاهما ما زال في مراحل بحثية مبكرة جداً دون أي اعتماد تجاري حقيقي حتى الآن','3-NOP معتمد تجارياً في عشرات الدول، والأعشاب البحرية في مراحل تطور تجاري أحدث','الأعشاب البحرية معتمدة تجارياً في عشرات الدول، بينما 3-NOP ما زال بحثياً فقط','كلاهما معتمد تجارياً بنفس المستوى تماماً في كل دول العالم دون أي فارق يُذكر'],
cor:1,exp:'3-NOP معتمد تجارياً ومنظَّم بالفعل في عشرات الدول، بينما إضافات الأعشاب البحرية القائمة على البروموفورم، رغم نتائجها الميدانية الواعدة (تخفيض يتراوح تقريباً بين 30% وأكثر من 80% حسب الظروف)، ما زالت في مراحل تطور ونمو تجاري أحدث نسبياً مقارنة بالمركّبات الكيميائية المعتمدة.'},
{q:'لماذا تُضاف إنزيمات "السكريات غير النشوية" (NSP Enzymes) خصوصاً في علائق الدواجن القائمة على القمح أو الشعير؟',
opts:['لأن هذه السكريات تزيد لزوجة محتوى الأمعاء وتُعيق حركة العناصر الغذائية نحو الامتصاص','لأن القمح والشعير خاليان تماماً من أي طاقة أو بروتين دون هذه الإنزيمات المُضافة','لأن هذه الإنزيمات تحل محل الحاجة الكاملة لأي مصدر طاقة آخر في العليقة كلياً','لا سبب علمي حقيقي؛ إضافتها تقليدية صناعية فقط دون أي أساس فسيولوجي واضح'],
cor:0,exp:'تزيد السكريات غير النشوية الموجودة في القمح والشعير لزوجة محتوى الأمعاء، ما يُعيق حركة العناصر الغذائية نحو جدار الأمعاء لامتصاصها؛ تكسير هذه السكريات إنزيمياً بالزيلانيز والجلوكانيز يُحسّن سيولة المحتوى المعوي وكفاءة الامتصاص بشكل ملحوظ في هذه العلائق تحديداً.'},
{q:'وفق الإطار النقدي لتقييم أي إضافة علفية جديدة، ما الأساس الأصح للحكم على ادعاء تسويقي كـ"زيادة الإنتاج 20%"؟',
opts:['قبول الادعاء فوراً طالما صدر عن شركة مُصنِّعة معروفة وموثوقة في السوق','رفض الادعاء تلقائياً بصرف النظر عن أي دليل مُقدَّم من أي جهة كانت','البحث عن أدلة علمية مستقلة ومنشورة تتكرر في ظروف ميدانية حقيقية','الاعتماد فقط على عدد المزارع المجاورة التي تستخدم هذه الإضافة حالياً'],
cor:2,exp:'يحتاج أي ادعاء تسويقي أدلة علمية مستقلة ومنشورة، وقابلية تكرار في ظروف ميدانية حقيقية لا معملية مثالية فقط، وعائداً اقتصادياً يبرر التكلفة فعلياً، لا مجرد بيانات تسويقية داخلية من الشركة المُصنِّعة وحدها مهما بدت موثوقة ظاهرياً.'},
{q:'ما الفائدة البيئية المباشرة لاستخدام الفيتاز في علائق الدواجن التجارية على نطاق واسع؟',
opts:['زيادة استهلاك المياه في مزارع الدواجن بشكل ملحوظ ومقصود لأسباب تقنية','رفع درجة حرارة الحظائر المطلوبة لتربية الدواجن بشكل عام في كل الفصول','تقليل عدد الطيور التي يمكن تربيتها في نفس المساحة المتاحة للمزرعة','خفض كمية الفوسفور المطروحة في البيئة عبر فضلات الطائر نتيجة تحسين امتصاصه'],
cor:3,exp:'بتحرير الفيتاز للفوسفور المحبوس في الفايتات، تقل الحاجة لإضافة فوسفور غير عضوي زائد، وتزداد كفاءة امتصاص الفوسفور الكلي من العليقة؛ النتيجة كمية أقل من الفوسفور غير المُستفاد منه تخرج في الفضلات، وهو أمر بيئي مهم خصوصاً حول مزارع الدواجن الكثيفة.'},
{q:'لماذا لا تُعد الإضافات الحديثة بديلاً عن التصميم الغذائي السليم للعليقة الأساسية؟',
opts:['لأن الإضافات مكلفة جداً بحيث لا يستحق استخدامها في أي برنامج تغذية عملياً','لأن الإضافات تُحسّن كفاءة عليقة متوازنة أصلاً، ولا تُصلح عليقة سيئة التصميم من الأساس','لأن استخدام الإضافات ممنوع قانونياً في كل الدول المُصدِّرة للحوم والألبان','لأنها تحل محل احتياجات الطاقة والبروتين الأساسية بالكامل دون أي حاجة لتصميم عليقة'],
cor:1,exp:'الإضافات الحديثة أداة لتحسين كفاءة عليقة مُصمَّمة بشكل سليم أصلاً (تركيب صحيح، احتياجات مغطاة، توازن معادن وفيتامينات)، لا حلاً سحرياً يُصلح أخطاء جوهرية في تصميم العليقة الأساسية أو يعوّض نقصاً حقيقياً في الطاقة أو البروتين أو المعادن الأساسية.'}
]},
fd11:{title:'اختبار المحاضرة الحادية عشرة — إدارة الأعلاف داخل المزارع وتقليل الفاقد',questions:[
{q:'ما الفرق الجوهري بين الفاقد الفيزيائي والفاقد الغذائي في الأعلاف؟',
opts:['الفاقد الفيزيائي مرتبط بالدواجن فقط، والفاقد الغذائي مرتبط بالمجترات دون غيرها','كلاهما مترادفان تماماً ولا فرق عملي بينهما في أي حساب اقتصادي حقيقي','الفاقد الفيزيائي علف يغادر الدورة كلياً دون استهلاك، والفاقد الغذائي تراجع في القيمة دون فقدان الكمية','الفاقد الغذائي يخص التخزين فقط، والفاقد الفيزيائي يخص المعلفة فقط'],
cor:2,exp:'الفاقد الفيزيائي يعني أن كمية العلف نفسها تغادر الدورة — تطايرت، انسكبت، أكلها الفأر. أما الفاقد الغذائي فالعلف موجود كوزن لكن قيمته الغذائية تراجعت (تزنخ الدهون، تحلل الفيتامينات، السموم الفطرية)، وهو خفي لكنه يُفسّر أداء حيوانياً ضعيفاً رغم ثبات الكمية المُصرَّفة ظاهرياً.'},
{q:'ما أقصى نسبة رطوبة مسموح بها عموماً في الأعلاف المركزة لضمان تخزين آمن يمنع نمو الفطريات؟',
opts:['أقل من 6% فقط، وهو معيار لا يتحقق عملياً إلا في الأعلاف المجففة صناعياً','أقل من 12-14%، وهو النطاق الذي تستقر فيه الأعلاف المركزة وتقل فيه نشاط الفطريات','حتى 25% مقبولة للأعلاف طالما درجة الحرارة منخفضة خلال فترة التخزين','لا حد مُقيَّد للرطوبة طالما التهوية كافية في المخزن'],
cor:1,exp:'تنشط الفطريات بشكل ملحوظ فوق نسبة رطوبة 14% في الأعلاف المركزة، وبعض الأجناس تبدأ نشاطها من 12%. الحفاظ على رطوبة أقل من 12-14% هو المعيار التشغيلي الأساسي لإطالة العمر التخزيني ومنع نمو الفطريات المُنتِجة للسموم. هذا يتطلب أحياناً التجفيف المسبق أو إضافة حمض البروبيونيك حافظاً للرطوبة في الحبوب الطازجة.'},
{q:'ما مبدأ FIFO في تخزين الأعلاف وما الخطر من إهماله؟',
opts:['FIFO يعني طحن العلف قبل تخزينه — إهماله يُسبب تكتلات صعبة التوزيع','FIFO يعني تخزين الأعلاف في الثلاجة — إهماله يسبب ارتفاع درجة الحرارة','FIFO يعني أول ما يدخل أول ما يخرج — إهماله يجعل الدفعات القديمة تبقى في القاع متجاوزة الصلاحية','FIFO مصطلح خاص بتخزين الأدوية البيطرية وليس له صلة بالأعلاف أصلاً'],
cor:2,exp:'FIFO (First In, First Out) مبدأ بسيط وجوهري: الدفعة الأقدم تخرج أولاً. إهماله يعني تكديس الدفعات الجديدة فوق القديمة، ما يُبقي العلف القديم في القاع لأشهر يتراجع خلالها في جودته الغذائية أو يتعفن أو يُصبح بيئة مثالية للفطريات — وهو فاقد غذائي حقيقي رغم وجود العلف كوزن في المخزن.'},
{q:'ما تقدير منظمة الفاو (FAO) لنسبة العلف المخزّن الذي تُتلفه القوارض أو تُلوّثه في ظروف تخزين غير محمية؟',
opts:['أقل من 1% وهي نسبة هامشية لا تستحق أي اهتمام إداري يُذكر','نحو 15-20% من العلف يُؤكل أو يُتلف أو يُلوَّث بفضلات القوارض','أكثر من 50% في المناطق الاستوائية فقط دون غيرها من مناطق العالم','القوارض لا تُلوّث العلف بل تأكله فقط فالتلوث من مصادر أخرى دائماً'],
cor:1,exp:'تُشير تقديرات منظمة الفاو إلى أن الفئران والجرذان قادرة على إتلاف 15-20% من المخزون في ظروف غير محمية. اللافت أن ما تُلوّثه بالبول والبراز غالباً أكبر مما تأكله مباشرة — لأن الجرذ الواحد يُخلّف 30-50 ألف حبة براز سنوياً ويُلوّث مناطق أوسع بكثير مما يستهلكه.'},
{q:'ما النسبة المثالية لبقايا العلف في معلفة التغذية الحرة (Ad Libitum) عند موعد الوجبة التالية؟',
opts:['الصفر — أي بقايا دليل على الإسراف وإهدار المال في كل المواضع','2-5% من الكمية المُقدَّمة كدليل على عدم تقييد الحيوانات عن التغذية','20-30% لضمان أن الحيوانات لم تشعر بأي نقص في العلف طوال الوقت','لا توجد نسبة مثالية — أي كمية متبقية مقبولة في جميع الأحوال'],
cor:1,exp:'في نظام التغذية الحرة، يجب أن يبقى 2-5% من العلف عند موعد الوجبة التالية كدليل على أن الحيوانات لم تكن مقيّدة عن الأكل في أي وقت. أقل من ذلك يعني احتمال وجود فترات نقص؛ أكثر من ذلك يعني إسرافاً حقيقياً في الكمية المُقدَّمة. هذه القاعدة هي أداة تشغيلية مُدمجة لمنع الفاقد دون الإضرار بالأداء.'},
{q:'لماذا يُعدّ ارتفاع معدل التحويل الغذائي (FCR) مع ثبات الحالة الصحية الظاهرية للحيوان مؤشراً على فاقد مخفي؟',
opts:['FCR لا علاقة له بالفاقد في المعلفة — ارتفاعه مرتبط فقط بأمراض الجهاز الهضمي','ارتفاع FCR يعني أن الحيوان ينتج أكثر بكفاءة عالية وهو مؤشر إيجابي دوماً','إذا ارتفع FCR دون مرض ظاهر فهو يعني أن العلف المُستهلَك الفعلي أعلى من الإنتاج أو أن الكمية الواصلة للحيوان أقل مما يُسجَّل، فكلاهما علامة فاقد','FCR ثابت دوماً لكل نوع حيواني بصرف النظر عن أي إدارة أو ظروف'],
cor:2,exp:'FCR هو نسبة العلف المُستهلَك إلى الإنتاج. ارتفاعه مع ثبات الحالة الصحية يعني إما أن العلف المُسجَّل كمصروف لم يصل بالكامل للحيوان (فاقد فيزيائي مخفي: سقوط من المعلفة، قوارض، خطأ في الوزن)، أو أن قيمته الغذائية تراجعت رغم وصول الكمية (فاقد غذائي: سموم فطرية، تزنخ). كلا الاحتمالين يستدعي تحقيقاً ميدانياً وليس تغييراً في التركيبة.'},
{q:'ما الجانب الأخطر في تخزين السيلاج من حيث الفاقد وكيف يُعالَج عملياً؟',
opts:['التوازن الحمضي لا يمكن الحفاظ عليه إطلاقاً بعد أول أسبوع من التخزين','الطبقة السطحية المعرّضة للهواء تُعدّ مصدر الفاقد الأكبر — ويُعالَج بضغط كافٍ وتغطية مُحكمة وإغلاق الثقوب فوراً','السيلاج يتحسّن كلما طالت مدة تخزينه دون أي حد زمني أقصى','الفاقد في السيلاج يعتمد كلياً على نوع المحصول ولا تأثير للتغطية أو الضغط'],
cor:1,exp:'الطبقة السطحية للسيلاج المعرّضة للهواء تتعرض لعملية إعادة تخمّر هوائي (Aerobic Spoilage) تُفسد البروتين وتُنتج حرارة وكحولات؛ وقد تصل خسائرها إلى 15-20% من هذه الطبقة. الحل: ضغط محكم عند التعبئة لطرد الهواء، تغطية بلاستيكية بدون ثقوب، وإغلاق أي ثقب فور اكتشافه بالشريط اللاصق. عند الإطعام: مقطع عمودي نظيف يومياً ولا تهشيش للسطح.'},
{q:'ما الإجراء الأهم لمنع القوارض من اختراق مخزن الأعلاف البشري والميداني؟',
opts:['رش المبيدات الحشرية داخل المخزن أسبوعياً بصرف النظر عن وجود قوارض أم لا','سد كل فتحة بقطر أكبر من 2.5 سم في الجدران والأسقف والأبواب لأن الجرذ يدخل من هذا القطر فما فوقه','رفع الأكياس فوق مستوى الأرض مباشرة كاف تماماً دون أي إجراءات أخرى','فتح المخزن طوال اليوم لدخول الهواء هو أفضل رادع للقوارض عملياً'],
cor:1,exp:'الجرذ النرويجي (Rattus norvegicus) الشائع قادر على الدخول من فتحة بقطر 2.5 سم فما فوقه، والفأر المنزلي من فتحة 1 سم. سد كل الثقوب والشقوق في الجدران والأرضية والأسقف والأبواب هو حجر الأساس في مكافحة القوارض — أرخص وأفعل من الطُّعم السُّمّي المستمر الذي يعالج أعراض المشكلة لا جذرها.'},
{q:'مزرعة تستهلك 1,000 كجم علف يومياً وتُسجّل فاقداً 10%. ما التكلفة الشهرية للفاقد بسعر 5,000 جنيه للطن؟',
opts:['500 جنيه شهرياً فقط — وهي قيمة لا تستحق تحسينات استثمارية','1,500 جنيه شهرياً تقريباً، وهي قيمة محدودة نسبياً','15,000 جنيه شهرياً — وهو رقم يبرر الاستثمار الجاد في تقليل الفاقد','3,000 جنيه شهرياً فقط، بغض النظر عن حجم الاستهلاك'],
cor:2,exp:'الفاقد اليومي = 1000 × 10% = 100 كجم. القيمة اليومية = 100 × 5 = 500 جنيه. الفاقد الشهري = 500 × 30 = 15,000 جنيه. هذا الرقم يُبرّر بوضوح استثمارات في تحسين التخزين أو المعالف أو مكافحة القوارض التي قد تكلف جزءاً صغيراً من هذا المبلغ ولها عائد مباشر خلال أسابيع.'},
{q:'لماذا يُعدّ الجرد الشهري للأعلاف أداةً تشغيليةً فعّالة وليس مجرد إجراء محاسبي بيروقراطي؟',
opts:['لأن القانون يُلزم كل مزرعة بجرد شهري موثّق بغض النظر عن حجمها أو نوعها','لأنه يكشف الفجوة بين ما اشتُري وما اُستُهلك فعلاً مُضافاً إليه الرصيد — وأي فارق غير مبرر هو فاقد مخفي يستحق تحقيقاً','الجرد الشهري إجراء ضروري فقط في المزارع الكبيرة التي تتجاوز 500 رأس','لا فائدة من الجرد إذا كانت المزرعة تستهلك أعلافاً مصنّعة جاهزة من مصنع'],
cor:1,exp:'الجرد الشهري معادلة بسيطة: (ما اشتريته) - (الرصيد المتبقي) = ما استُهلك فعلاً. إذا كان هذا الرقم أكبر مما سجّله العمال يومياً كمصروف للحيوانات، فالفرق هو فاقد غير محسوب — قوارض، تلف، خطأ في الوزن، أو حتى سرقة. هذه الأداة البسيطة تُجعل الفاقد مرئياً وتخلق حافزاً حقيقياً للتحسين.'}
]},
fd12:{title:'اختبار المحاضرة الثانية عشرة — تطبيقات عملية ودراسات حالة في برامج التغذية الحيوانية',questions:[
{q:'أبقار هولشتاين عالية الإنتاج تُسجَّل عليها خسارة حادة في وضع الجسم (BCS) من 3.0 إلى 1.75 خلال 40 يوماً بعد الولادة، مع تراجع الإنتاج من الذروة المتوقعة. ما الاسم الفني للحالة الأيضية التي تصفها هذه الأرقام؟',
opts:['فرط التسمين (Over-conditioning)، وهو أن البقرة استهلكت طاقة أكثر مما يجب أثناء الجفاف','توازن الطاقة السلبي المفرط (Excessive Negative Energy Balance) الذي يتجاوز قدرة البقرة على التعويض من الجسم','الحماض الكرشي الحاد (Acute Rumen Acidosis) الناتج عن زيادة النشا في العليقة فجأة','نقص كالسيوم الدم (Hypocalcemia) المرتبط بتكلّس الحليب الزائد عند بداية الإنتاج'],
cor:1,exp:'توازن الطاقة السلبي (NEB) طبيعي في أسابيع ما بعد الولادة — البقرة العالية الإنتاج لا تستطيع استهلاك طاقة تكفي ذروتها من اليوم الأول. لكن إذا تجاوز هذا النقص قدرة الجسم على التعويض (ظهر في تراجع BCS من 3.0 إلى أقل من 2.0 بسرعة شديدة) فنحن أمام NEB مفرط يُقلّص الذروة الإنتاجية ويضر بالخصوبة — والحل تعديل كثافة الطاقة في العليقة قبل تفاقمه.'},
{q:'في إطار التشخيص الخماسي المنهجي للمشكلة التغذوية، لماذا يُنصح بتغيير عامل واحد في كل مرة عند التدخل؟',
opts:['لأن تغيير عدة عوامل مرة واحدة ممنوع قانونياً في أغلب الدول المُنتِجة للمنتجات الحيوانية','لأن الحيوان يستجيب للتغييرات المتعددة بردود فعل متعاكسة ومتضادة تجعل النتيجة صفراً','لأن التغيير الواحد يُوضّح سبباً وأثراً بوضوح، فتعرف ما الذي أحدث الفرق الفعلي إذا تحسّنت النتيجة','لأن الجهاز الهضمي للحيوان يتعامل مع المواد الغذائية واحدة واحدة ولا يمكنه معالجة أكثر من تعديل في يوم'],
cor:2,exp:'أهمية التغيير الواحد في كل مرة في التشخيص المنهجي: إذا نجح، تعرف بالضبط ما الذي حل المشكلة. إذا أجريت خمسة تعديلات متزامنة وتحسّن الوضع، ستظل تجهل أيّها كان الفعّال، وإذا لم يتحسّن لن تعرف أيّها المسؤول. استثناء وحيد: حالات الطوارئ التي تستوجب تدخلاً فورياً على أكثر من مستوى لمنع خسارة اقتصادية كبيرة.'},
{q:'قلم تسمين 60 رأساً: 40 رأساً وزنها 310-325 كجم، و20 رأساً وزنها 230-245 كجم، بعد 55 يوماً من نفس الظروف والعليقة. ما أرجح تفسير لهذا التباين الحاد داخل القلم الواحد؟',
opts:['الـ20 رأس المتخلفة أكلت كميات مساوية لكن جهازها الهضمي أقل كفاءة وراثياً بشكل دائم','طاقة العليقة غير كافية للقطيع كله — جميع الرؤوس متأخرة لكن البعض أكثر وضوحاً','ازدحام المعلفة يُقيّد وصول المراتب الدنيا من القطيع إلى كميتها الكافية يومياً','العليقة تحتوي سموماً فطرية تُصيب فقط الحيوانات الصغيرة دون الكبيرة منها'],
cor:2,exp:'وجود مجموعتين متمايزتين بوضوح داخل نفس القلم مع نفس العليقة والظروف هو النمط الكلاسيكي لمشكلة وصول لا مشكلة تركيبة. الحيوانات المراتب الاجتماعية العليا تأكل أولاً وأكثر وتُزيح الأضعف. مساحة معلفة 30-40 سم/رأس ضرورة لا ترف. الحل: فرز المتخلفين لقلم منفصل + زيادة مساحة المعلفة في الدفعات القادمة.'},
{q:'عجلة في الأسبوع الثاني من التحوّل للعليقة الكاملة في قلم التسمين تُبدي: خمولاً، تقليل استهلاك العلف، وبراز رخواً. ما الأرجح سبباً وما الإجراء الفوري المناسب؟',
opts:['بداية نزلة برد بكتيرية حادة — العلاج الفوري بمضاد حيوي واسع الطيف فوراً','حماض كرشي مزمن تحت الإكلينيكي ناتج عن انتقال سريع للعليقة المركزة — خفض المركز مؤقتاً وتدريج أبطأ','نقص ملح الطعام في العليقة فقط — إضافة 30 جرام ملح للرأس يومياً يحل المشكلة فوراً','الحيوان يرفض العليقة الجديدة بسبب الروائح — استبدال مصدر السيلاج هو الحل الوحيد'],
cor:1,exp:'هذه الأعراض الثلاثة معاً (خمول، انخفاض شهية، براز رخو) في الأسبوع الثاني من الانتقال للعليقة الكاملة هي صورة نصية للحماض الكرشي تحت الإكلينيكي (Sub-Acute Rumen Acidosis - SARA). الرقم الهيدروجيني للكرش ينخفض دون 5.8 بشكل متقطع فيسبب هذه الأعراض غير الواضحة. الإجراء: تراجع مؤقت لمستوى المركز + زيادة النشادر (بيكربونات) + تدريج أبطأ في المرحلة التالية.'},
{q:'نعاج في الأسبوع السادس من الحمل (من نعجتين) تُعاني من التعكز وتورم المفاصل في 15% من القطيع. تحليل العلف يُشير إلى نقص واضح في فيتامين E والسيلينيوم. ما المتلازمة المحتملة وكيف تتداخل المحاضرات لشرحها؟',
opts:['التسمم الحملي (Pregnancy Toxemia) الناتج عن نقص الطاقة في الثلث الأخير من الحمل','متلازمة العضلات البيضاء (White Muscle Disease) الناتجة عن نقص السيلينيوم وفيتامين E — ترتبط باحتياجات العناصر الصغرى (المحاضرة 3) ونقصها في الأعلاف (المحاضرة 5) في مرحلة الحمل الحرجة (المحاضرة 8)','نقص الكالسيوم التوليدي (Milk Fever) خاص بالأبقار الحلاب ولا يظهر في الأغنام الحوامل','حالة ميكروبية بيطرية بحتة لا علاقة لها بالتغذية ولا بأي محاضرة من هذا الكورس'],
cor:1,exp:'متلازمة العضلات البيضاء من أمراض العناصر الصغرى الكلاسيكية في أغنام مناطق التربة الفقيرة بالسيلينيوم. تجمع ثلاث محاضرات: المحاضرة 3 (احتياجات العناصر الصغرى وأعراض نقصها)، المحاضرة 5 (تحليل الأعلاف والكشف المبكر عن النقص)، والمحاضرة 8 (برامج تغذية الأغنام في الحمل حيث تزيد الحساسية). الوقاية: حقن بروتينات السيلينيوم قبل 30 يوماً من الولادة وتدعيم العليقة.'},
{q:'مزرعة دجاج لاحم تشكو من FCR 2.15 (المعيار 1.88). تحليل العلف سليم وصحة القطيع طيبة. تُجري جرداً يومياً وتجد أن الكمية المصروفة تتجاوز الاستهلاك الحيواني المُقدَّر بنسبة 8%. ما الاستنتاج الصحيح؟',
opts:['خطأ في حساب الاستهلاك الحيواني المُقدَّر — الرقم التقديري ليس دقيقاً','يوجد فاقد فيزيائي ميداني يتجاوز الطيور — تطاير، سقوط من المعلفة، أو قوارض تأكل من نفس المعلفة','FCR الحالي (2.15) في حدود الطبيعي ولا داعي للقلق أصلاً','المشكلة في حساب FCR نفسه — الصيغة الصحيحة تُعطي نتيجة مختلفة تماماً'],
cor:1,exp:'8% فجوة بين المصروف الموثَّق والمُستهلَك الحيواني المُقدَّر رقم حقيقي وكبير. مصادره المحتملة: تطاير عند الخلط أو ملء المعلفة (المحاضرة 11)، سقوط عبر فتحات المعلفة، قوارض تتغذى على العلف في الليل، أو خطأ في الوزن عند الصرف. الإجراء: مراقبة ليلية للمعلفة، فحص جميع نقاط التسريب، قياس الفاقد الفعلي عند الملء. إصلاح الفاقد الميداني يُعيد FCR للمعيار دون أي تغيير في التركيبة.'},
{q:'خبير تغذية يزور مزرعة أغنام ويجد: BCS = 2.0 قبل التزاوج بأسبوعين فقط. لم يبدأ برنامج Flushing بعد. ماذا يوصي؟',
opts:['تأجيل التزاوج أسبوعاً فقط لأن الـ Flushing ليس ضرورياً عند BCS 2.0 وهو مقبول','بدء Flushing فوراً بكمية مضاعفة (800 جرام/نعجة/يوم) للتعويض السريع عن التأخير','بدء Flushing الفوري بكمية معتدلة (400 جرام مركزة/نعجة/يوم) مع الإسراع في البدء وقبول BCS أدنى من المثالي مع مراقبة نسبة الحمل بعناية','الإلغاء الكامل لهذا الموسم لأن BCS 2.0 يجعل الحمل مستحيلاً بيولوجياً'],
cor:2,exp:'BCS 2.0 منخفض لكن ليس مستعصياً. الوصول لـ BCS 3.0 المثالي في أسبوعين فقط صعب (يحتاج عادة 3-4 أسابيع)، لكن الـ Flushing الفوري أفضل من لا شيء — حتى رفع BCS من 2.0 إلى 2.5 يُحسّن معدل التبويض وبالتالي نسبة الحمل. الكمية المعتدلة (400 جرام/يوم) آمنة ولا تُسبب السمنة المفرطة التي تضر بالتبويض هي الأخرى. المراقبة بعد التزاوج أساسية لتقييم النتيجة الفعلية.'},
{q:'مزرعة تستهلك 2 طن علف يومياً للدواجن. بعد تحسين نظام المعالف وسد ثقوب المخزن وتطبيق مكافحة القوارض، تراجع الفاقد من 12% إلى 4.5%. ما صافي التوفير الشهري بسعر 6,000 جنيه للطن؟',
opts:['16,200 جنيه شهرياً باحتساب تكلفة الفاقد الجديد 4.5% فقط بدلاً من الفارق بين القديم والجديد','27,000 جنيه شهرياً وهو صافي التوفير الصحيح: 150 كجم/يوم × 6 جنيه × 30 يوماً','43,200 جنيه شهرياً باحتساب تكلفة الفاقد القديم 12% كاملاً بدلاً من الفرق','54,000 جنيه شهرياً بضرب التوفير اليومي في سعر الطن (6,000) بدلاً من سعر الكيلوجرام (6)'],
cor:1,exp:'الفاقد القديم = 2000 × 12% = 240 كجم/يوم. الفاقد الجديد = 2000 × 4.5% = 90 كجم/يوم. التوفير اليومي = 150 كجم. القيمة اليومية = 150 × 6 = 900 جنيه. التوفير الشهري = 900 × 30 = 27,000 جنيه. الفاقد القديم 240 كجم/يوم × 6 = 1,440 جنيه/يوم؛ الجديد 90 كجم/يوم × 6 = 540 جنيه/يوم؛ الفرق 900 جنيه/يوم × 30 = 27,000 جنيه/شهر. الحساب الدقيق: الفاقد القديم 240 كجم × 6 ج = 1,440 ج/يوم؛ الفاقد الجديد 90 كجم × 6 ج = 540 ج/يوم؛ التوفير = 900 ج/يوم × 30 = 27,000 ج/شهر.'},
{q:'أي من هذه المجموعات يصف التسلسل الصحيح لإطار التشخيص الخماسي للمشكلة التغذوية؟',
opts:['صمّم عليقة جديدة → طبّق التعديل → لاحظ الأعراض → وثّق الأرقام → قارن بالمعيار','لاحظ ووثّق → اجمع الأرقام → قارن بالمعيار → ضيِّق الاحتمالات → تدخّل وراقب','ضيِّق الاحتمالات → تدخّل → لاحظ ووثّق → اجمع الأرقام → قارن بالمعيار','اجمع الأرقام → صمّم عليقة → تدخّل → قارن بالمعيار → لاحظ الأعراض لاحقاً'],
cor:1,exp:'إطار التشخيص الخماسي المنهجي: (1) لاحظ ووثّق الأعراض والتغييرات التي سبقتها بدقة. (2) اجمع الأرقام (FCR، إنتاج، BCS، تحليل علف). (3) قارن بالمعيار لتُحدد حجم الانحراف. (4) ضيِّق الاحتمالات بين تصميم العليقة والهضم والإدارة الميدانية. (5) تدخّل بتغيير واحد وراقب النتيجة. أي تغيير في هذا الترتيب يُضعف دقة التشخيص ويُطوّل وقت الوصول للحل الصحيح.'},
{q:'أيّ من المحاضرات الآتية يُعدّ المرجع الأول عند الشك في أن مشكلة الإنتاج ناتجة عن فقد غذائي خفي لا نقص في تركيبة العليقة؟',
opts:['المحاضرة الثانية — مكونات الأعلاف والقيمة الغذائية للمواد العلفية','المحاضرة السادسة — تصميم علائق الأبقار والجاموس الحلاب','المحاضرة الحادية عشرة — إدارة الأعلاف داخل المزارع وتقليل الفاقد','المحاضرة الرابعة — هضم وامتصاص المغذيات في المجترة وغير المجترة'],
cor:2,exp:'المحاضرة 11 هي المرجع المباشر لكل ما يخص الفاقد الميداني — الفيزيائي (تطاير، سقوط، قوارض) والغذائي (رطوبة، عفن، تزنخ) — وكيف يرفع هذا الفاقد FCR دون أن تكون التركيبة الغذائية هي المشكلة. هذا السؤال يمثّل بالضبط نوع التفكير الذي تُدرّبه دراسة الحالة الثانية في هذه المحاضرة (مزرعة الدواجن).'}
]}
};
var FEED_FINAL_EXAM={title:'الاختبار النهائي — إدارة الأعلاف وبرامج التغذية في الإنتاج الحيواني',passScore:70,questions:[
{q:'ما التعريف الأشمل لمصطلح "إدارة الأعلاف" في سياق الإنتاج الحيواني الحديث؟',
opts:['اختيار أرخص مصدر علف متاح في السوق المحلي شهرياً دون النظر لأي معيار آخر مهم','عملية تخزين الأعلاف داخل صوامع مخصصة فقط دون أي تدخل حقيقي في تركيبها العلمي','تسجيل إداري بسيط لكميات الأعلاف الداخلة والخارجة من مخزن المزرعة كل أسبوع','منظومة متكاملة تشمل تقييم المواد العلفية وتصميم العليقة والتخزين ومتابعة الفاقد والتكلفة'],
cor:3,exp:'إدارة الأعلاف منظومة متكاملة تبدأ بتقييم جودة المواد العلفية، وتمر بتصميم العليقة المناسبة لكل فئة إنتاجية، وتشمل التخزين السليم والخلط والتوزيع، وتنتهي بالمتابعة المستمرة لضبط التكلفة وتقليل الفاقد؛ وليست مجرد قرار شرائي أو إجراء تخزيني منعزل.'},
{q:'لماذا يُحسب محتوى الأعلاف والاحتياجات الغذائية أساساً على "المادة الجافة" بدلاً من الوزن الطازج؟',
opts:['لأن نسبة الماء المتفاوتة بين الأعلاف تجعل الوزن الطازج مقياساً غير عادل للمقارنة بينها','لأن الوزن الطازج للعلف غير قابل للقياس بأي ميزان متاح داخل المزارع العادية أصلاً','لأن تحليل المادة الجافة أرخص تكلفة من التحليل الكامل في كل المختبرات المتخصصة','لأن وجود الماء داخل تركيب العلف يُعد ضاراً بصحة الحيوان مهما كانت نسبته المئوية'],
cor:0,exp:'تتفاوت نسبة الماء بين الأعلاف بشدة، فقد تتجاوز 80% في بعض الأعلاف الخضراء بينما تقل عن 12% في الحبوب الجافة، ما يجعل مقارنة الأوزان الطازجة مضللة. لذلك تُحسب كل الاحتياجات والعلائق على أساس المادة الجافة بعد استبعاد الماء، لضمان مقارنة عادلة ودقيقة بين مصادر العلف المختلفة.'},
{q:'ما الفارق الجوهري بين "احتياجات الصيانة" و"احتياجات الإنتاج" لدى الحيوان؟',
opts:['كلا المصطلحين مترادف تماماً ولا يوجد فرق عملي حقيقي بينهما في أي حساب غذائي دقيق','احتياجات الصيانة تخص فقط الحيوانات الصغيرة، واحتياجات الإنتاج تخص فقط الحيوانات البالغة','الصيانة حد أدنى لوظائف الجسم الأساسية دون إنتاج، والإنتاج احتياجات إضافية للنمو أو الحليب أو البيض','احتياجات الإنتاج ثابتة دوماً بصرف النظر عن مستوى الأداء أو المرحلة الفسيولوجية للحيوان'],
cor:2,exp:'احتياجات الصيانة هي الحد الأدنى من الطاقة والمغذيات اللازم للحفاظ على وظائف الجسم الأساسية كالتنفس ودرجة الحرارة دون أي إنتاج فعلي، بينما احتياجات الإنتاج هي الكمية الإضافية التي تُضاف فوق الصيانة لدعم النمو أو إدرار الحليب أو إنتاج البيض أو الحمل، وتتغير بتغير مستوى الأداء الإنتاجي.'},
{q:'مزرعة ألبان تسجّل أن تكلفة العلف تمثل نحو نصف تكلفتها الكلية تقريباً. أين تقع هذه النسبة مقارنةً بقطاعات الإنتاج الحيواني الأخرى عموماً؟',
opts:['هي الأعلى بين كل قطاعات الإنتاج الحيواني دون استثناء ولا يتجاوزها أي قطاع آخر إطلاقاً','ضمن نطاق معقول ومتوقع لقطاع الألبان، وإن كانت نسبة الدجاج اللاحم غالباً أعلى منها قليلاً','نسبة نادرة الحدوث عملياً ولا تُسجَّل في أي مزرعة ألبان حقيقية على أرض الواقع','نسبة منخفضة جداً مقارنةً بمعظم قطاعات الإنتاج الحيواني التجاري الأخرى كافة'],
cor:1,exp:'تمثل الأعلاف في إنتاج الألبان عادة نحو 40-60% من التكلفة الكلية، وهي نسبة معقولة ومتوقعة لهذا القطاع، لكنها غالباً أقل من نظيرتها في الدجاج اللاحم التي قد تصل إلى 65-70% بسبب سرعة النمو ومعدل التحويل الغذائي المرتفع نسبياً في الدواجن مقارنة بالأبقار الحلاب.'},
{q:'ما الذي يميز التركيب الهضمي للحيوانات المجترة تحديداً عن الحيوانات وحيدة المعدة؟',
opts:['معدة واحدة بسيطة أصغر حجماً من معدة الحيوانات وحيدة المعدة في كل الحالات المدروسة','غياب شبه تام لأي كائنات دقيقة مساعدة فعلياً في عملية الهضم داخل الجهاز الهضمي بأكمله','قناة هضمية أقصر بكثير من قناة الحيوانات وحيدة المعدة في معظم الحالات المدروسة عملياً','معدة من أربع حجرات تتيح تخميراً ميكروبياً واسعاً للاستفادة الجيدة من الألياف الخشنة'],
cor:3,exp:'تتميز المجترات كالأبقار والجاموس والأغنام والماعز بمعدة من أربع حجرات (الكرش والشبكية والورقية والإنفحة) تتيح تخميراً ميكروبياً هائلاً يُمكّنها من هضم الألياف الخشنة بكفاءة عالية، بعكس الحيوانات وحيدة المعدة كالدواجن التي تحتاج علائق أعلى تركيزاً وأقل ألياف بسبب بساطة تركيبها الهضمي.'},
{q:'ما المقصود بـ"الكفاءة التحويلية للعلف" (FCR) وكيف تُفسَّر قيمتها العددية عملياً؟',
opts:['نسبة الرطوبة المتبقية في العلف بعد عملية التجفيف الكامل داخل مصنع الأعلاف الحديث','السعر السوقي لكيلوجرام واحد من العلف المُباع للمربين في أي وقت من السنة','كمية العلف اللازمة لإنتاج وحدة واحدة من المنتج، وانخفاضها يعني كفاءة تحويل أعلى','متوسط عدد الوجبات اليومية التي يتناولها الحيوان الواحد داخل المزرعة التجارية'],
cor:2,exp:'الكفاءة التحويلية للعلف (FCR) تقيس كمية العلف اللازمة لإنتاج وحدة واحدة من المنتج كوزن حي مكتسب أو حليب أو بيض. انخفاض هذا الرقم يدل على كفاءة أعلى، إذ يعني حاجة أقل من العلف لإنتاج الكمية نفسها من المنتج، وهو من أهم المؤشرات الاقتصادية التي تُتابعها أي منشأة إنتاج حيواني باستمرار.'},
{q:'ما الذي طرأ على تسمية المرجع الأمريكي لجداول الاحتياجات الغذائية للحيوان (NRC سابقاً) منذ اندماجه المؤسسي في 2015؟',
opts:['أصبحت إصداراته الجديدة تُنشر باسم NASEM بعد اندماجه ضمن الأكاديميات الوطنية للعلوم والهندسة','اختفى المرجع كلياً ولم يعد له أي وجود أو أي تحديثات لاحقة بعد ذلك التاريخ إطلاقاً','اقتصرت تحديثاته بعدها على تغطية الدواجن فقط دون أي نوع حيواني آخر مهما كانت أهميته','تحوّل المرجع بالكامل إلى جهة أوروبية بديلة بدلاً من الجهة الأمريكية الأصلية المعروفة'],
cor:0,exp:'اندمج المجلس القومي للبحوث الأمريكي (NRC) عام 2015 ضمن الأكاديميات الوطنية للعلوم والهندسة والطب (NASEM)، فأصبحت كل الإصدارات الجديدة كطبعة الألبان 2021 وتحديث اللحوم 2024 والطبعة العاشرة للدواجن تُنشر باسم NASEM، وإن ظل كثيرون في الحقل يستخدمون اسم NRC القديم بالتبادل حتى اليوم.'},
{q:'مثبطات الميثان الحديثة مثل المركّبات القائمة على 3-NOP تعمل بآلية محددة داخل جسم المجترات. ما هذه الآلية؟',
opts:['تعمل على قتل كل الكائنات الدقيقة داخل الكرش دفعة واحدة دون أي انتقائية بينها','تزيد من درجة حرارة الكرش بشكل مباشر لتسريع عملية الهضم الكلية لكل الألياف','تحل محل الماء الذي يشربه الحيوان يومياً كبديل غذائي متكامل ودائم له','تُثبّط إنزيماً أساسياً في مسار إنتاج الميثان لدى الكائنات الدقيقة داخل الكرش تحديداً'],
cor:3,exp:'تعمل هذه الفئة من الإضافات، مثل مركّب 3-NOP المعروف تجارياً باسم Bovaer، على تثبيط إنزيم محدد (methyl-coenzyme M reductase) ضروري لإنتاج غاز الميثان لدى الكائنات الدقيقة المولّدة للميثان داخل الكرش، فتخفض الانبعاثات نحو 30% في الأبقار الحلاب دون التأثير على كمية الحليب أو صحة الحيوان.'},
{q:'ما الخطأ الشائع الذي يقع فيه كثير من المربين المبتدئين بخصوص العليقة الواحدة داخل القطيع؟',
opts:['الحرص المبالغ فيه على تصميم عليقة مختلفة تماماً لكل حيوان منفرد داخل القطيع','افتراض أن كل حيوانات القطيع تحتاج العليقة نفسها بصرف النظر عن عمرها ومرحلتها الإنتاجية','تجاهل نوع العلف كلياً والاعتماد فقط على الكمية بصرف النظر عن أي معيار آخر','رفض استخدام أي إضافات علفية حديثة في أي عليقة مهما كانت مبرراتها العلمية القوية'],
cor:1,exp:'من أشيع الأخطاء افتراض أن عليقة واحدة تناسب كل حيوانات القطيع بصرف النظر عن الفروق بينها. عملياً تحتاج البقرة عالية الإدرار كمية وتركيزاً مختلفين تماماً عمّا تحتاجه بقرة جافة أو عجلة نامية، لأن احتياجات الصيانة شبه ثابتة بينما تتغير احتياجات الإنتاج بتغير المرحلة الفسيولوجية والأداء.'},
{q:'وفق مسح Alltech العالمي لعام 2026، ما الترتيب التقريبي لأكبر ثلاث دول منتجة للأعلاف عالمياً من حيث الحصة الإجمالية؟',
opts:['الصين والولايات المتحدة والبرازيل، وتمثل معاً نحو نصف الإنتاج العالمي تقريباً','الهند وروسيا وأستراليا، وتمثل معاً أقل من عُشر الإنتاج العالمي المُسجَّل فقط','مصر والسعودية والإمارات، وتمثل معاً الحصة الأكبر من الإنتاج العالمي المُسجَّل','ألمانيا وفرنسا وإسبانيا، وتمثل معاً غالبية الإنتاج العالمي المُسجَّل رسمياً'],
cor:0,exp:'أظهر المسح أن الصين والولايات المتحدة والبرازيل كانت أكبر ثلاث دول منتجة للأعلاف عالمياً في 2025، بحصة مجمعة بلغت نحو 47.7% من إجمالي الإنتاج العالمي البالغ نحو 1.44 مليار طن متري، فيما استحوذت أكبر عشر دول مجتمعة على نحو 65.2% من هذا الإنتاج.'},
{q:'ما الفرق الجوهري بين مؤشر NDF ومؤشر ADF في تحليل الأعلاف الخشنة من حيث المكونات التي يقيسها كل منهما؟',
opts:['NDF يقيس نسبة البروتين الخام الكلية في العلف الخشن وADF يقيس نسبة الدهون الكلية فيه دون غيرهما','كلا المؤشرَين يقيسان الألياف الكلية في العلف الخشن بطريقتين كيميائيتين مختلفتين دون فرق في الناتج','NDF يُعبّر عن الكربوهيدرات الذائبة غير الهيكلية وADF يُعبّر عن الطاقة الصافية للإنتاج فيه','NDF يشمل الهيميسيلولوز والسيليلوز واللجنين معاً وADF يشمل السيليلوز واللجنين فقط دون الهيميسيلولوز'],
cor:3,exp:'NDF (Neutral Detergent Fiber) يشمل كل ألياف جدار الخلية: الهيميسيلولوز + السيليلوز + اللجنين. ارتفاعه يُقيّد كمية العلف المُستهلَكة لأنه يملأ الكرش. أما ADF (Acid Detergent Fiber) فيشمل السيليلوز واللجنين فقط — وهو مؤشر الهضمية: كلما ارتفع ADF انخفضت الطاقة المُستخلَصة من العلف. المعادلات المستخدمة في تقدير NEL للأبقار تعتمد على ADF مباشرة لذلك يُعدّ الأهم في تصنيف الأعلاف الخشنة.'},
{q:'بقرة حلاب عليقتها تحتوي 0.45% كالسيوم و0.55% فوسفور على أساس المادة الجافة. أي خطر غذائي تُنذر به هذه النسبة تحديداً؟',
opts:['لا يوجد أي خطر حقيقي لأن الكميتين مناسبتان وقريبتان من الاحتياج القياسي لأبقار الحليب','نسبة الفوسفور أعلى من الكالسيوم مما يُعيق امتصاص الكالسيوم ويُهيئ لحمّى الحليب بعد الولادة','زيادة كلا المعدنَين ستُسبب ترسّباً في الكلى والمفاصل وتُعيق أداء الجهاز التناسلي كلياً','نقص الفوسفور منفرداً هو المشكلة الوحيدة بصرف النظر عن نسبته للكالسيوم في العليقة'],
cor:1,exp:'النسبة المثالية كالسيوم:فوسفور في علائق الأبقار الحلاب 1.5-2:1. هنا انقلبت النسبة تماماً — الفوسفور (0.55%) أعلى من الكالسيوم (0.45%). الفوسفور الزائد نسبياً يُثبّط امتصاص الكالسيوم من الأمعاء الدقيقة ويُضاعف خطر نقص كالسيوم الدم (حمّى الحليب) الذي يظهر في الأيام الأولى بعد الولادة. التصحيح بسيط: رفع مصادر الكالسيوم (كربونات الكالسيوم أو حجر الجير) حتى تعود النسبة لمكانها.'},
{q:'لماذا تستطيع المجترة استخلاص طاقة كافية من الأعلاف الخشنة الغنية بالسيليلوز بينما تعجز عن ذلك الدواجن بنفس الكفاءة؟',
opts:['لأن الكرش يحتضن مليارات من الكائنات الدقيقة التي تُنتج إنزيمات تُحلّل السيليلوز وتُنتج الأحماض الدهنية المتطايرة','لأن المجترة تمتلك أسناناً أقوى وقدرة على إعادة المضغ تُكسر بها الألياف الخشنة ميكانيكياً','لأن المجترة تشرب كميات هائلة من الماء تُسرّع تحلّل الألياف كيميائياً في الجهاز الهضمي','لأن المجترة تُنتج كميات أكبر من اللعاب القلوي الذي يُحلّل الألياف قبل وصولها للمعدة'],
cor:0,exp:'الكرش منظومة تخمير حيوية لا مثيل لها: تتكاثر فيه بكتيريا من فصيلة Firmicutes و Bacteroidetes تُنتج إنزيم السيليولاز القادر على كسر الرابطة β-1,4 الجلوكوزية التي لا يستطيع أي جهاز هضمي ثديي إنتاجها ذاتياً. الأحماض الدهنية المتطايرة الناتجة (خلّي، بروبيوني، بوتيريكي) تُمثّل 60-80% من الطاقة اليومية للمجترة. الدواجن لا تمتلك هذا النظام إطلاقاً فلا تستفيد من السيليلوز.'},
{q:'ما الهدف الجوهري من نظام التغذية بالعليقة الكاملة الممزوجة (TMR) في مزارع أبقار الحليب بالمقارنة مع التغذية المنفصلة؟',
opts:['تقليل الكمية الإجمالية المُقدَّمة يومياً للبقرة عن طريق رفع الكثافة الغذائية لكل كيلوجرام','ضمان حصول كل رأس على نسب متوازنة في كل قضمة ومنع انتقاء مكونات بعينها من العليقة','تسهيل عمليات التوزيع اليومية وتقليل عدد العمال اللازمين لتشغيل الحظيرة بشكل كامل','تبسيط خطة التغذية السنوية حتى يتمكن المربي المبتدئ من تطبيقها دون استشارة متخصص'],
cor:1,exp:'جوهر TMR منع الانتقاء الانتقائي (Selective Sorting) — إذا قُدِّمت مكونات العليقة منفصلة، أكلت الأبقار ذات المرتبة الاجتماعية العليا الجزء المركّز أولاً وتركت الخشن، فاضطربت نسبة العلف الخشن/المركز في الكرش وتفاوتت حموضته. TMR يُقدّم الخشن والمركز والإضافات معاً في قضمة واحدة متجانسة، فيثبت pH الكرش ويُوزَّع التغذية بعدالة على القطيع. الفوائد الثانوية: تحسين استهلاك العلف وتقليل تذبذب الإنتاج.'},
{q:'لماذا يبدأ برنامج تسمين العجول بعليقة بادئة منخفضة التركيز ثم ينتقل تدريجياً للعليقة الكاملة على مدى 3-4 أسابيع؟',
opts:['لأن العجول الصغيرة لا تستطيع هضم النشا من الحبوب إطلاقاً قبل بلوغها 250 كجم من وزنها','لتهيئة الميكروبيوم الكرشي وخلايا جدار الكرش تدريجياً لمعالجة النشا وتجنب الحماض الكرشي','لأن العليقة عالية التركيز أغلى بكثير وتأجيلها يُقلّل تكلفة مرحلة البداية اقتصادياً فقط','لأن الانتقال المفاجئ يزيد إنتاج اللعاب بشكل مفرط فيُضعف تركيز الكرش الرئيسي بالكامل'],
cor:1,exp:'كرش العجل عند الفطام لم يكتمل تطوّره ولا يحمل الكائنات الدقيقة الكافية لمعالجة النشا المرتفع. التدرج يُتيح للبكتيريا اللاكتوباسيلية والبروبيونية التكاثر والتكيّف، ويُحفّز نمو حليمات جدار الكرش (Papillae) الضرورية للامتصاص الجيد للأحماض الدهنية. الانتقال المفاجئ ينتج أحماضاً تتجاوز قدرة الامتصاص فينخفض pH الكرش تحت 5.6 ويحدث الحماض الكرشي الحاد مع توقف الشهية وتراجع حاد في النمو.'},
{q:'ما الهدف الفسيولوجي من تقنية Flushing للنعاج قبل موسم التزاوج وما التوقيت الأنسب لتطبيقها؟',
opts:['رفع إنتاج الحليب في الأسابيع الأولى بعد الولادة لضمان نمو أفضل للحملان في العمر المبكر','تحفيز زيادة معدل التبويض عن طريق رفع مستوى الطاقة في الدم قبل التزاوج بثلاثة إلى أربعة أسابيع','منع التهاب الرحم بعد الولادة عن طريق رفع مستوى المناعة من خلال التغذية الجيدة والمتوازنة','تقليل خطر الإجهاض عن طريق رفع مستوى السيلينيوم وفيتامين E في دم النعاج الحوامل'],
cor:1,exp:'Flushing يعتمد على علاقة مثبتة: رفع الجلوكوز في الدم عبر تدعيم الطاقة يُحفّز الغدة النخامية لإفراز FSH بكميات أعلى، مما يُنضج بويضات إضافية ويرفع معدل التبويض (Ovulation Rate). نعجة تُبيَّض بويضتين بدلاً من واحدة تضع توأمَين وهذا ضعف الإنتاج بنفس رأس القطيع. التوقيت: 3-4 أسابيع قبل الإدخال واستمرار الأسبوعين التاليين. جرعة 300-500 جرام مركزة إضافية فوق الاحتياج اليومي للصيانة.'},
{q:'لماذا ينخفض تركيز البروتين في علف الدجاج اللاحم من مرحلة البادئ (22-24%) إلى مرحلة الناهي (18-19%)؟',
opts:['لأن الجهاز الهضمي في الطائر يُصبح أقل كفاءة كلما تقدّم في العمر فيحتاج بروتيناً أسهل هضماً','لأن البروتين المرتفع في مرحلة الناهي يُسبب فشلاً كلوياً مزمناً ويرفع نسبة النفوق الأسبوعية','لأن الطيور الكبيرة ترفض العلف عالي البروتين بشكل سلوكي ولا تتناوله في حالات التغذية الحرة','لأن احتياج الطائر النسبي للبروتين يتراجع مع النمو وتصبح الطاقة الأهم اقتصادياً في مرحلة التسمين'],
cor:3,exp:'الطائر الصغير يُجنّد كل طاقته لبناء العضلات والأنسجة بسرعة — البروتين هو المحدّد في هذه المرحلة. مع نمو الجسم يقلّ الاحتياج النسبي للبروتين كنسبة من الوزن الحيّ ويُصبح التسمين (ترسيب الدهون وإكمال الوزن) الأولوية. تخفيض البروتين في الناهي يُقلّل التكلفة (كسب الصويا أغلى من الذرة) ويُحسّن FCR ويُقلّل النيتروجين في الفضلات ذي الأثر البيئي السلبي.'},
{q:'مزرعة تُضيف مستخلصات المانان أوليجوساكرايد (MOS) لعليقة كتاكيت الأسبوع الأول. إلى أي فئة من فئات إضافات الأعلاف تنتمي هذه المادة وما آلية عملها؟',
opts:['بروبيوتيك — كائنات حية دقيقة مفيدة تُضاف للعليقة لتستعمر الأمعاء وتُحسّن التخمر الميكروبي','مثبط ميثان — يُقلّل انبعاثات الغاز المُنتَج في أمعاء الطيور الصغيرة خلال أسابيع النمو الأولى','بريبايوتيك — مركب غير حي يُغذّي الفلورا المعوية المفيدة ويُعيق التصاق الممرضات بجدار الأمعاء','منظّم حموضة — يخفض pH الأمعاء ليُشكّل بيئة مُعادية للبكتيريا الممرضة مثل السالمونيلا'],
cor:2,exp:'MOS ليست كائناً حياً (فليست بروبيوتيك) — هي سكّر معقد مُشتَق من جدار خلية خميرة Saccharomyces cerevisiae. تُغذّي البكتيريا المفيدة الموجودة في الأمعاء (تعريف البريبايوتيك)، وتحمل ميزةً إضافية: ترتبط ببكتيريا ممرضة كالسالمونيلا والإشريكية القولونية التي تمتلك مستقبلات مانوز على سطحها، فتمنع التصاقها بجدار الأمعاء وتُسهّل إخراجها مع الفضلات.'},
{q:'لماذا يُعدّ ارتفاع نسبة رطوبة الأعلاف المركزة فوق 14% في التخزين أمراً بالغ الخطورة حتى لو بدا العلف سليماً في المظهر؟',
opts:['لأن الفطريات تنشط فوق هذا الحد وتُنتج سموماً خفية ودورات تسخين داخلية تُتلف المغذيات','لأن الرطوبة الزائدة تُسبب ذوبان المعادن وتُفقد العليقة توازنها دون أن يتغيّر مظهرها الخارجي','لأن المياه الزائدة في العلف تُغرق الكائنات الدقيقة الهضمية في كرش الحيوان عند الاستهلاك','لأن رطوبة العلف تُسبب تراجعاً في FCR ميكانيكياً بسبب الوزن الإضافي غير الغذائي للماء'],
cor:0,exp:'فوق 14% رطوبة تنشط الفطريات (Aspergillus, Fusarium, Penicillium) وتستهلك النشا والبروتين وتُنتج سموماً فطرية صامتة كالأفلاتوكسين B1 الذي لا يتغيّر مذاقه ولا رائحته. في نفس الوقت تنشأ نقاط تسخين داخلية (Hot Spots) من التنفس الميكروبي تُسرّع تحلّل الدهون والفيتامينات. العلف قد يبدو عادياً من الخارج بينما قيمته الغذائية تتراجع يومياً. الحل الوقائي: قياس الرطوبة عند الاستلام وعند التخزين.'},
{q:'ما الفرق بين الطاقة الأيضية (ME) والطاقة الصافية للإنتاج (NEL) وأيهما أدق للتعبير عن احتياجات الأبقار الحلاب؟',
opts:['ME تُحسَب بحرق العلف في مفرمة حرارية، وNEL تُحسَب بتحليل عيّنات الدم في المختبر المتخصص','كلا المصطلحَين مترادفان تماماً ولا فرق عملي أو حسابي بينهما في تطبيقات التغذية الميدانية','ME تشمل ما يُفقد في البول والغازات، وNEL تستبعد الفقد الحراري أيضاً فتُعبّر عمّا يصل للإنتاج','NEL تُستخدَم فقط في الدول الأوروبية بينما ME معيار NASEM الأمريكي الذي يُطبَّق عالمياً'],
cor:2,exp:'الطاقة الكلية (GE) تُطرح منها خسائر البراز = الطاقة القابلة للهضم (DE). طرح الغازات والبول = الطاقة الأيضية (ME). طرح الحرارة الناتجة عن الهضم والأيض (Heat Increment) = الطاقة الصافية (NE). NEL هي الجزء الذي يتبقى حقاً للإنتاج من الحليب. تقدير احتياجات الأبقار الحلاب بـNEL أدق لأنه يُحسب بعد كل الخسائر، وجداول NASEM 2021 تعتمده معياراً أساسياً في كل حسابات الألبان.'},
{q:'ما الحماض الكرشي تحت الإكلينيكي (SARA) وما الذي يجعل تشخيصه أصعب بكثير من الحماض الكرشي الحاد؟',
opts:['هو تسمم دم بالحمض الناتج عن قصور كلوي ويصعب تشخيصه لغياب أي أعراض مرئية على الإطلاق','هو انخفاض مستمر لـpH دون 4.5 مع توقف تام للحركة الكرشية وتورم ملحوظ في منطقة البطن','هو ارتفاع pH الكرش فوق 7.5 بسبب زيادة اليوريا ويصعب تشخيصه لمشابهته لأعراض التسمم الحملي','هو انخفاض متقطع لـpH الكرش دون 5.8 بدون أعراض حادة واضحة مما يجعله صامتاً وخفياً'],
cor:3,exp:'SARA يختلف عن الحماض الحاد في الديناميكية: pH الكرش يهبط دون 5.8 بشكل متقطع لساعات يومياً ثم يعود. لا توقف ظاهر للحركة الكرشية ولا رغوة ولا بروز واضح. المربي يلاحظ تراجعاً تدريجياً في الإنتاج وتذبذباً في دهون الحليب وتناقصاً في الشهية. السبب: النشا المفاجئ يُنتج حمضاً أسرع مما يستطيع الكرش استيعابه. الوقاية: تدرّج التغذية، مساحة معلفة كافية، إضافة بيكربونات الصوديوم منظّم pH.'},
{q:'مصنع أعلاف دواجن أضاف إنزيم الفيتاز لعليقته (500 طن/أسبوع). قلّل ثنائي فوسفات الكالسيوم (DCP) من 9 كجم/طن إلى 3 كجم/طن. سعر DCP = 14 جنيه/كجم، تكلفة الفيتاز = 18 جنيه/طن. ما صافي التوفير الأسبوعي؟',
opts:['21,000 جنيه أسبوعياً بعد خصم تكلفة الفيتاز من قيمة DCP الموفّرة في 500 طن أسبوعياً','33,000 جنيه أسبوعياً وهو صافي التوفير الفعلي بعد خصم تكلفة الإنزيم من قيمة DCP الموفَّرة','42,000 جنيه أسبوعياً وهو إجمالي قيمة DCP الموفَّرة قبل أي خصم لتكاليف الإنزيم المضاف','9,000 جنيه أسبوعياً وهو الفرق المباشر بين تكلفة الإنزيم وتكلفة DCP المخفّضة الجديدة'],
cor:1,exp:'توفير DCP للطن = (9-3) × 14 = 84 جنيه/طن. تكلفة الفيتاز = 18 جنيه/طن. صافي التوفير/طن = 84 - 18 = 66 جنيه/طن. × 500 طن/أسبوع = 33,000 جنيه/أسبوع. يُظهر هذا المثال أن الإضافات الجيدة ذات مردودية اقتصادية حقيقية: تكلفة الفيتاز 9,000 جنيه/أسبوع توفّر 42,000 جنيه من DCP، أي عائد يُعادل 4.6 ضعف التكلفة. هذا هو منطق قرار الإضافة: لا تُقيَّم بالتكلفة وحدها بل بصافي العائد.'},
{q:'مزرعة أغنام 200 رأس (1.5 كجم علف/رأس/يوم، سعر 5,000 جنيه/طن) تفقد 9% من علفها عبر معالف غير مناسبة. ما الفاقد الشهري؟',
opts:['2,025 جنيه شهرياً وهو الفاقد اليومي 67.5 جنيه مضروباً في 30 يوماً بسعر الطن الحالي','8,100 جنيه شهرياً وهو الفاقد 54 كجم/يوم × 5 جنيه/كجم × 30 يوماً بنسبة مضاعفة','4,050 جنيه شهرياً وهو الفاقد 27 كجم/يوم × 5 جنيه/كجم × 30 يوماً بالحساب الصحيح','6,750 جنيه شهرياً وهو الفاقد 45 كجم/يوم × 5 جنيه/كجم × 30 يوماً بنسبة 15%'],
cor:2,exp:'الاستهلاك الكلي = 200 × 1.5 = 300 كجم/يوم. الفاقد = 300 × 9% = 27 كجم/يوم. سعر الكجم = 5,000 ÷ 1,000 = 5 جنيه. الخسارة اليومية = 27 × 5 = 135 جنيه. الخسارة الشهرية = 135 × 30 = 4,050 جنيه. هذا المبلغ يكفي لتمويل تصميم معالف جديدة مناسبة تسترد تكلفتها في أشهر قليلة. الرقم ينبّه أن كل تحسين ميداني بسيط له عائد اقتصادي محسوب وليس مجرد ترفٍ إداري.'},
{q:'مزرعة دجاج لاحم: العليقة سليمة، الصحة طيبة، الكثافة مناسبة، التهوية ممتازة — لكن FCR = 2.10 في الأسبوع الرابع (معيار 1.88). ما الخطوة التشخيصية المنطقية التالية وفق الإطار الخماسي؟',
opts:['تغيير سلالة الطيور في الدورة القادمة لأن FCR المرتفع مرتبط بالوراثة وليس بالإدارة الميدانية','تغيير التركيبة فوراً ورفع البروتين الخام 3% كخطوة احترازية عند أي ارتفاع في معدل التحويل','قياس الفاقد الميداني الفعلي: وزن ما يتطاير وينسكب أثناء ملء المعالف وعبرها يومياً','إيقاف الإنتاج كلياً ومراجعة جميع السجلات منذ بداية الدورة قبل اتخاذ أي إجراء جديد'],
cor:2,exp:'الإطار الخماسي: استُبعدت الصحة والكثافة والتهوية والتركيبة — تبقى محور لم يُفحَص: الفاقد الميداني. FCR = كمية العلف ÷ الإنتاج. إذا كان القسمة صحيحاً فالخطأ في البسط — كمية العلف المُسجَّلة أعلى مما وصل فعلاً للطائر. قياس الفاقد عند الملء وعبر المعلفة وفي الليل (قوارض) يُجيب عن هذا السؤال مباشرةً. التغيير العشوائي للتركيبة قبل هذه الخطوة مكلف وغالباً لا يحل المشكلة الحقيقية.'},
{q:'قطيع أبقار حلاب يُسجَّل فيه تراجع نسبة الحمل عند التلقيح الاصطناعي من 65% إلى 38% خلال موسمَين متتاليَين مع تراجع BCS متوسط القطيع من 3.25 إلى 2.50 في نفس الفترة. ما الارتباط التغذوي الأرجح بين هذَين المؤشرَين؟',
opts:['لا ارتباط تغذوي قائم بين BCS ونسبة الحمل لأن الخصوبة تُحدّدها الوراثة حصراً دون تدخل التغذية','BCS المنخفض يزيد إنتاج الحليب فيرتفع الضغط على المبيض مما يُحسّن التبويض لكن يُقلّل نجاح الحمل','طاقة سلبية مزمنة قبل التلقيح أضعفت التبويض وجودة البيضة وأطالت فترة العودة للدورة الجنسية','النسبتان لا تعكسان مشكلة تغذوية حقيقية وانخفاضهما معاً ضمن التذبذب الموسمي الطبيعي المتوقع'],
cor:2,exp:'تراجع BCS من 3.25 إلى 2.50 يُشير لتوازن طاقة سلبي مزمن يمتد قبل وبعد الولادة. الطاقة السلبية تُقلّل تردد نبضات LH (Luteinizing Hormone) التي تُحفّز التبويض، فيتأخر الأول بعد الولادة (Anovulatory Period يطول) ويتراجع جودة البيضة المُنتَجة وسُمك الجدار الرحمي. نسبة حمل 38% مع BCS 2.50 نمط كلاسيكي لهذه المشكلة — والعلاج: رفع كثافة طاقة العليقة في فترة الجفاف وما بعد الولادة المبكرة لتجنب الاستنزاف المفرط من احتياطي الجسم.'}
]};
/* ── Vodafone Cash Payment — Feed Management Course ──────────────
   رقم فودافون كاش: غيّر القيمة أدناه برقمك الفعلي                */

var _FD_VCASH_NUM='01095282573'; /* ← غيّر هنا برقم فودافون كاش */
var _FD_COURSE_PRICE=25;          /* ← السعر بالجنيه              */

/* Returns locally-cached status: 'paid' | 'pending' | 'none' */
function acFdStatus(){
var u=(typeof currentUser!=='undefined'&&currentUser&&currentUser.uid)?currentUser.uid:null;
if(!u)return 'none';
try{
if(localStorage.getItem('nb-feed-mgmt-access__'+u)==='paid')return 'paid';
if(localStorage.getItem('nb-feed-mgmt-pending__'+u)==='true')return 'pending';
}catch(e){}
return 'none';
}
window.acFdStatus=acFdStatus; /* تعريض عالمي — يستخدمه كاروسيل الكورسات في الرئيسية */

/* Async check against Firestore, updates local cache */
function acCheckFdAccess(cb){
var u=(typeof currentUser!=='undefined'&&currentUser&&currentUser.uid)?currentUser.uid:null;
if(!u){cb('none');return;}
var cacheKey='nb-feed-mgmt-access__'+u;
try{if(localStorage.getItem(cacheKey)==='paid'){cb('paid');return;}}catch(e){}
/* Check users/{uid}.paidCourses first */
db.collection('users').doc(u).get().then(function(snap){
var data=snap.exists?snap.data():{};
if(data.paidCourses&&data.paidCourses.indexOf('feed-mgmt')>-1){
try{localStorage.setItem(cacheKey,'paid');}catch(e){}
cb('paid');return;
}
/* Check course_payments for pending/approved */
db.collection('course_payments').where('uid','==',u).get().then(function(qs){
if(qs.empty){cb('none');return;}
var docs=qs.docs.filter(function(d){return d.data().courseId==='feed-mgmt';});
if(!docs.length){cb('none');return;}
var st=docs[0].data().status;
if(st==='approved'){
try{localStorage.setItem(cacheKey,'paid');}catch(e){}
cb('paid');
}else{
try{localStorage.setItem('nb-feed-mgmt-pending__'+u,'true');}catch(e){}
cb('pending');
}
}).catch(function(){cb('none');});
}).catch(function(){cb('none');});
}

function acShowFdPayModal(mode){
var el=document.getElementById('vcash7-overlay');if(!el)return;
var stepPay=document.getElementById('vcash7-step-pay');
var stepPend=document.getElementById('vcash7-step-pending');
document.getElementById('vcash7-number').textContent=_FD_VCASH_NUM;
document.getElementById('vcash7-price-display').textContent=_FD_COURSE_PRICE+' جنيه';
if(mode==='pending'){
stepPay.classList.remove('on');stepPend.classList.add('on');
}else{
stepPay.classList.add('on');stepPend.classList.remove('on');
var ph=document.getElementById('vcash7-phone');var rf=document.getElementById('vcash7-ref');
if(ph)ph.value='';if(rf)rf.value='';
var btn=document.getElementById('vcash7-submit-btn');
if(btn){btn.disabled=false;btn.textContent='أرسل طلب التفعيل';}
}
el.classList.add('on');
document.body.classList.add('modal-open');
}

function acCloseFdPayModal(){
var el=document.getElementById('vcash7-overlay');
if(el)el.classList.remove('on');
document.body.classList.remove('modal-open');
}

function acCopyVcash7Num(){
var num=document.getElementById('vcash7-number');if(!num)return;
var val=num.textContent;
if(navigator.clipboard){
navigator.clipboard.writeText(val).then(function(){
if(typeof showToast==='function')showToast('تم نسخ رقم فودافون كاش','ok');
}).catch(function(){});
}else{
try{
var ta=document.createElement('textarea');ta.value=val;
document.body.appendChild(ta);ta.select();
document.execCommand('copy');document.body.removeChild(ta);
if(typeof showToast==='function')showToast('تم نسخ الرقم','ok');
}catch(e){}
}
}

function acSubmitFdPayment(){
var u=(typeof currentUser!=='undefined'&&currentUser&&currentUser.uid)?currentUser.uid:null;
if(!u){if(typeof showToast==='function')showToast('سجّل الدخول أولاً','err');return;}
var phone=(document.getElementById('vcash7-phone').value||'').trim();
var ref=(document.getElementById('vcash7-ref').value||'').trim();
if(!phone||phone.length<10){
if(typeof showToast==='function')showToast('برجاء إدخال رقم الهاتف المُرسِل','err');return;
}
if(!ref||ref.length<10){
if(typeof showToast==='function')showToast('برجاء إدخال رقم هاتفك الشخصي','err');return;
}
var btn=document.getElementById('vcash7-submit-btn');
if(btn){btn.disabled=true;btn.textContent='جاري الإرسال...';}
db.collection('course_payments').add({
uid:u,
email:(currentUser&&currentUser.email)||'',
phone:phone,
transactionRef:ref,
courseId:'feed-mgmt',
amount:_FD_COURSE_PRICE,
currency:'EGP',
status:'pending',
createdAt:firebase.firestore.FieldValue.serverTimestamp()
}).then(function(docRef){
try{localStorage.setItem('nb-feed-mgmt-pending__'+u,'true');}catch(e){}
_acNotifyAdminNewPayment('feed-mgmt',_FD_COURSE_PRICE,docRef.id);
var stepPay=document.getElementById('vcash7-step-pay');
var stepPend=document.getElementById('vcash7-step-pending');
var refDisp=document.getElementById('vcash7-pending-ref-display');
if(refDisp)refDisp.textContent='رقم الطلب: '+docRef.id.substring(0,14)+'…  |  رقم التواصل: '+ref;
if(stepPay)stepPay.classList.remove('on');
if(stepPend)stepPend.classList.add('on');
if(typeof showToast==='function')showToast('تم إرسال طلبك — سيُفعَّل الكورس خلال 24 ساعة','ok');
/* Re-render catalog card if visible */
if(typeof acR==='function'&&typeof AC!=='undefined'&&AC.view==='catalog')acR();
}).catch(function(e){
console.error('[VCash7] code:',e&&e.code,'|',e);
if(btn){btn.disabled=false;btn.textContent='أرسل طلب التفعيل';}
var _msg='خطأ في الإرسال — أعد المحاولة';
if(e&&(e.code==='permission-denied'||e.code==='PERMISSION_DENIED'))
  _msg='خطأ في الصلاحيات — تواصل مع الدعم';
else if(e&&(e.code==='unavailable'||e.code==='deadline-exceeded'||e.code==='network-request-failed'))
  _msg='خطأ في الاتصال — تحقق من الإنترنت وأعد المحاولة';
if(typeof showToast==='function')showToast(_msg,'err');
});
}

window.acCloseFdPayModal=acCloseFdPayModal;
window.acCopyVcash7Num=acCopyVcash7Num;
window.acSubmitFdPayment=acSubmitFdPayment;

