var _PD_COURSE_PRICE=70;          /* ← السعر بالجنيه — مطابق لكورس الميكروبيولوجيا الغذائية */
var _PD_VCASH_NUM='01095282573'; /* ← غيّر هنا برقم فودافون كاش */
var _PD_INSTAPAY_INFO={handle:'',mobile:'01095282573',iban:''}; /* ← يملأها المالك: معرّف/موبايل/IBAN — اترك أي حقل فارغاً لإخفائه */

/* Returns locally-cached status: 'paid' | 'pending' | 'none' */
function acPdStatus(){
var u=(typeof currentUser!=='undefined'&&currentUser&&currentUser.uid)?currentUser.uid:null;
if(!u)return 'none';
try{
if(localStorage.getItem('nb-pd-access__'+u)==='paid')return 'paid';
if(localStorage.getItem('nb-pd-pending__'+u)==='true')return 'pending';
}catch(e){}
return 'none';
}
window.acPdStatus=acPdStatus; /* تعريض عالمي — يستخدمه كاروسيل الكورسات في الرئيسية */

/* Async check against Firestore, updates local cache */
function acCheckPdAccess(cb){
var u=(typeof currentUser!=='undefined'&&currentUser&&currentUser.uid)?currentUser.uid:null;
if(!u){cb('none');return;}
var cacheKey='nb-pd-access__'+u;
try{if(localStorage.getItem(cacheKey)==='paid'){cb('paid');return;}}catch(e){}
/* Check users/{uid}.paidCourses first */
db.collection('users').doc(u).get().then(function(snap){
var data=snap.exists?snap.data():{};
if(data.paidCourses&&data.paidCourses.indexOf('plant-diseases')>-1){
try{localStorage.setItem(cacheKey,'paid');}catch(e){}
cb('paid');return;
}
/* Check course_payments for pending/approved */
db.collection('course_payments').where('uid','==',u).get().then(function(qs){
if(qs.empty){cb('none');return;}
var docs=qs.docs.filter(function(d){return d.data().courseId==='plant-diseases';});
if(!docs.length){cb('none');return;}
var st=docs[0].data().status;
if(st==='approved'){
try{localStorage.setItem(cacheKey,'paid');}catch(e){}
cb('paid');
}else if(st==='rejected'){
try{localStorage.removeItem('nb-pd-pending__'+u);}catch(e){}
cb('rejected',docs[0].data().rejectionNote||'');
}else{
try{localStorage.setItem('nb-pd-pending__'+u,'true');}catch(e){}
cb('pending');
}
}).catch(function(){cb('none');});
}).catch(function(){cb('none');});
}

