/* Self-contained Canvas2D certificate renderer — no external library, no CDN, can't be blocked by CSP/network */

function acWrapLines(ctx,text,maxWidth){
var words=text.split(' ');var lines=[];var cur='';
for(var i=0;i<words.length;i++){
var test=cur?cur+' '+words[i]:words[i];
if(ctx.measureText(test).width>maxWidth&&cur){lines.push(cur);cur=words[i]}
else{cur=test}}
if(cur)lines.push(cur);
return lines}

function acDrawRibbonOnCanvas(ctx,ox,oy,size,logoImg){
var s=size/200;
function px(x){return ox+x*s}
function py(y){return oy+y*s}
ctx.save();
ctx.fillStyle='#143d26';ctx.strokeStyle='#c9971f';ctx.lineWidth=1.5*s;
ctx.beginPath();
[[78,150],[100,156],[95,266],[75,238],[56,244],[67,170]].forEach(function(p,i){i===0?ctx.moveTo(px(p[0]),py(p[1])):ctx.lineTo(px(p[0]),py(p[1]))});
ctx.closePath();ctx.fill();ctx.stroke();
ctx.fillStyle='#1e5c39';
ctx.beginPath();
[[122,150],[100,156],[105,266],[125,238],[144,244],[133,170]].forEach(function(p,i){i===0?ctx.moveTo(px(p[0]),py(p[1])):ctx.lineTo(px(p[0]),py(p[1]))});
ctx.closePath();ctx.fill();ctx.stroke();
var starPts=[[100,15],[115,39],[140,25.7],[141,54],[169.3,55],[156,80],[180,95],[156,110],[169.3,135],[141,136],[140,164.3],[115,151],[100,175],[85,151],[60,164.3],[59,136],[30.7,135],[44,110],[20,95],[44,80],[30.7,55],[59,54],[60,25.7],[85,39]];
var starGrad=ctx.createLinearGradient(px(20),py(15),px(180),py(175));
starGrad.addColorStop(0,'#f6d98a');starGrad.addColorStop(1,'#c9971f');
ctx.fillStyle=starGrad;
ctx.beginPath();
starPts.forEach(function(p,i){i===0?ctx.moveTo(px(p[0]),py(p[1])):ctx.lineTo(px(p[0]),py(p[1]))});
ctx.closePath();ctx.fill();
var r=54*s,cx=px(100),cy=py(95);
ctx.save();
ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.clip();
if(logoImg){
ctx.drawImage(logoImg,cx-r,cy-r,r*2,r*2);
}else{
var circGrad=ctx.createRadialGradient(px(81),py(75),5*s,px(100),py(95),54*s);
circGrad.addColorStop(0,'#3fa869');circGrad.addColorStop(.55,'#1f6e42');circGrad.addColorStop(1,'#123b25');
ctx.fillStyle=circGrad;ctx.fillRect(cx-r,cy-r,r*2,r*2);
}
ctx.restore();
ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);
ctx.strokeStyle='rgba(255,255,255,.4)';ctx.lineWidth=2*s;ctx.stroke();
ctx.restore()}

function acDrawCertCanvas(name,dateStr,logoImg){
var W=2200,H=1460,M=82;
var c=document.createElement('canvas');
c.width=W;c.height=H;
var ctx=c.getContext('2d');
ctx.fillStyle='#dbe4dd';ctx.fillRect(0,0,W,H);
var cx0=M,cy0=M,cw=W-2*M,ch=H-2*M;
ctx.fillStyle='#ffffff';ctx.fillRect(cx0,cy0,cw,ch);
ctx.strokeStyle='#84958d';ctx.lineWidth=3;ctx.strokeRect(cx0+1.5,cy0+1.5,cw-3,ch-3);
ctx.save();ctx.beginPath();ctx.rect(cx0,cy0,cw,ch);ctx.clip();
ctx.save();ctx.globalAlpha=.055;ctx.fillStyle='#1f5c39';
ctx.font="600 1180px 'Cormorant Garamond', serif";
ctx.textAlign='center';ctx.textBaseline='middle';
ctx.fillText('N',cx0+cw*0.78,cy0+ch*0.52);
ctx.restore();
var padX=128,padTop=118;
var contentLeft=cx0+padX,contentRight=cx0+cw-padX,contentTop=cy0+padTop;
acDrawRibbonOnCanvas(ctx,contentLeft,contentTop,210,logoImg);
var textLeft=contentLeft+210+80,textRight=contentRight;
var textCenterX=(textLeft+textRight)/2,textWidth=textRight-textLeft;
var y=contentTop+10;
ctx.textBaseline='alphabetic';ctx.textAlign='left';ctx.fillStyle='#33453f';
ctx.font="600 92px 'Cormorant Garamond', serif";
y+=80;ctx.fillText('CERTIFICATE OF',textLeft,y);
var certCourse=acCertCourseInfo(AC_CID);
y+=100;ctx.fillText(certCourse.en,textLeft,y);
y+=100;ctx.fillText('NABTEX PLATFORM',textLeft,y);
y+=70;ctx.font="400 36px 'Cairo', sans-serif";ctx.fillStyle='#5e6f69';
ctx.fillText('This certificate is proudly presented to',textLeft,y);
y+=110;
var safeName=(name&&name.trim())?name.trim():'Your Name';
var nameFontSize=140;
ctx.font="400 "+nameFontSize+"px 'Mrs Saint Delafield', cursive";
var nameWidth=ctx.measureText(safeName).width;
var maxNameWidth=textWidth*0.96;
while(nameWidth>maxNameWidth&&nameFontSize>56){
nameFontSize-=4;
ctx.font="400 "+nameFontSize+"px 'Mrs Saint Delafield', cursive";
nameWidth=ctx.measureText(safeName).width}
ctx.fillStyle='#1f5c39';ctx.textAlign='left';
ctx.fillText(safeName,textLeft,y);
ctx.strokeStyle='#c6d2cb';ctx.lineWidth=2;
ctx.beginPath();ctx.moveTo(textLeft,y+24);ctx.lineTo(textLeft+Math.max(nameWidth,300),y+24);ctx.stroke();
y+=90;
ctx.font="700 42px 'Cairo', sans-serif";ctx.fillStyle='#28352f';ctx.textAlign='left';
var completedLines=acWrapLines(ctx,'has successfully completed the '+certCourse.enFull+' Course offered by Nabtex Platform.',textWidth*0.92);
completedLines.forEach(function(line){y+=58;ctx.fillText(line,textLeft,y)});
y+=50;
ctx.font="700 34px 'Cairo', sans-serif";ctx.fillStyle='#1f5c39';
var recogLines=acWrapLines(ctx,"This certificate is awarded in recognition of the recipient's successful completion of the course and final examination, as well as their commitment to professional development in the field of agriculture.",textWidth*0.95);
recogLines.forEach(function(line){y+=52;ctx.fillText(line,textLeft,y)});
var textBlockBottom=y;
y+=90;ctx.textAlign='left';
var colW=340,col1X=textLeft,col2X=textLeft+colW+110;
ctx.strokeStyle='#84958d';ctx.lineWidth=2;
ctx.beginPath();ctx.moveTo(col1X,y);ctx.lineTo(col1X+colW,y);ctx.stroke();
ctx.beginPath();ctx.moveTo(col2X,y);ctx.lineTo(col2X+colW,y);ctx.stroke();
var footerLineY=y;
y+=46;ctx.font="800 38px 'Cairo', sans-serif";ctx.fillStyle='#28352f';
ctx.fillText('Authorized Signature',col1X,y);ctx.fillText('Date of Issue',col2X,y);
y+=40;ctx.font="400 32px 'Cairo', sans-serif";ctx.fillStyle='#5e6f69';
ctx.fillText('Nabtex Platform',col1X,y);ctx.fillText(dateStr,col2X,y);
var qrSize=170;
var qrX=textRight-qrSize,qrY=Math.max(footerLineY-qrSize+18,textBlockBottom+24);
nbqrDrawOnCanvas(ctx,nbCertVerifyUrl(safeName,dateStr,AC_CID),'M',qrX,qrY,qrSize);
ctx.strokeStyle='#c6d2cb';ctx.lineWidth=1.5;ctx.strokeRect(qrX,qrY,qrSize,qrSize);
ctx.font="700 20px 'Cairo', sans-serif";ctx.fillStyle='#5e6f69';ctx.textAlign='center';
ctx.fillText('Scan to verify',qrX+qrSize/2,qrY+qrSize+30);
ctx.restore();
return c}

function acExportCert(mode,btn){
var nameEl=document.getElementById('acad-cert-name');
if(nameEl&&!nameEl.textContent.trim()){
if(typeof showToast==='function')showToast('✍️ برجاء كتابة الاسم على الشهادة أولاً','inf');
nameEl.focus();return}
var origHTML=btn?btn.innerHTML:null;
if(btn){btn.disabled=true;btn.innerHTML='⏳ ...'}
function restore(){if(btn){btn.disabled=false;btn.innerHTML=origHTML}}
var fontDone=false,logoImg=null,logoDone=false;
function proceedIfReady(){
if(!fontDone||!logoDone)return;
var canvas;
try{canvas=acDrawCertCanvas(nameEl?nameEl.textContent:'',acCertDate(),logoImg)}
catch(e){restore();if(typeof showToast==='function')showToast('⚠️ تعذر إنشاء صورة الشهادة','err');return}
finishExport(canvas)}
acFontsReady(function(){fontDone=true;proceedIfReady()});
acLoadLogoImg(function(img){logoImg=img;logoDone=true;proceedIfReady()});
function finishExport(canvas){
if(mode==='print'){
var dataUrl=canvas.toDataURL('image/png');
restore();
var w=window.open('','_blank');
if(!w){if(typeof showToast==='function')showToast('⚠️ يرجى السماح بالنوافذ المنبثقة لطباعة الشهادة','err');return}
w.document.write('<!DOCTYPE html><html><head><meta charset="utf-8"><title>شهادة نبتيكس أكاديمي</title>'+
'<style>@page{margin:0}html,body{margin:0;padding:0}body{display:flex;align-items:center;justify-content:center;min-height:100vh;background:#fff}img{width:100%;height:auto;display:block;max-width:1100px}</style>'+
'</head><body><img decoding="async" src="'+dataUrl+'" alt="شهادة" onload="setTimeout(function(){window.print()},300)"></body></html>');
w.document.close();
return}
canvas.toBlob(function(blob){
restore();
if(!blob)return;
var fileName='Nabtex-'+(acCertCourseInfo(AC_CID).abbr||acCertCourseInfo(AC_CID).en).replace(/\s+/g,'-')+'-Certificate.png';
var file=null;
try{file=new File([blob],fileName,{type:'image/png'})}catch(e){}
if(mode==='share'&&file&&navigator.share&&navigator.canShare&&navigator.canShare({files:[file]})){
navigator.share({files:[file],title:'شهادة نبتيكس أكاديمي',text:'شهادة إتمام دورة '+acCertCourseInfo(AC_CID).ar+' - نبتيكس أكاديمي'}).catch(function(){})
}else{
var url=URL.createObjectURL(blob);
var a=document.createElement('a');
a.href=url;a.download=fileName;document.body.appendChild(a);a.click();
setTimeout(function(){a.parentNode&&document.body.removeChild(a);URL.revokeObjectURL(url)},1200);
if(typeof showToast==='function')showToast(mode==='share'?'📥 تم تنزيل الشهادة (المشاركة المباشرة غير مدعومة هنا)':'✅ تم تنزيل الشهادة بنجاح','ok')
}
},'image/png')
}}

