var _sp=window.showPage;
window.showPage=function(e,t){
_sp&&_sp.apply(this,arguments);
if(e==='academy'){
 document.getElementById('nl-academy')&&document.getElementById('nl-academy').classList.add('active');
 var r=document.getElementById('acad-root');
 if(r&&!r.firstChild)acR();
 window.AcNotif&&AcNotif._touchActive()}};
var _ap=document.getElementById('pg-academy');
if(_ap)new MutationObserver(function(ms){
ms.forEach(function(m){
 if(m.attributeName==='class'&&_ap.classList.contains('active')){
  document.getElementById('nl-academy')&&document.getElementById('nl-academy').classList.add('active');
  var r=document.getElementById('acad-root');
  if(r&&!r.firstChild)acR();
  window.AcNotif&&AcNotif._touchActive()}})
}).observe(_ap,{attributes:true});

